generator_py:
"""Corner-components to center-components generator for Test2/t1.

The rule matches ``Test2/t1.json``:
- up to four components, one per corner window
- each corner component is translated to the corresponding center window
"""

from __future__ import annotations

import random
from typing import Dict, List, Sequence, Tuple

Grid = List[List[int]]
PixelList = List[Tuple[int, int]]

_CORNERS = ("tl", "tr", "bl", "br")


def _empty(size: int) -> Grid:
    return [[0 for _ in range(size)] for _ in range(size)]


def _corner_span(size: int) -> int:
    # Matches examples: size=10 -> 3, size=12 -> 4.
    return size // 2 - 2


def _origins(size: int) -> Dict[str, Tuple[int, int]]:
    span = _corner_span(size)
    return {
        "tl": (0, 0),
        "tr": (0, size - span),
        "bl": (size - span, 0),
        "br": (size - span, size - span),
    }


def _random_component(rng: random.Random, span: int) -> PixelList:
    # 8-connected component without isolated cells.
    n = rng.randint(2, min(span * span, 8))
    all_cells = {(r, c) for r in range(span) for c in range(span)}
    start = rng.choice(list(all_cells))
    comp = {start}
    while len(comp) < n:
        frontier = set()
        for r, c in comp:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < span and 0 <= cc < span and (rr, cc) not in comp:
                        frontier.add((rr, cc))
        if not frontier:
            break
        comp.add(rng.choice(list(frontier)))
    return sorted(comp)


def _is_8_connected_and_non_isolated(pixels: PixelList) -> bool:
    if len(pixels) < 2:
        return False
    pix = set(pixels)
    seen = set()
    stack = [pixels[0]]
    while stack:
        r, c = stack.pop()
        if (r, c) in seen:
            continue
        seen.add((r, c))
        has_neighbor = False
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                q = (r + dr, c + dc)
                if q in pix:
                    has_neighbor = True
                    if q not in seen:
                        stack.append(q)
        if not has_neighbor:
            return False
    return len(seen) == len(pix)


def generate(
    size: int | None = None,
    present: Sequence[str] | None = None,
    components: Dict[str, PixelList] | None = None,
    colors: Dict[str, int] | None = None,
    rng: random.Random | None = None,
) -> dict[str, Grid]:
    """Returns one ARC-style {"input": ..., "output": ...} pair.

    Args:
      size: square grid size (defaults to random even size in [8, 16]).
      present: subset of {"tl","tr","bl","br"} that contain components.
      components: local (row, col) coordinates per corner inside corner span.
      colors: color per corner.
    """
    rr = rng if rng is not None else random
    if size is None:
        size = rr.choice([8, 10, 12, 14, 16])
    if size < 8 or size % 2 != 0:
        raise ValueError("size must be even and >= 8")

    span = _corner_span(size)
    if span < 2:
        raise ValueError("size too small for this task layout")

    if present is None:
        k = rr.randint(1, 4)
        present = rr.sample(list(_CORNERS), k)
    present_set = set(present)
    if not present_set.issubset(set(_CORNERS)):
        raise ValueError("present must only use tl/tr/bl/br")
    if not present_set:
        raise ValueError("at least one component must be present")

    if components is None:
        components = {corner: _random_component(rr, span) for corner in present_set}
    if colors is None:
        available = [c for c in range(1, 10)]
        chosen = rr.sample(available, len(present_set))
        colors = {corner: col for corner, col in zip(sorted(present_set), chosen)}

    inp = _empty(size)
    out = _empty(size)
    src_o = _origins(size)
    half = size // 2

    by_corner: Dict[str, List[Tuple[int, int, int]]] = {c: [] for c in _CORNERS}
    for corner in sorted(present_set):
        pix = components.get(corner, [])
        if pix and not _is_8_connected_and_non_isolated(pix):
            raise ValueError(f"{corner} component must be 8-connected with no isolated cells")
        color = colors[corner]
        sr, sc = src_o[corner]
        for rr0, cc0 in pix:
            if rr0 < 0 or cc0 < 0 or rr0 >= span or cc0 >= span:
                raise ValueError(f"component pixel {(rr0, cc0)} outside corner span {span}")
            r, c = sr + rr0, sc + cc0
            inp[r][c] = color
            by_corner[corner].append((r, c, color))

    top_cells = by_corner["tl"] + by_corner["tr"]
    bot_cells = by_corner["bl"] + by_corner["br"]
    left_cells = by_corner["tl"] + by_corner["bl"]
    right_cells = by_corner["tr"] + by_corner["br"]

    top_max_r = max((r for r, _, _ in top_cells), default=half - 1)
    bot_min_r = min((r for r, _, _ in bot_cells), default=half)
    left_max_c = max((c for _, c, _ in left_cells), default=half - 1)
    right_min_c = min((c for _, c, _ in right_cells), default=half)

    dr_top = (half - 1) - top_max_r
    dr_bot = half - bot_min_r
    dc_left = (half - 1) - left_max_c
    dc_right = half - right_min_c

    for corner in _CORNERS:
        cells = by_corner[corner]
        if not cells:
            continue
        dr = dr_top if corner in ("tl", "tr") else dr_bot
        dc = dc_left if corner in ("tl", "bl") else dc_right
        for r, c, color in cells:
            out[r + dr][c + dc] = color

    return {"input": inp, "output": out}

"""Generator for Test2/t2: cyclic color shift by leftmost-object order.

Rule:
- detect 8-connected non-zero objects
- sort objects by the position of their leftmost cell (col, then row)
- shift object colors to the right with wrap-around
"""

from __future__ import annotations

import random
from typing import Dict, List, Sequence, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _neighbors8(r: int, c: int) -> list[Cell]:
    out: list[Cell] = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            out.append((r + dr, c + dc))
    return out


def _grow_component(
    rng: random.Random,
    start: Cell,
    target_size: int,
    h: int,
    w: int,
    blocked: set[Cell],
) -> list[Cell]:
    comp = {start}
    while len(comp) < target_size:
        frontier: set[Cell] = set()
        for r, c in comp:
            for rr, cc in _neighbors8(r, c):
                if rr < 0 or cc < 0 or rr >= h or cc >= w:
                    continue
                if (rr, cc) in comp or (rr, cc) in blocked:
                    continue
                frontier.add((rr, cc))
        if not frontier:
            break
        comp.add(rng.choice(list(frontier)))
    return sorted(comp)


def _leftmost_key(cells: Sequence[Cell]) -> tuple[int, int]:
    min_col = min(c for _, c in cells)
    min_row = min(r for r, c in cells if c == min_col)
    return (min_col, min_row)


def _leftmost_col(cells: Sequence[Cell]) -> int:
    return min(c for _, c in cells)


def _shift_colors_right(grid: Grid) -> Grid:
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen: set[Cell] = set()
    objs: list[list[Cell]] = []
    colors: list[int] = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            comp: list[Cell] = []
            while stack:
                rr, cc = stack.pop()
                if (rr, cc) in seen or grid[rr][cc] != color:
                    continue
                seen.add((rr, cc))
                comp.append((rr, cc))
                for nr, nc in _neighbors8(rr, cc):
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and (nr, nc) not in seen
                        and grid[nr][nc] == color
                    ):
                        stack.append((nr, nc))
            objs.append(comp)
            colors.append(color)
    if len(objs) <= 1:
        return [list(row) for row in grid]

    order = sorted(range(len(objs)), key=lambda i: _leftmost_key(objs[i]))
    out = _empty(h, w)
    for pos, obj_idx in enumerate(order):
        src_idx = order[pos - 1]  # right-shift with wrap-around
        new_color = colors[src_idx]
        for r, c in objs[obj_idx]:
            out[r][c] = new_color
    return out


def generate(
    width: int | None = None,
    height: int | None = None,
    object_count: int | None = None,
    objects: Sequence[Sequence[Cell]] | None = None,
    colors: Sequence[int] | None = None,
    rng: random.Random | None = None,
) -> dict[str, Grid]:
    """Return one input/output pair for the t2 rule."""
    rr = rng if rng is not None else random
    if width is None:
        width = rr.randint(8, 14)
    if height is None:
        height = rr.randint(8, 14)
    if width < 6 or height < 6:
        raise ValueError("width/height must be >= 6")

    if objects is None:
        if object_count is None:
            object_count = rr.randint(2, 5)
        if object_count < 2:
            raise ValueError("need at least 2 objects for color shifting")
        max_layout_attempts = 120
        objects = None
        for _ in range(max_layout_attempts):
            blocked: set[Cell] = set()
            built: list[list[Cell]] = []
            attempts = 0
            max_attempts = 4000
            while len(built) < object_count and attempts < max_attempts:
                attempts += 1
                r0 = rr.randint(0, height - 1)
                c0 = rr.randint(0, width - 1)
                if (r0, c0) in blocked:
                    continue
                size = rr.randint(2, 8)
                comp = _grow_component(rr, (r0, c0), size, height, width, blocked)
                if len(comp) < 2:
                    continue
                # Reserve 8-neighborhood halo so objects stay distinct.
                halo = set(comp)
                for r, c in comp:
                    for nr, nc in _neighbors8(r, c):
                        if 0 <= nr < height and 0 <= nc < width:
                            halo.add((nr, nc))
                blocked.update(halo)
                built.append(comp)
            if len(built) < object_count:
                continue
            # No ties on leftmost position criterion shown in provided examples:
            # require strictly unique leftmost columns across objects.
            left_cols = [_leftmost_col(comp) for comp in built]
            if len(set(left_cols)) != len(left_cols):
                continue
            objects = built
            break
        if objects is None:
            raise RuntimeError("could not sample non-tied objects by leftmost-column order")
    else:
        if len(objects) < 2:
            raise ValueError("objects must contain at least 2 objects")
        left_cols = [_leftmost_col(comp) for comp in objects]
        if len(set(left_cols)) != len(left_cols):
            raise ValueError("objects must have unique leftmost columns (no ordering ties)")

    if colors is None:
        colors = rr.sample([1, 2, 3, 4, 5, 6, 7, 8, 9], len(objects))
    if len(colors) != len(objects):
        raise ValueError("colors length must equal objects length")

    inp = _empty(height, width)
    for comp, col in zip(objects, colors):
        for r, c in comp:
            if r < 0 or c < 0 or r >= height or c >= width:
                raise ValueError("object cell outside grid")
            inp[r][c] = int(col)
    out = _shift_colors_right(inp)
    return {"input": inp, "output": out}

verifier_py:
"""Verifier for Test2/t2 color-shift-by-leftmost-object rule."""

from __future__ import annotations

from typing import List, Sequence, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]


def _neighbors8(r: int, c: int) -> list[Cell]:
    out: list[Cell] = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            out.append((r + dr, c + dc))
    return out


def _leftmost_key(cells: Sequence[Cell]) -> tuple[int, int]:
    min_col = min(c for _, c in cells)
    min_row = min(r for r, c in cells if c == min_col)
    return (min_col, min_row)


def verify_t2(grid: Grid) -> Grid:
    h = len(grid)
    w = len(grid[0]) if h else 0
    if h == 0 or w == 0:
        return []

    seen: set[Cell] = set()
    objs: list[list[Cell]] = []
    colors: list[int] = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            comp: list[Cell] = []
            while stack:
                rr, cc = stack.pop()
                if (rr, cc) in seen or grid[rr][cc] != color:
                    continue
                seen.add((rr, cc))
                comp.append((rr, cc))
                for nr, nc in _neighbors8(rr, cc):
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and (nr, nc) not in seen
                        and grid[nr][nc] == color
                    ):
                        stack.append((nr, nc))
            objs.append(comp)
            colors.append(color)

    if len(objs) <= 1:
        return [list(row) for row in grid]

    order = sorted(range(len(objs)), key=lambda i: _leftmost_key(objs[i]))
    out: Grid = [[0 for _ in range(w)] for _ in range(h)]
    for pos, obj_idx in enumerate(order):
        src_idx = order[pos - 1]  # shift right with wrap
        col = colors[src_idx]
        for r, c in objs[obj_idx]:
            out[r][c] = col
    return out

generator_py:
"""Generator for Test2/t4 scaled-rectangle task."""

from __future__ import annotations

import random
from typing import List

Grid = List[List[int]]

RED = 2


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _neighbors4(r: int, c: int) -> list[tuple[int, int]]:
    return [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]


def _neighbors8(r: int, c: int) -> list[tuple[int, int]]:
    out: list[tuple[int, int]] = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            out.append((r + dr, c + dc))
    return out


def _find_sub_rectangles(cells: set[tuple[int, int]]) -> list[set[tuple[int, int]]]:
    """Greedily decompose into mergeable 4-neighbor rectangles of size 9/6/4/2."""
    remaining = set(cells)
    groups: list[set[tuple[int, int]]] = []

    def all_rectangles_of_size(target: int) -> list[set[tuple[int, int]]]:
        out: list[set[tuple[int, int]]] = []
        rows = [r for r, _ in remaining]
        cols = [c for _, c in remaining]
        if not rows or not cols:
            return out
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)
        for r0 in range(min_r, max_r + 1):
            for c0 in range(min_c, max_c + 1):
                max_h = max_r - r0 + 1
                max_w = max_c - c0 + 1
                for h in range(1, max_h + 1):
                    for w in range(1, max_w + 1):
                        if h * w != target:
                            continue
                        cand = {(r, c) for r in range(r0, r0 + h) for c in range(c0, c0 + w)}
                        if cand.issubset(remaining):
                            out.append(cand)
        out.sort(key=lambda s: (min(r for r, _ in s), min(c for _, c in s)))
        return out

    while remaining:
        picked: set[tuple[int, int]] | None = None
        for size in (9, 6, 4, 2):
            candidates = all_rectangles_of_size(size)
            if candidates:
                picked = candidates[0]
                break
        if picked is None:
            # Unmergeable cell becomes a singleton rectangle.
            r, c = min(remaining)
            picked = {(r, c)}
        groups.append(picked)
        remaining -= picked
    return groups


def _color_groups_4n_rectangular(ref_cells: Grid) -> list[tuple[int, set[tuple[int, int]]]]:
    """Group same-color descriptor cells via 4-neighborhood, then rectangular merge rules."""
    h = len(ref_cells)
    w = len(ref_cells[0]) if h else 0
    seen: set[tuple[int, int]] = set()
    groups: list[tuple[int, set[tuple[int, int]]]] = []
    for r in range(h):
        for c in range(w):
            color = ref_cells[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp: set[tuple[int, int]] = set()
            while stack:
                cr, cc = stack.pop()
                comp.add((cr, cc))
                for nr, nc in _neighbors4(cr, cc):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                        if ref_cells[nr][nc] == color:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            for part in _find_sub_rectangles(comp):
                groups.append((color, part))
    return groups


def _reference_corner(ref_top: int, ref_left: int, h: int, w: int) -> tuple[str, str]:
    vertical = "top" if ref_top == 0 else "bottom"
    horizontal = "left" if ref_left == 0 else "right"
    return vertical, horizontal


def _render_output(
    ref_cells: Grid,
    h: int,
    w: int,
    ref_top: int,
    ref_left: int,
) -> Grid:
    if h % 3 != 0 or w % 3 != 0:
        raise ValueError("grid dimensions must be divisible by 3")
    bh = h // 3
    bw = w // 3
    out = _empty(h, w)
    ref_vertical, ref_horizontal = _reference_corner(ref_top, ref_left, h, w)

    for color, comp in _color_groups_4n_rectangular(ref_cells):
        rows = [r for r, _ in comp]
        cols = [c for _, c in comp]
        r0, r1 = min(rows), max(rows)
        c0, c1 = min(cols), max(cols)
        comp_h = r1 - r0 + 1
        comp_w = c1 - c0 + 1

        top = r0 * bh
        left = c0 * bw
        rect_h = comp_h * bh
        rect_w = comp_w * bw

        # Outline in component color.
        for cc in range(left, left + rect_w):
            out[top][cc] = color
            out[top + rect_h - 1][cc] = color
        for rr in range(top + 1, top + rect_h - 1):
            out[rr][left] = color
            out[rr][left + rect_w - 1] = color

        # Interior is split into 4 regions; red occupies the quadrant of ref corner.
        inner_top = top + 1
        inner_left = left + 1
        inner_h = rect_h - 2
        inner_w = rect_w - 2
        half_h = inner_h // 2
        half_w = inner_w // 2
        row_start = inner_top if ref_vertical == "top" else inner_top + half_h
        row_end = inner_top + half_h if ref_vertical == "top" else inner_top + inner_h
        col_start = inner_left if ref_horizontal == "left" else inner_left + half_w
        col_end = inner_left + half_w if ref_horizontal == "left" else inner_left + inner_w
        for rr in range(row_start, row_end):
            for cc in range(col_start, col_end):
                out[rr][cc] = RED

    return out


def _sample_reference_cells(rng: random.Random) -> Grid:
    # 3x3 descriptor inside the red 5x5 reference rectangle.
    cells = _empty(3, 3)
    palette = [1, 3, 4, 5, 6, 7, 8, 9]
    active_count = rng.randint(2, 5)
    coords = [(r, c) for r in range(3) for c in range(3)]
    rng.shuffle(coords)
    for i in range(active_count):
        r, c = coords[i]
        cells[r][c] = rng.choice(palette)

    # Encourage valid mergeable groups (2/4/6/9 cells, 4-neighborhood only).
    if rng.random() < 0.55:
        starts = [(r, c) for r in range(3) for c in range(3)]
        rng.shuffle(starts)
        r, c = starts[0]
        color = rng.choice(palette)
        cells[r][c] = color
        orient = rng.choice(["h", "v", "sq", "h6", "v6", "sq9"])
        if orient == "h" and c + 1 < 3:
            cells[r][c + 1] = color
        elif orient == "v" and r + 1 < 3:
            cells[r + 1][c] = color
        elif orient == "sq" and r + 1 < 3 and c + 1 < 3:
            cells[r + 1][c] = color
            cells[r][c + 1] = color
            cells[r + 1][c + 1] = color
        elif orient == "h6":
            rr = rng.choice([0, 1])
            for cc in range(3):
                cells[rr][cc] = color
                cells[rr + 1][cc] = color
        elif orient == "v6":
            cc = rng.choice([0, 1])
            for rr in range(3):
                cells[rr][cc] = color
                cells[rr][cc + 1] = color
        elif orient == "sq9":
            for rr in range(3):
                for cc in range(3):
                    cells[rr][cc] = color
    return cells


def generate(
    width: int | None = None,
    height: int | None = None,
    ref_top: int | None = None,
    ref_left: int | None = None,
    ref_cells: Grid | None = None,
    rng: random.Random | None = None,
) -> dict[str, Grid]:
    """Generate one t4 input/output pair."""
    rr = rng if rng is not None else random
    if width is None:
        width = rr.choice([12, 18])
    if height is None:
        height = width
    if width % 3 != 0 or height % 3 != 0:
        raise ValueError("width and height must be divisible by 3")
    if width < 9 or height < 9:
        raise ValueError("width and height must be >= 9")

    if ref_top is None or ref_left is None:
        corner = rr.choice(["ul", "ur", "bl", "br"])
        if ref_top is None:
            ref_top = 0 if corner in ("ul", "ur") else height - 5
        if ref_left is None:
            ref_left = 0 if corner in ("ul", "bl") else width - 5
    if not (0 <= ref_top <= height - 5 and 0 <= ref_left <= width - 5):
        raise ValueError("reference 5x5 rectangle does not fit")
    if ref_top not in (0, height - 5) or ref_left not in (0, width - 5):
        raise ValueError("reference rectangle must sit in a grid corner")

    if ref_cells is None:
        ref_cells = _sample_reference_cells(rr)
    if len(ref_cells) != 3 or any(len(row) != 3 for row in ref_cells):
        raise ValueError("ref_cells must be 3x3")
    if not any(ref_cells[r][c] != 0 for r in range(3) for c in range(3)):
        raise ValueError("ref_cells must contain at least one non-zero cell")
    for r in range(3):
        for c in range(3):
            if ref_cells[r][c] == RED:
                raise ValueError("ref_cells cannot use red (2)")

    inp = _empty(height, width)

    # Draw red 5x5 outline.
    for c in range(ref_left, ref_left + 5):
        inp[ref_top][c] = RED
        inp[ref_top + 4][c] = RED
    for r in range(ref_top + 1, ref_top + 4):
        inp[r][ref_left] = RED
        inp[r][ref_left + 4] = RED

    # Place descriptor cells in the 3x3 interior.
    for r in range(3):
        for c in range(3):
            inp[ref_top + 1 + r][ref_left + 1 + c] = ref_cells[r][c]

    out = _render_output(ref_cells, height, width, ref_top, ref_left)
    return {"input": inp, "output": out}

verifier_py:
"""Verifier for Test2/t4 scaled-rectangle task."""

from __future__ import annotations

from typing import List

Grid = List[List[int]]
RED = 2


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _neighbors4(r: int, c: int) -> list[tuple[int, int]]:
    return [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]


def _neighbors8(r: int, c: int) -> list[tuple[int, int]]:
    out: list[tuple[int, int]] = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            out.append((r + dr, c + dc))
    return out


def _find_sub_rectangles(cells: set[tuple[int, int]]) -> list[set[tuple[int, int]]]:
    remaining = set(cells)
    groups: list[set[tuple[int, int]]] = []

    def all_rectangles_of_size(target: int) -> list[set[tuple[int, int]]]:
        out: list[set[tuple[int, int]]] = []
        rows = [r for r, _ in remaining]
        cols = [c for _, c in remaining]
        if not rows or not cols:
            return out
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)
        for r0 in range(min_r, max_r + 1):
            for c0 in range(min_c, max_c + 1):
                max_h = max_r - r0 + 1
                max_w = max_c - c0 + 1
                for h in range(1, max_h + 1):
                    for w in range(1, max_w + 1):
                        if h * w != target:
                            continue
                        cand = {(r, c) for r in range(r0, r0 + h) for c in range(c0, c0 + w)}
                        if cand.issubset(remaining):
                            out.append(cand)
        out.sort(key=lambda s: (min(r for r, _ in s), min(c for _, c in s)))
        return out

    while remaining:
        picked: set[tuple[int, int]] | None = None
        for size in (9, 6, 4, 2):
            candidates = all_rectangles_of_size(size)
            if candidates:
                picked = candidates[0]
                break
        if picked is None:
            picked = {min(remaining)}
        groups.append(picked)
        remaining -= picked
    return groups


def _color_groups_4n_rectangular(ref_cells: Grid) -> list[tuple[int, set[tuple[int, int]]]]:
    h = len(ref_cells)
    w = len(ref_cells[0]) if h else 0
    seen: set[tuple[int, int]] = set()
    groups: list[tuple[int, set[tuple[int, int]]]] = []
    for r in range(h):
        for c in range(w):
            color = ref_cells[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp: set[tuple[int, int]] = set()
            while stack:
                cr, cc = stack.pop()
                comp.add((cr, cc))
                for nr, nc in _neighbors4(cr, cc):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                        if ref_cells[nr][nc] == color:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            for part in _find_sub_rectangles(comp):
                groups.append((color, part))
    return groups


def _find_reference_top_left(inp: Grid) -> tuple[int, int]:
    h = len(inp)
    w = len(inp[0]) if h else 0
    candidates = [(0, 0), (0, w - 5), (h - 5, 0), (h - 5, w - 5)]
    for top, left in candidates:
        if top < 0 or left < 0:
            continue
        if top + 5 > h or left + 5 > w:
            continue
        ok = True
        for c in range(left, left + 5):
            if inp[top][c] != RED or inp[top + 4][c] != RED:
                ok = False
                break
        if not ok:
            continue
        for r in range(top + 1, top + 4):
            if inp[r][left] != RED or inp[r][left + 4] != RED:
                ok = False
                break
        if ok:
            return top, left
    raise ValueError("could not find red 5x5 reference rectangle")


def _reference_corner(ref_top: int, ref_left: int, h: int, w: int) -> tuple[str, str]:
    vertical = "top" if ref_top == 0 else "bottom"
    horizontal = "left" if ref_left == 0 else "right"
    return vertical, horizontal


def verify_t4(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input must be non-empty")
    h = len(inp)
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    if h % 3 != 0 or w % 3 != 0:
        raise ValueError("input dimensions must be divisible by 3")
    if h not in (12, 18) or w not in (12, 18):
        raise ValueError("this task uses size 12 or 18")

    ref_top, ref_left = _find_reference_top_left(inp)
    ref_cells = _empty(3, 3)
    for r in range(3):
        for c in range(3):
            ref_cells[r][c] = inp[ref_top + 1 + r][ref_left + 1 + c]

    bh = h // 3
    bw = w // 3
    out = _empty(h, w)
    ref_vertical, ref_horizontal = _reference_corner(ref_top, ref_left, h, w)

    for color, comp in _color_groups_4n_rectangular(ref_cells):
        rows = [r for r, _ in comp]
        cols = [c for _, c in comp]
        r0, r1 = min(rows), max(rows)
        c0, c1 = min(cols), max(cols)
        comp_h = r1 - r0 + 1
        comp_w = c1 - c0 + 1

        top = r0 * bh
        left = c0 * bw
        rect_h = comp_h * bh
        rect_w = comp_w * bw

        for cc in range(left, left + rect_w):
            out[top][cc] = color
            out[top + rect_h - 1][cc] = color
        for rr in range(top + 1, top + rect_h - 1):
            out[rr][left] = color
            out[rr][left + rect_w - 1] = color

        inner_top = top + 1
        inner_left = left + 1
        inner_h = rect_h - 2
        inner_w = rect_w - 2
        half_h = inner_h // 2
        half_w = inner_w // 2
        row_start = inner_top if ref_vertical == "top" else inner_top + half_h
        row_end = inner_top + half_h if ref_vertical == "top" else inner_top + inner_h
        col_start = inner_left if ref_horizontal == "left" else inner_left + half_w
        col_end = inner_left + half_w if ref_horizontal == "left" else inner_left + inner_w
        for rr in range(row_start, row_end):
            for cc in range(col_start, col_end):
                out[rr][cc] = RED

    return out

generator_py:
"""Generator for Test2/t5 cyan-flow task."""

from __future__ import annotations

import random
from typing import List

Grid = List[List[int]]

CYAN = 8
ORANGE = 7


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _neighbors4(r: int, c: int) -> list[tuple[int, int]]:
    return [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]


def _non_orange_components(grid: Grid) -> list[set[tuple[int, int]]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen: set[tuple[int, int]] = set()
    comps: list[set[tuple[int, int]]] = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == ORANGE or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp: set[tuple[int, int]] = set()
            while stack:
                cr, cc = stack.pop()
                comp.add((cr, cc))
                for nr, nc in _neighbors4(cr, cc):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                        if grid[nr][nc] != ORANGE:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            comps.append(comp)
    return comps


def _center_order(cols: list[int]) -> list[int]:
    center = (cols[0] + cols[-1]) / 2.0
    return sorted(cols, key=lambda c: (abs(c - center), c))


def _pack_component(
    comp: set[tuple[int, int]], count: int, preferred_center: float | None = None
) -> set[tuple[int, int]]:
    if count <= 0:
        return set()
    rows = sorted({r for r, _ in comp}, reverse=True)
    row_cells = {r: sorted([c for rr, c in comp if rr == r]) for r in rows}
    bottom = rows[0]

    filled: set[tuple[int, int]] = set()
    remaining = count

    # Bottom-up fill; each row selects a single flow-front segment and fills from
    # the middle. This avoids non-physical "teleport" fills into side cavities on
    # the same level.
    for r in rows:
        if remaining <= 0:
            break
        cols = row_cells[r]
        if not cols:
            continue
        segments: list[list[int]] = []
        i = 0
        while i < len(cols):
            j = i
            while j + 1 < len(cols) and cols[j + 1] == cols[j] + 1:
                j += 1
            seg = cols[i : j + 1]
            segments.append(seg)
            i = j + 1

        if not segments:
            continue

        if r == bottom:
            global_center = preferred_center if preferred_center is not None else (cols[0] + cols[-1]) / 2.0
            chosen_seg = min(segments, key=lambda seg: (abs(((seg[0] + seg[-1]) / 2.0) - global_center), seg[0]))
            order = _center_order(chosen_seg)
        else:
            anchored: list[tuple[int, list[int], list[int]]] = []
            for seg in segments:
                anchors = [c for c in seg if (r + 1, c) in filled]
                if anchors:
                    anchored.append((len(anchors), seg, anchors))
            if not anchored:
                continue
            # Prefer the segment with the strongest support from below.
            anchored.sort(
                key=lambda t: (
                    -t[0],
                    abs(
                        ((t[1][0] + t[1][-1]) / 2.0)
                        - (preferred_center if preferred_center is not None else ((cols[0] + cols[-1]) / 2.0))
                    ),
                    t[1][0],
                )
            )
            _, chosen_seg, anchors = anchored[0]
            # Center from underlying cyan support row (anchors), not full row span.
            center = sum(anchors) / float(len(anchors))
            order = sorted(
                chosen_seg,
                key=lambda c: (abs(c - center), min(abs(c - a) for a in anchors), c),
            )

        take = min(remaining, len(order))
        for c in order[:take]:
            filled.add((r, c))
        remaining -= take

    # Rare fallback for irregular cavities: continue from frontier.
    while remaining > 0:
        candidates: list[tuple[int, int, int]] = []
        for r, c in comp:
            if (r, c) in filled:
                continue
            support = (r == bottom) or ((r + 1, c) in filled) or ((r, c - 1) in filled) or ((r, c + 1) in filled)
            if not support:
                continue
            center = 0.0
            row = row_cells[r]
            if row:
                center = (row[0] + row[-1]) / 2.0
            candidates.append((r, int(abs(c - center) * 1000), c))
        if not candidates:
            break
        # Highest row index (lower in grid) first.
        candidates.sort(key=lambda x: (-x[0], x[1], x[2]))
        r, _, c = candidates[0]
        filled.add((r, c))
        remaining -= 1

    return filled


def _flow_component(
    comp: set[tuple[int, int]], initial_cyan: set[tuple[int, int]], steps_cap: int = 2000
) -> set[tuple[int, int]]:
    """Simulate deterministic gravity/flow inside one non-orange component."""
    if not initial_cyan:
        return set()
    by_row: dict[int, set[int]] = {}
    for r, c in comp:
        by_row.setdefault(r, set()).add(c)

    def row_segment(r: int, c: int) -> tuple[int, int] | None:
        row = by_row.get(r)
        if row is None or c not in row:
            return None
        lo = c
        hi = c
        while (lo - 1) in row:
            lo -= 1
        while (hi + 1) in row:
            hi += 1
        return (lo, hi)

    occ = set(initial_cyan)
    global_center = sum(c for _, c in comp) / float(len(comp))

    steps = 0
    changed = True
    while changed and steps < steps_cap:
        steps += 1
        changed = False
        # Bottom-up update reduces oscillations and keeps settling stable.
        order = sorted(occ, key=lambda rc: (-rc[0], abs(rc[1] - global_center), rc[1]))
        for r, c in order:
            if (r, c) not in occ:
                continue
            # 1) Pure gravity: fall straight down whenever possible.
            below = (r + 1, c)
            if below in comp and below not in occ:
                occ.remove((r, c))
                occ.add(below)
                changed = True
                continue
            # Lateral travel is only on solid support (orange/boundary below),
            # not when simply stacked on another cyan.
            if below in comp:
                continue

            # 2) Blocked below: move laterally toward a reachable drop if any.
            seg = row_segment(r, c)
            if seg is None:
                continue
            lo, hi = seg

            drop_targets: list[int] = []
            for tc in range(lo, hi + 1):
                if (r, tc) in occ and tc != c:
                    continue
                tb = (r + 1, tc)
                if tb in comp and tb not in occ:
                    drop_targets.append(tc)

            moved = False
            if drop_targets:
                best_tc = min(
                    drop_targets,
                    key=lambda tc: (abs(tc - c), abs(tc - global_center), tc),
                )
                step = 0 if best_tc == c else (1 if best_tc > c else -1)
                if step != 0:
                    nxt = (r, c + step)
                    if nxt in comp and nxt not in occ:
                        occ.remove((r, c))
                        occ.add(nxt)
                        changed = True
                        moved = True
            if moved:
                continue

            # 3) No reachable drop: settle on the current solid lane from middle.
            seg_center = (lo + hi) / 2.0
            dirs = sorted(
                [-1, 1],
                key=lambda dc: (
                    abs((c + dc) - seg_center),
                    abs((c + dc) - global_center),
                    c + dc,
                ),
            )
            for dc in dirs:
                nxt = (r, c + dc)
                if nxt in comp and nxt not in occ:
                    occ.remove((r, c))
                    occ.add(nxt)
                    changed = True
                    break
    return occ


def transform_t5(inp: Grid) -> Grid:
    h = len(inp)
    w = len(inp[0]) if h else 0
    out = _empty(h, w)
    for r in range(h):
        for c in range(w):
            if inp[r][c] == ORANGE:
                out[r][c] = ORANGE

    for comp in _non_orange_components(inp):
        cyan_cols = [c for r, c in comp if inp[r][c] == CYAN]
        n_cyan = len(cyan_cols)
        preferred_center = (sum(cyan_cols) / float(n_cyan)) if n_cyan > 0 else None
        for r, c in _pack_component(comp, n_cyan, preferred_center=preferred_center):
            out[r][c] = CYAN
    return out


def _add_random_boundaries(
    grid: Grid, rng: random.Random
) -> tuple[int, set[int], set[tuple[int, int]]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    barrier_r = rng.randint(max(1, h // 4), min(h - 4, h // 2))
    for c in range(w):
        grid[barrier_r][c] = ORANGE
    gap_cols: set[int] = set()
    # Keep openings center-symmetric to avoid ambiguous left-vs-right cases.
    if w % 2 == 0:
        gap_cols = {w // 2 - 1, w // 2}
    else:
        gap_cols = {w // 2}
    for c in gap_cols:
        grid[barrier_r][c] = 0

    reserved_no_cyan: set[tuple[int, int]] = {(barrier_r, c) for c in gap_cols}
    for c in gap_cols:
        for rr, cc in (
            (barrier_r - 1, c - 1),
            (barrier_r - 1, c + 1),
            (barrier_r + 1, c - 1),
            (barrier_r + 1, c + 1),
        ):
            if 0 <= rr < h and 0 <= cc < w:
                reserved_no_cyan.add((rr, cc))

    # Keep one main horizontal barrier only; stacked barriers can produce
    # non-physical-looking fills under a gravity interpretation.

    # Add one or two vertical walls for richer basin geometry/cavities.
    wall_count = rng.randint(0, 2)
    for _ in range(wall_count):
        candidates = [c for c in range(1, w - 1) if all(abs(c - gc) >= 2 for gc in gap_cols)]
        if not candidates:
            break
        c = rng.choice(candidates)
        start_r = rng.randint(barrier_r + 1, max(barrier_r + 1, h - 2))
        for r in range(start_r, h):
            grid[r][c] = ORANGE
        # Optional small opening near bottom to keep compartments varied.
        if h - start_r >= 4 and rng.random() < 0.45:
            hole_r = rng.randint(start_r + 1, h - 2)
            grid[hole_r][c] = 0
            reserved_no_cyan.add((hole_r, c))
            for rr, cc in (
                (hole_r - 1, c - 1),
                (hole_r - 1, c + 1),
                (hole_r + 1, c - 1),
                (hole_r + 1, c + 1),
            ):
                if 0 <= rr < h and 0 <= cc < w:
                    reserved_no_cyan.add((rr, cc))
    return barrier_r, gap_cols, reserved_no_cyan


def _row_segments(cells: set[tuple[int, int]]) -> dict[int, list[list[int]]]:
    by_row: dict[int, list[int]] = {}
    for r, c in cells:
        by_row.setdefault(r, []).append(c)
    out: dict[int, list[list[int]]] = {}
    for r, cols in by_row.items():
        cols = sorted(cols)
        segs: list[list[int]] = []
        start = [cols[0]]
        for c in cols[1:]:
            if c == start[-1] + 1:
                start.append(c)
            else:
                segs.append(start)
                start = [c]
        segs.append(start)
        out[r] = segs
    return out


def _is_ambiguous_fill(inp: Grid, out: Grid) -> bool:
    """Reject generated samples with unresolved center-fill side ambiguity."""
    h = len(inp)
    for comp in _non_orange_components(inp):
        segs_by_row = _row_segments(comp)
        for r, segs in segs_by_row.items():
            for seg in segs:
                chosen = [c for c in seg if out[r][c] == CYAN]
                if not chosen or len(chosen) == len(seg):
                    continue
                # Partial fills are validated against deterministic center ranking
                # from the immediate supporting row.
                support = [c for c in seg if r + 1 < h and out[r + 1][c] == CYAN]
                if not support:
                    return True
                center = sum(support) / float(len(support))
                ordered = sorted(seg, key=lambda c: (abs(c - center), c))
                k = len(chosen)
                # If the boundary between chosen and unchosen has equal distance
                # to center, then side choice is ambiguous.
                if 0 < k < len(ordered):
                    d_k = abs(ordered[k - 1] - center)
                    d_next = abs(ordered[k] - center)
                    if abs(d_k - d_next) < 1e-9:
                        return True
                if set(chosen) != set(ordered[:k]):
                    return True
                # If an unchosen column in this segment has a free drop below
                # (inside component and not already occupied), dynamics would be
                # ambiguous between "center now" vs "slide then drop".
                if r + 1 < h:
                    for c in seg:
                        if c in chosen:
                            continue
                        if (r + 1, c) in comp and out[r + 1][c] != CYAN:
                            return True
    return False


def _has_multi_basin_drop_ambiguity(inp: Grid) -> bool:
    """Reject layouts with multiple simultaneously fed bottom basins.

    If a non-orange component has a split row near its bottom (multiple disjoint
    segments) and more than one segment has cyan somewhere above it in-column,
    the intended drop destination can be read ambiguously.
    """
    for comp in _non_orange_components(inp):
        if not comp:
            continue
        by_row = _row_segments(comp)
        rows = sorted(by_row.keys(), reverse=True)  # bottom-up
        # Focus on the lowest part of each cavity where ambiguity is most visible.
        for r in rows[:3]:
            segs = by_row[r]
            if len(segs) <= 1:
                continue
            fed = 0
            for seg in segs:
                cols = set(seg)
                has_source = any(
                    inp[rr][cc] == CYAN
                    for rr, cc in comp
                    if rr < r and cc in cols
                )
                if has_source:
                    fed += 1
            if fed >= 2:
                return True
    return False


def generate(
    width: int | None = None,
    height: int | None = None,
    rng: random.Random | None = None,
) -> dict[str, Grid]:
    rr = rng if rng is not None else random
    if width is None:
        width = rr.randint(8, 12)
    if height is None:
        height = rr.randint(8, 12)
    if width < 8 or height < 8:
        raise ValueError("width and height must be >= 8")

    for _ in range(1000):
        inp = _empty(height, width)
        barrier_r, gap_cols, reserved_no_cyan = _add_random_boundaries(inp, rr)

        comps = _non_orange_components(inp)
        for comp in comps:
            if not comp:
                continue
            frac = rr.uniform(0.2, 0.5)
            cells = [
                (r, c)
                for (r, c) in comp
                if (r, c) not in reserved_no_cyan and not (r == barrier_r and c in gap_cols)
            ]
            # Avoid seeding directly ambiguous local states:
            # cyan above orange with both lateral routes open.
            safe_cells: list[tuple[int, int]] = []
            for r, c in cells:
                if r + 1 < height and inp[r + 1][c] == ORANGE:
                    continue
                safe_cells.append((r, c))
            if not safe_cells:
                continue
            # Favor sources above/near the first barrier and near its opening(s),
            # so motion reads like mostly vertical falling into the main basin.
            gap_min = min(gap_cols)
            gap_max = max(gap_cols)
            upper_band = [
                rc
                for rc in safe_cells
                if rc[0] <= barrier_r + 1 and (gap_min - 2) <= rc[1] <= (gap_max + 2)
            ]
            # If filtering is too strict for a particular component, relax gently.
            if len(upper_band) < max(1, int(0.5 * len(safe_cells))):
                upper_band = [rc for rc in safe_cells if rc[0] <= barrier_r + 1]

            n = max(1, min(len(safe_cells), int(round(len(safe_cells) * frac))))
            upper_target = n
            chosen: list[tuple[int, int]] = []

            rr.shuffle(upper_band)
            chosen.extend(upper_band[: min(len(upper_band), upper_target)])

            remaining = n - len(chosen)
            if remaining > 0:
                # Top up from just-above-barrier cells before using deeper cells.
                chosen_set = set(chosen)
                near_band = [rc for rc in safe_cells if rc[0] <= barrier_r + 2 and rc not in chosen_set]
                rr.shuffle(near_band)
                chosen.extend(near_band[:remaining])

            if len(chosen) < n:
                chosen_set = set(chosen)
                rest = [rc for rc in safe_cells if rc not in chosen_set and rc[0] <= barrier_r + 3]
                rr.shuffle(rest)
                chosen.extend(rest[: n - len(chosen)])

            for r, c in chosen:
                inp[r][c] = CYAN

        out = transform_t5(inp)
        if not _is_ambiguous_fill(inp, out) and not _has_multi_basin_drop_ambiguity(inp):
            return {"input": inp, "output": out}

    raise RuntimeError("failed to sample unambiguous t5 instance")

verifier_py:
"""Verifier for Test2/t5 cyan-flow task."""

from __future__ import annotations

from typing import List

from generator import transform_t5

Grid = List[List[int]]


def verify_t5(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t5(inp)

generator_py:
"""Generator for Test2/t6 partition-distance ranking task."""

from __future__ import annotations

import random
from typing import List

Grid = List[List[int]]

GREY = 5
GREEN = 3
RANK_COLORS = [3, 4, 2]  # closest, second, third
# Only green is forbidden for partition objects.
OBJECT_PALETTE = [1, 2, 4, 6, 7, 8, 9]


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _neighbors4(r: int, c: int) -> list[tuple[int, int]]:
    return [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]


def _find_partitions(grid: Grid, top: int, left: int, bottom: int, right: int) -> list[set[tuple[int, int]]]:
    interior = [
        (r, c)
        for r in range(top + 1, bottom)
        for c in range(left + 1, right)
        if grid[r][c] != GREY
    ]
    inside = set(interior)
    seen: set[tuple[int, int]] = set()
    comps: list[set[tuple[int, int]]] = []
    for rc in interior:
        if rc in seen:
            continue
        stack = [rc]
        seen.add(rc)
        comp: set[tuple[int, int]] = set()
        while stack:
            r, c = stack.pop()
            comp.add((r, c))
            for nr, nc in _neighbors4(r, c):
                if (nr, nc) in inside and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        comps.append(comp)
    return comps


def _paint_outer_rectangle(grid: Grid, top: int, left: int, bottom: int, right: int) -> None:
    for c in range(left, right + 1):
        grid[top][c] = GREY
        grid[bottom][c] = GREY
    for r in range(top + 1, bottom):
        grid[r][left] = GREY
        grid[r][right] = GREY


def _paint_internal_walls(
    grid: Grid,
    top: int,
    left: int,
    bottom: int,
    right: int,
    partition_count: int,
    rng: random.Random,
) -> None:
    ih = bottom - top - 1
    iw = right - left - 1

    if partition_count == 1:
        return

    if partition_count == 2:
        modes: list[str] = ["diag_pos", "diag_neg"]
        if iw >= 5:
            modes.append("vertical")
        if ih >= 5:
            modes.append("horizontal")
        if iw >= 5 and ih >= 5:
            modes.append("zigzag2")
        mode = rng.choice(modes)
        if mode == "vertical":
            cut = rng.randint(2, iw - 2)
            c = left + cut
            for r in range(top + 1, bottom):
                grid[r][c] = GREY
            return
        if mode == "horizontal":
            cut = rng.randint(2, ih - 2)
            r = top + cut
            for c in range(left + 1, right):
                grid[r][c] = GREY
            return
        if mode == "diag_pos":
            # interior coords satisfy (rr - cc == k)
            k = rng.randint(-(iw - 3), ih - 3)
            for rr in range(1, ih + 1):
                for cc in range(1, iw + 1):
                    if rr - cc == k:
                        grid[top + rr][left + cc] = GREY
            return
        if mode == "zigzag2":
            # Staircase-style separating wall.
            base = rng.randint(2, iw - 2)
            for rr in range(1, ih + 1):
                cc = base + (rr % 2)
                if cc > iw - 1:
                    cc = base - (rr % 2)
                cc = max(1, min(iw, cc))
                grid[top + rr][left + cc] = GREY
            return
        # diag_neg: interior coords satisfy (rr + cc == k)
        k = rng.randint(4, ih + iw - 2)
        for rr in range(1, ih + 1):
            for cc in range(1, iw + 1):
                if rr + cc == k:
                    grid[top + rr][left + cc] = GREY
        return

    # partition_count == 3
    modes3: list[str] = []
    if iw >= 6:
        modes3.append("vertical3")
    if ih >= 6:
        modes3.append("horizontal3")
    # Parallel diagonals need enough spread to leave 3 regions.
    if ih + iw >= 10:
        modes3.extend(["diag_pos3", "diag_neg3"])
    if iw >= 8 and ih >= 6:
        modes3.append("zigzag3")
    if not modes3:
        # Fallback: single wall; caller will reject if partition count mismatches.
        return
    mode = rng.choice(modes3)
    if mode == "vertical3":
        a = rng.randint(2, iw - 4)
        b = rng.randint(a + 2, iw - 2)
        for r in range(top + 1, bottom):
            grid[r][left + a] = GREY
            grid[r][left + b] = GREY
        return
    if mode == "horizontal3":
        a = rng.randint(2, ih - 4)
        b = rng.randint(a + 2, ih - 2)
        for c in range(left + 1, right):
            grid[top + a][c] = GREY
            grid[top + b][c] = GREY
        return
    if mode == "diag_pos3":
        k1 = rng.randint(-(iw - 4), ih - 6)
        k2 = rng.randint(k1 + 2, ih - 3)
        for rr in range(1, ih + 1):
            for cc in range(1, iw + 1):
                if rr - cc == k1 or rr - cc == k2:
                    grid[top + rr][left + cc] = GREY
        return
    if mode == "zigzag3":
        # Two parallel staircase walls, similar to the provided test style.
        base1 = rng.randint(2, max(2, iw // 2 - 1))
        base2 = rng.randint(base1 + 3, iw - 1)
        for rr in range(1, ih + 1):
            off = rr % 2
            c1 = base1 + off
            c2 = base2 + off
            if c2 > iw:
                c1 -= 1
                c2 -= 1
            c1 = max(1, min(iw, c1))
            c2 = max(1, min(iw, c2))
            if c2 - c1 < 2:
                c2 = min(iw, c1 + 2)
            grid[top + rr][left + c1] = GREY
            grid[top + rr][left + c2] = GREY
        return
    k1 = rng.randint(4, ih + iw - 6)
    k2 = rng.randint(k1 + 2, ih + iw - 2)
    for rr in range(1, ih + 1):
        for cc in range(1, iw + 1):
            if rr + cc == k1 or rr + cc == k2:
                grid[top + rr][left + cc] = GREY


def _sample_object_cells(part: set[tuple[int, int]], rng: random.Random) -> set[tuple[int, int]]:
    # Build a small connected object (1-4 cells) inside this partition.
    seed = rng.choice(list(part))
    obj = {seed}
    target = rng.randint(1, min(4, len(part)))
    frontier = [seed]
    while len(obj) < target and frontier:
        r, c = frontier.pop(rng.randrange(len(frontier)))
        candidates = [(nr, nc) for nr, nc in _neighbors4(r, c) if (nr, nc) in part and (nr, nc) not in obj]
        rng.shuffle(candidates)
        for rc in candidates[:2]:
            obj.add(rc)
            frontier.append(rc)
            if len(obj) >= target:
                break
    return obj


def transform_t6(inp: Grid) -> Grid:
    h = len(inp)
    w = len(inp[0]) if h else 0
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")

    grey_cells = [(r, c) for r in range(h) for c in range(w) if inp[r][c] == GREY]
    if not grey_cells:
        raise ValueError("no grey rectangle found")
    top = min(r for r, _ in grey_cells)
    bottom = max(r for r, _ in grey_cells)
    left = min(c for _, c in grey_cells)
    right = max(c for _, c in grey_cells)

    green_cells = [(r, c) for r in range(h) for c in range(w) if inp[r][c] == GREEN]
    if len(green_cells) != 1:
        raise ValueError("expected exactly one green cell")
    gr, gc = green_cells[0]

    parts = _find_partitions(inp, top, left, bottom, right)
    part_info: list[tuple[int, set[tuple[int, int]]]] = []
    for part in parts:
        objs = [(r, c) for r, c in part if inp[r][c] not in (0, GREY, GREEN)]
        if not objs:
            raise ValueError("each partition must contain one object")
        d = min(abs(r - gr) + abs(c - gc) for r, c in objs)
        part_info.append((d, part))
    part_info.sort(key=lambda x: x[0])

    out = _empty(h, w)
    for r, c in grey_cells:
        out[r][c] = GREY
    for i, (_, part) in enumerate(part_info):
        col = RANK_COLORS[min(i, len(RANK_COLORS) - 1)]
        for r, c in part:
            out[r][c] = col
    return out


def generate(
    width: int | None = None,
    height: int | None = None,
    partition_count: int | None = None,
    rng: random.Random | None = None,
) -> dict[str, Grid]:
    rr = rng if rng is not None else random
    if width is None:
        width = rr.randint(10, 14)
    if height is None:
        height = rr.randint(10, 14)
    if width < 9 or height < 9:
        raise ValueError("width and height must be >= 9")

    if partition_count is None:
        # Bias toward richer examples: 3 partitions most likely, then 2, then 1.
        partition_count = rr.choices([1, 2, 3], weights=[1, 2, 9], k=1)[0]
    if partition_count not in (1, 2, 3):
        raise ValueError("partition_count must be in {1,2,3}")

    for _ in range(300):
        inp = _empty(height, width)

        rect_h = rr.randint(7, min(height - 1, 11))
        rect_w = rr.randint(7, min(width - 1, 11))
        top = rr.randint(1, height - rect_h)
        left = rr.randint(1, width - rect_w)
        bottom = top + rect_h - 1
        right = left + rect_w - 1

        _paint_outer_rectangle(inp, top, left, bottom, right)
        _paint_internal_walls(inp, top, left, bottom, right, partition_count, rr)

        parts = _find_partitions(inp, top, left, bottom, right)
        if len(parts) != partition_count:
            continue
        if any(len(p) < 3 for p in parts):
            continue

        # One object per partition.
        used_colors = rr.sample(OBJECT_PALETTE, k=partition_count)
        for part, color in zip(parts, used_colors):
            for r, c in _sample_object_cells(part, rr):
                inp[r][c] = color

        # One green target may be outside or inside the grey shape.
        outside = {
            (r, c)
            for r in range(height)
            for c in range(width)
            if not (top <= r <= bottom and left <= c <= right)
        }
        inside_open = {
            (r, c)
            for r in range(top + 1, bottom)
            for c in range(left + 1, right)
            if inp[r][c] == 0
        }
        outside_list = list(outside)
        inside_list = list(inside_open)
        if not outside_list and not inside_list:
            continue
        # Bias placement outside the grey shape; inside remains possible but less likely.
        if outside_list and inside_list:
            pick_outside = rr.random() < 0.8
            gr, gc = rr.choice(outside_list if pick_outside else inside_list)
        elif outside_list:
            gr, gc = rr.choice(outside_list)
        else:
            gr, gc = rr.choice(inside_list)
        inp[gr][gc] = GREEN

        # Enforce unique distances to avoid tie ambiguity.
        dists = []
        for part in parts:
            objs = [(r, c) for r, c in part if inp[r][c] not in (0, GREY, GREEN)]
            d = min(abs(r - gr) + abs(c - gc) for r, c in objs)
            dists.append(d)
        if len(set(dists)) != len(dists):
            continue

        out = transform_t6(inp)
        return {"input": inp, "output": out}

    raise RuntimeError("failed to sample valid t6 instance")

