generator_py:
"""Generator for Test2/t12: demonstration-grounded container push.

Design:
- Container templates are grounded in the provided t12 demonstrations/test.
- We expand those templates with rotations/mirrors for directional variety.
- Container opening direction is therefore unambiguous by template identity.
- Support bar (9) is always a single connected full line.
- Container always touches (8-neighbor) the bar, does not overlap it, and lies on
  one strict side of it.
"""

from __future__ import annotations

import random
from collections import deque
from typing import Dict, List, Optional, Set, Tuple

Grid = List[List[int]]
Pos = Tuple[int, int]
Dir = Tuple[int, int]

LINE = 9
PALETTE = [1, 2, 3, 4, 5, 6, 7, 8]


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _normalize(cells: Set[Pos]) -> Set[Pos]:
    mr = min(r for r, _ in cells)
    mc = min(c for _, c in cells)
    return {(r - mr, c - mc) for r, c in cells}


def _rotate_cw_cells(cells: Set[Pos]) -> Set[Pos]:
    return _normalize({(c, -r) for r, c in cells})


def _mirror_h_cells(cells: Set[Pos]) -> Set[Pos]:
    return _normalize({(r, -c) for r, c in cells})


def _rotate_cw_dir(d: Dir) -> Dir:
    dr, dc = d
    return (dc, -dr)


def _mirror_h_dir(d: Dir) -> Dir:
    dr, dc = d
    return (dr, -dc)


def _neighbors8(r: int, c: int) -> list[Pos]:
    out: list[Pos] = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            out.append((r + dr, c + dc))
    return out


def _demo_template_library() -> Dict[frozenset[Pos], Dir]:
    """Template->opening direction, grounded in t12 demos (+ symmetries)."""
    bases: list[tuple[Set[Pos], Dir]] = []

    # Demo-like C container (train[0]) opening right.
    bases.append(
        (
            {
                (0, 0),
                (0, 1),
                (0, 2),
                (1, 0),
                (2, 0),
                (3, 0),
                (3, 1),
                (3, 2),
            },
            (0, 1),
        )
    )

    # Demo-like V/chevron (train[1]) opening up.
    bases.append(({(0, 0), (0, 4), (1, 1), (1, 3), (2, 2)}, (-1, 0)))

    # Demo-like diagonal container (train[2], color-8) opening up-left.
    # In the demonstration this shape moves along (-1, -1), not orthogonally.
    bases.append(({(0, 3), (1, 4), (2, 3), (3, 0), (3, 2), (4, 1)}, (-1, -1)))

    # Demo-like wide ring/diamond (train[2]/test-like) opening left.
    bases.append(
        (
            {
                (0, 2),
                (1, 1),
                (1, 3),
                (2, 0),
                (2, 4),
                (3, 4),
                (4, 0),
                (4, 4),
                (5, 1),
                (5, 3),
                (6, 2),
            },
            (0, -1),
        )
    )

    out: Dict[frozenset[Pos], Dir] = {}
    for cells0, dir0 in bases:
        cells = _normalize(cells0)
        d = dir0
        for _ in range(4):
            out.setdefault(frozenset(cells), d)
            mc = _mirror_h_cells(cells)
            md = _mirror_h_dir(d)
            out.setdefault(frozenset(mc), md)
            cells = _rotate_cw_cells(cells)
            d = _rotate_cw_dir(d)
    return out


TEMPLATE_TO_DIR = _demo_template_library()
TEMPLATES: list[Set[Pos]] = [set(k) for k in TEMPLATE_TO_DIR.keys()]


def _components8_by_color(grid: Grid) -> list[tuple[int, Set[Pos]]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen: Set[Pos] = set()
    comps: list[tuple[int, Set[Pos]]] = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col in (0, LINE) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp: Set[Pos] = set()
            while q:
                cr, cc = q.popleft()
                comp.add((cr, cc))
                for nr, nc in _neighbors8(cr, cc):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == col:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append((col, comp))
    return comps


def _metric(orient: str, r: int, c: int) -> int:
    if orient == "h":
        return r
    if orient == "v":
        return c
    if orient == "d1":
        return r - c
    if orient == "d2":
        return r + c
    raise ValueError("bad orientation")


def _line_cells(h: int, w: int, orient: str, k: int) -> Set[Pos]:
    out: Set[Pos] = set()
    if orient == "h":
        if 0 <= k < h:
            for c in range(w):
                out.add((k, c))
        return out
    if orient == "v":
        if 0 <= k < w:
            for r in range(h):
                out.add((r, k))
        return out
    if orient == "d1":  # r-c=k
        for r in range(h):
            c = r - k
            if 0 <= c < w:
                out.add((r, c))
        return out
    if orient == "d2":  # r+c=k
        for r in range(h):
            c = k - r
            if 0 <= c < w:
                out.add((r, c))
        return out
    raise ValueError("bad orientation")


def _touching(a: Set[Pos], b: Set[Pos]) -> bool:
    for r, c in a:
        for nr, nc in _neighbors8(r, c):
            if (nr, nc) in b:
                return True
    return False


def _choose_line_for_container(h: int, w: int, container: Set[Pos], direction: Dir, rng: random.Random) -> Optional[Set[Pos]]:
    """Place a connected full bar touching container on exactly one side."""
    dr, dc = direction
    # For diagonal-opening containers, enforce bar axis parallel to movement/opening.
    if dr != 0 and dc != 0:
        orientations = ["d1"] if dr == dc else ["d2"]
    else:
        orientations = ["h", "v", "d1", "d2"]
        rng.shuffle(orientations)

    for orient in orientations:
        vals = [_metric(orient, r, c) for r, c in container]
        minv = min(vals)
        maxv = max(vals)
        for side in ("less", "greater"):
            k = maxv + 1 if side == "less" else minv - 1
            line = _line_cells(h, w, orient, k)
            if not line:
                continue
            if container & line:
                continue
            if not _touching(container, line):
                continue
            vals2 = [_metric(orient, r, c) for r, c in container]
            if side == "less" and not all(v < k for v in vals2):
                continue
            if side == "greater" and not all(v > k for v in vals2):
                continue
            return line
    return None


def _detect_container_and_direction(grid: Grid) -> tuple[int, Set[Pos], Dir]:
    """Find the unique template-matching component touching the support bar."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    bar = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == LINE}
    matches: list[tuple[int, Set[Pos], Dir]] = []
    for col, comp in _components8_by_color(grid):
        key = frozenset(_normalize(comp))
        d = TEMPLATE_TO_DIR.get(key)
        if d is None:
            continue
        if not _touching(comp, bar):
            continue
        matches.append((col, comp, d))
    if len(matches) != 1:
        raise ValueError("expected exactly one template-matching container touching bar")
    return matches[0]


def _sorted_for_move(cells: Set[Pos], dr: int, dc: int) -> list[Pos]:
    return sorted(cells, key=lambda rc: rc[0] * dr + rc[1] * dc, reverse=True)


def _encountered_cells(r: int, c: int, dr: int, dc: int) -> list[Pos]:
    """Cells a moving block face can encounter during one step.

    For diagonal motion, also include the two orthogonal front-adjacent cells.
    This prevents corner slip-through where payload can bypass via 8-neighborhood.
    """
    cells = [(r + dr, c + dc)]
    if dr != 0 and dc != 0:
        cells.append((r + dr, c))
        cells.append((r, c + dc))
    return cells


def _touches8_cell(p: Pos, cells: Set[Pos]) -> bool:
    pr, pc = p
    for nr, nc in _neighbors8(pr, pc):
        if (nr, nc) in cells:
            return True
    return False


def _is_blocked_flank_for_cell(container: Set[Pos], r: int, c: int, nr: int, nc: int, dr: int, dc: int) -> bool:
    """Whether flank (nr,nc) is blocked by a diagonal container seam at (r,c).

    We only treat seams adjacent to the current container cell as blocking.
    This prevents unrelated global seam matches from repeatedly dragging
    payload that is merely nearby.
    """
    if dr == 0 or dc == 0:
        return False
    # A flank is blocked only when the side-diagonal band is closed; this is
    # the stable container seam that payload cannot slip through.
    side_v = (r + dr, c - dc) in container
    side_h = (r - dr, c + dc) in container
    if nr == r + dr and nc == c:
        return side_v and side_h
    if nr == r and nc == c + dc:
        return side_v and side_h
    return False


def _step_push(grid: Grid, container: Set[Pos], dr: int, dc: int) -> tuple[bool, Set[Pos]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    moving: Set[Pos] = set(container)
    blocked = False

    # Diagonal-only exception: occupied cells on blocked diagonal seams move too.
    if dr != 0 and dc != 0:
        for r, c in container:
            for nr, nc in _encountered_cells(r, c, dr, dc)[1:]:
                if not _is_blocked_flank_for_cell(container, r, c, nr, nc, dr, dc):
                    continue
                if nr < 0 or nr >= h or nc < 0 or nc >= w:
                    continue
                if (nr, nc) in moving or grid[nr][nc] == 0:
                    continue
                if grid[nr][nc] == LINE:
                    blocked = True
                    break
                moving.add((nr, nc))
            if blocked:
                break

    # Overwrite closure: if a moving cell would overwrite an occupied cell,
    # that occupant must be moved as well. This prevents vanishing cells.
    changed = True
    while changed and not blocked:
        changed = False
        for r, c in list(moving):
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= h or nc < 0 or nc >= w:
                blocked = True
                break
            if grid[nr][nc] == LINE and (nr, nc) not in moving:
                blocked = True
                break
            if grid[nr][nc] != 0 and (nr, nc) not in moving:
                moving.add((nr, nc))
                changed = True

    if blocked:
        return False, container

    old = {(r, c): grid[r][c] for r, c in moving}
    for r, c in moving:
        grid[r][c] = 0
    for r, c in _sorted_for_move(moving, dr, dc):
        grid[r + dr][c + dc] = old[(r, c)]
    return True, {(r + dr, c + dc) for r, c in container}


def transform_t12(inp: Grid) -> Grid:
    h = len(inp)
    w = len(inp[0]) if h else 0
    if h == 0 or w == 0 or any(len(row) != w for row in inp):
        raise ValueError("input must be a non-empty rectangular grid")

    out = [row[:] for row in inp]
    _col, container, (dr, dc) = _detect_container_and_direction(out)
    while True:
        moved, container = _step_push(out, container, dr, dc)
        if not moved:
            break
    return out


def _scatter_payload(grid: Grid, container_color: int, rng: random.Random, n: int) -> None:
    h = len(grid)
    w = len(grid[0]) if h else 0
    colors = [c for c in PALETTE if c != container_color]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    rng.shuffle(cells)
    for r, c in cells[:n]:
        grid[r][c] = rng.choice(colors)


def generate(
    width: int | None = None,
    height: int | None = None,
    rng: random.Random | None = None,
) -> dict[str, Grid]:
    rr = rng if rng is not None else random
    w = width if width is not None else rr.randint(10, 14)
    h = height if height is not None else rr.randint(10, 14)
    if w < 8 or h < 8:
        raise ValueError("width and height must be >= 8")

    for _ in range(1500):
        inp = _empty(h, w)
        tmpl = rr.choice(TEMPLATES)
        direction = TEMPLATE_TO_DIR[frozenset(tmpl)]
        th = max(r for r, _ in tmpl) + 1
        tw = max(c for _, c in tmpl) + 1
        if th >= h - 2 or tw >= w - 2:
            continue
        ar = rr.randint(1, h - th - 1)
        ac = rr.randint(1, w - tw - 1)
        container_cells = {(ar + r, ac + c) for r, c in tmpl}
        container_color = rr.choice(PALETTE)
        for r, c in container_cells:
            inp[r][c] = container_color

        line_cells = _choose_line_for_container(h, w, container_cells, direction, rr)
        if line_cells is None:
            continue
        for r, c in line_cells:
            inp[r][c] = LINE

        _scatter_payload(inp, container_color, rr, n=rr.randint(7, 18))

        try:
            out = transform_t12(inp)
        except Exception:
            continue
        if out == inp:
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to sample valid t12 instance")

verifier_py:
"""Verifier for Test2/t12 container push task."""

from __future__ import annotations

from typing import List

from generator import transform_t12

Grid = List[List[int]]


def verify_t12(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t12(inp)

"""Verifier / forward transform for Test2/t13 (concentric layers + green marker)."""

from __future__ import annotations

import copy
from collections import Counter, defaultdict
from typing import List, Tuple

Grid = List[List[int]]

GREEN = 3
MARK = 9
BG = 0


def _bbox_nonzero(g: Grid) -> Tuple[int, int, int, int]:
    rows = [i for i, r in enumerate(g) for j, v in enumerate(r) if v != 0]
    cols = [j for i, r in enumerate(g) for j, v in enumerate(r) if v != 0]
    if not rows:
        raise ValueError("empty grid")
    return min(rows), max(rows), min(cols), max(cols)


def _find_green(g: Grid) -> Tuple[int, int]:
    found: list[Tuple[int, int]] = []
    for r, row in enumerate(g):
        for c, v in enumerate(row):
            if v == GREEN:
                found.append((r, c))
    if len(found) != 1:
        raise ValueError("expected exactly one green cell (3)")
    return found[0]


def _border_coords(r0: int, r1: int, c0: int, c1: int) -> List[Tuple[int, int]]:
    out: list[Tuple[int, int]] = []
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r == r0 or r == r1 or c == c0 or c == c1:
                out.append((r, c))
    return out


def _mode_non_green(vals: List[int]) -> int:
    xs = [v for v in vals if v not in (BG, GREEN)]
    if not xs:
        raise ValueError("empty border for mode")
    return Counter(xs).most_common(1)[0][0]


def _onion_bands_uniform(g: Grid, r0: int, r1: int, c0: int, c1: int) -> bool:
    """Each L1-distance band (inside bbox) has at most one non-zero color."""
    by_d: dict[int, set[int]] = defaultdict(set)
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            v = g[r][c]
            if v == BG:
                continue
            d = min(r - r0, r1 - r, c - c0, c1 - c)
            by_d[d].add(v)
    for s in by_d.values():
        if len(s) > 1:
            return False
    return True


def _infer_center_color(
    inp: Grid, gr: int, gc: int, *, forbidden: set[int] | None = None
) -> int:
    """When green sits alone as the last 1×1 core, pick a consistent fill color.

    *forbidden* is the set of colors already used by outer logical layers (so we
    do not pick another ``4`` when the rim is ``4`` and only the core is missing).

    If several values keep L1-distance bands monochrome, break ties by closeness
    to the mean of the green cell's non-zero orthogonal neighbors.
    """
    ban = forbidden or set()
    nbr_vals: list[int] = []
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        r, c = gr + dr, gc + dc
        if 0 <= r < len(inp) and 0 <= c < len(inp[0]):
            v = inp[r][c]
            if v not in (BG, GREEN):
                nbr_vals.append(v)
    target = sum(nbr_vals) / len(nbr_vals) if nbr_vals else 0.0

    candidates: list[int] = []
    for trial in range(1, 10):
        if trial in (GREEN, MARK) or trial in ban:
            continue
        t = copy.deepcopy(inp)
        t[gr][gc] = trial
        r0, r1, c0, c1 = _bbox_nonzero(t)
        if _onion_bands_uniform(t, r0, r1, c0, c1):
            candidates.append(trial)
    if not candidates:
        raise ValueError("could not infer center color")
    candidates.sort(key=lambda t: (abs(t - target), -t))
    return candidates[0]


def transform_t13(inp: Grid) -> Grid:
    """Apply t13 rule: replace green with layer color; stack score 9s in last column."""
    if not inp or any(len(row) != len(inp[0]) for row in inp):
        raise ValueError("non-rectangular grid")

    gr, gc = _find_green(inp)
    r0, r1, c0, c1 = _bbox_nonzero(inp)

    layers: list[int] = []
    prev_dom: int | None = None
    score: int | None = None
    rep: int | None = None

    br0, br1, bc0, bc1 = r0, r1, c0, c1
    while br0 <= br1 and bc0 <= bc1:
        if br0 == br1 and bc0 == bc1 and inp[br0][bc0] == GREEN:
            rep = _infer_center_color(inp, gr, gc, forbidden=set(layers))
            score = len(layers) + 1
            break

        coords = _border_coords(br0, br1, bc0, bc1)
        dom = _mode_non_green([inp[r][c] for r, c in coords])
        if prev_dom is None or dom != prev_dom:
            layers.append(dom)
            prev_dom = dom

        on_border = gr == br0 or gr == br1 or gc == bc0 or gc == bc1
        if on_border:
            rep = dom
            score = len(layers)
            break

        if br0 == br1 and bc0 == bc1:
            break
        br0, br1, bc0, bc1 = br0 + 1, br1 - 1, bc0 + 1, bc1 - 1

    if score is None or rep is None:
        raise ValueError("could not place green on a recognized layer")

    out = copy.deepcopy(inp)
    out[gr][gc] = rep
    h, w = len(out), len(out[0])
    last_col = w - 1
    for k in range(score):
        r = h - 1 - k
        if r < 0:
            raise ValueError("score exceeds grid height")
        out[r][last_col] = MARK
    return out


def verify_t13(inp: Grid, out: Grid) -> bool:
    try:
        return transform_t13(inp) == out
    except Exception:
        return False

generator_py:
"""Generator for Test2/t14: bottom-runner jump/duck with conditional star."""

from __future__ import annotations

import random
from typing import List

Grid = List[List[int]]

BG = 0
DOT = 2
BLOCK = 3
STAR = 4


def _copy_grid(g: Grid) -> Grid:
    return [row[:] for row in g]


def _grounded_height(g: Grid, c: int) -> int:
    """Height of the contiguous bottom-anchored block stack in column c."""
    h = len(g)
    k = 0
    r = h - 1
    while r >= 0 and g[r][c] == BLOCK:
        k += 1
        r -= 1
    return k


def _add_top_right_star(g: Grid) -> None:
    h = len(g)
    w = len(g[0]) if h else 0
    if h < 3 or w < 3:
        return
    center_r, center_c = 1, w - 2
    for r, c in (
        (center_r, center_c),
        (center_r - 1, center_c),
        (center_r + 1, center_c),
        (center_r, center_c - 1),
        (center_r, center_c + 1),
    ):
        if 0 <= r < h and 0 <= c < w:
            g[r][c] = STAR


def transform_t14(inp: Grid) -> Grid:
    """Move the red dot right with jump/duck rules and add star on success."""
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("input grid must be rectangular")

    h = len(inp)
    dot_cells = [(r, c) for r in range(h) for c in range(w) if inp[r][c] == DOT]
    if len(dot_cells) != 1:
        raise ValueError("expected exactly one red dot (2)")
    dot_r, dot_c = dot_cells[0]
    if dot_r != h - 1:
        raise ValueError("dot must be on bottom row")

    pos = dot_c
    while pos < w - 1:
        nxt = pos + 1
        if inp[dot_r][nxt] == BG:
            pos = nxt
            continue

        # A grounded block directly ahead can be jumped only if its height is 1 or 2.
        if inp[dot_r][nxt] == BLOCK:
            height = _grounded_height(inp, nxt)
            if height in (1, 2):
                landing = pos + 2
                if landing < w and inp[dot_r][landing] == BG:
                    pos = landing
                    continue
        break

    out = _copy_grid(inp)
    out[dot_r][dot_c] = BG
    out[dot_r][pos] = DOT
    if pos == w - 1:
        _add_top_right_star(out)
    return out


def _make_empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _place_grounded_block(g: Grid, c: int, height: int) -> None:
    h = len(g)
    for r in range(h - 1, h - height - 1, -1):
        g[r][c] = BLOCK


def _place_floating_cell(g: Grid, c: int, r: int) -> None:
    g[r][c] = BLOCK


def _sample_nonadjacent_columns(
    candidates: list[int], count: int, rng: random.Random
) -> list[int]:
    pool = candidates[:]
    rng.shuffle(pool)
    chosen: list[int] = []
    for c in pool:
        if all(abs(c - x) > 1 for x in chosen):
            chosen.append(c)
            if len(chosen) >= count:
                break
    return sorted(chosen)


def _has_invalid_horizontal_adjacency(g: Grid) -> bool:
    """Adjacent 3s are allowed only if both are fully floating (clear shaft below)."""
    h = len(g)
    w = len(g[0]) if h else 0
    for r in range(h):
        for c in range(w - 1):
            if g[r][c] != BLOCK or g[r][c + 1] != BLOCK:
                continue
            left_clear = all(g[rr][c] == BG for rr in range(r + 1, h))
            right_clear = all(g[rr][c + 1] == BG for rr in range(r + 1, h))
            if not (left_clear and right_clear):
                return True
    return False


def _jump_clearance_cells(g: Grid) -> set[tuple[int, int]]:
    """Cells that must stay empty so 1/2-high grounded blocks are visibly jumpable."""
    h = len(g)
    w = len(g[0]) if h else 0
    forbidden: set[tuple[int, int]] = set()
    for c in range(w):
        gh = _grounded_height(g, c)
        if gh not in (1, 2):
            continue
        for k in range(gh):
            r = h - 1 - k
            nr = r - 1
            if nr < 0:
                continue
            if c - 1 >= 0:
                forbidden.add((nr, c - 1))
            if c + 1 < w:
                forbidden.add((nr, c + 1))
    return forbidden


def _has_blocked_jump_diagonal(g: Grid) -> bool:
    for r, c in _jump_clearance_cells(g):
        if g[r][c] == BLOCK:
            return True
    return False


def generate(
    rng: random.Random | None = None,
    *,
    min_w: int = 10,
    max_w: int = 16,
    min_h: int = 6,
    max_h: int = 10,
) -> dict[str, Grid]:
    rr = rng or random.Random()

    for _ in range(1000):
        w = rr.randint(min_w, max_w)
        h = rr.randint(min_h, max_h)
        inp = _make_empty(h, w)
        inp[h - 1][0] = DOT

        should_reach_border = rr.random() < 0.55
        candidates = list(range(1, w))
        rr.shuffle(candidates)
        grounded_cols: set[int] = set()

        if should_reach_border:
            n_grounded = rr.randint(2, max(2, min(4, (w - 2) // 2 + 1)))
            grounded_list = _sample_nonadjacent_columns(list(range(1, w - 1)), n_grounded, rr)
            for c in grounded_list:
                _place_grounded_block(inp, c, rr.choice([1, 2]))
                grounded_cols.add(c)
        else:
            stop_col = rr.randint(3, w - 2)
            before_candidates = [c for c in range(1, stop_col) if abs(c - stop_col) > 1]
            n_before_max = max(0, min(3, len(before_candidates)))
            n_before = rr.randint(0, n_before_max) if n_before_max else 0
            for c in _sample_nonadjacent_columns(before_candidates, n_before, rr):
                _place_grounded_block(inp, c, rr.choice([1, 2]))
                grounded_cols.add(c)
            _place_grounded_block(inp, stop_col, 3)
            grounded_cols.add(stop_col)
            after_candidates = [
                c
                for c in range(stop_col + 1, w - 1)
                if abs(c - stop_col) > 1 and all(abs(c - x) > 1 for x in grounded_cols)
            ]
            n_after_max = max(0, min(2, len(after_candidates)))
            n_after = rr.randint(0, n_after_max) if n_after_max else 0
            for c in _sample_nonadjacent_columns(after_candidates, n_after, rr):
                _place_grounded_block(inp, c, rr.choice([1, 2, 3]))
                grounded_cols.add(c)

        forbidden_jump_cells = _jump_clearance_cells(inp)

        # Add floating cells/runs with a full empty shaft below.
        for c in range(1, w - 1):
            if inp[h - 1][c] != BG:
                continue
            if rr.random() < 0.16:
                r = rr.randint(1, max(1, h - 3))
                if (r, c) in forbidden_jump_cells:
                    continue
                if all(inp[rrr][c] == BG for rrr in range(r, h)):
                    _place_floating_cell(inp, c, r)

        # Occasionally place one horizontal floating pair/triple, which is demo-compatible.
        if rr.random() < 0.35:
            run_len = 2 if rr.random() < 0.8 else 3
            start = rr.randint(1, max(1, w - run_len - 1))
            cols = list(range(start, start + run_len))
            r = rr.randint(1, max(1, h - 3))
            if all(inp[h - 1][c] == BG for c in cols) and all(
                all(inp[rrr][c] == BG for rrr in range(r, h)) for c in cols
            ) and all((r, c) not in forbidden_jump_cells for c in cols):
                for c in cols:
                    _place_floating_cell(inp, c, r)

        out = transform_t14(inp)

        # Ensure the task is non-trivial.
        if out == inp or _has_invalid_horizontal_adjacency(inp) or _has_blocked_jump_diagonal(inp):
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to sample valid t14 instance")

verifier_py:
"""Verifier for Test2/t14 dot jump + duck + conditional star task."""

from __future__ import annotations

from typing import List

from generator import transform_t14

Grid = List[List[int]]


def verify_t14(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t14(inp)

generator_py:
"""Generator for Test2/t15: move independent cell one partition clockwise."""

from __future__ import annotations

import random
from collections import Counter
from typing import List, Sequence, Tuple

Grid = List[List[int]]
Pos = Tuple[int, int]


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _in_bounds(h: int, w: int, r: int, c: int) -> bool:
    return 0 <= r < h and 0 <= c < w


def _rot_cw(r: int, c: int, cr: int, cc: int) -> Pos:
    dr, dc = r - cr, c - cc
    return cr + dc, cc - dr


def _best_center(inp: Grid) -> Pos:
    h = len(inp)
    w = len(inp[0]) if h else 0
    nz = [(r, c) for r in range(h) for c in range(w) if inp[r][c] != 0]
    if not nz:
        raise ValueError("input has no non-zero cells")

    best: tuple[int, int, int, int, int] | None = None
    for cr in range(h):
        for cc in range(w):
            good = 0
            miss = 0
            out = 0
            for r, c in nz:
                rr, rc = _rot_cw(r, c, cr, cc)
                if not _in_bounds(h, w, rr, rc):
                    out += 1
                elif inp[rr][rc] != 0:
                    good += 1
                else:
                    miss += 1
            cand = (good, -miss, -out, -abs(cr - h // 2), -abs(cc - w // 2))
            if best is None or cand > best:
                best = cand
                best_center = (cr, cc)
    return best_center


def _pick_mover(inp: Grid, center: Pos) -> tuple[Pos, Pos]:
    h = len(inp)
    w = len(inp[0]) if h else 0
    cr, cc = center
    freq = Counter(v for row in inp for v in row if v != 0)
    candidates: list[tuple[int, int, int, int]] = []
    for r in range(h):
        for c in range(w):
            v = inp[r][c]
            if v == 0:
                continue
            rr, rc = _rot_cw(r, c, cr, cc)
            if not _in_bounds(h, w, rr, rc):
                continue
            if inp[rr][rc] != 0:
                continue
            # Prefer likely "independent" colors first (rarer color count).
            candidates.append((freq[v], abs(r - cr) + abs(c - cc), r, c))
    if not candidates:
        raise ValueError("could not identify independent movable cell")
    candidates.sort()
    _f, _d, r, c = candidates[0]
    rr, rc = _rot_cw(r, c, cr, cc)
    return (r, c), (rr, rc)


def transform_t15(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("input must be rectangular")

    center = _best_center(inp)
    src, dst = _pick_mover(inp, center)
    out = [row[:] for row in inp]
    sr, sc = src
    dr, dc = dst
    out[dr][dc] = out[sr][sc]
    out[sr][sc] = 0
    return out


def _orbit4(cr: int, cc: int, r: int, c: int) -> list[Pos]:
    pts = []
    rr, rc = r, c
    for _ in range(4):
        pts.append((rr, rc))
        rr, rc = _rot_cw(rr, rc, cr, cc)
    # dedupe while preserving order
    seen: set[Pos] = set()
    out: list[Pos] = []
    for p in pts:
        if p not in seen:
            seen.add(p)
            out.append(p)
    return out


def _orbit_fully_in_bounds(h: int, w: int, cr: int, cc: int, r: int, c: int) -> bool:
    for rr, rc in _orbit4(cr, cc, r, c):
        if not _in_bounds(h, w, rr, rc):
            return False
    return True


def _is_occupancy_cw_closed(shape: set[Pos], cr: int, cc: int) -> bool:
    for r, c in shape:
        if _rot_cw(r, c, cr, cc) not in shape:
            return False
    return True


def _is_connected_8(cells: set[Pos]) -> bool:
    if not cells:
        return False
    start = next(iter(cells))
    stack = [start]
    seen: set[Pos] = {start}
    while stack:
        r, c = stack.pop()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nb = (r + dr, c + dc)
                if nb in cells and nb not in seen:
                    seen.add(nb)
                    stack.append(nb)
    return len(seen) == len(cells)


def _add_plus_skeleton(cells: set[Pos], h: int, w: int, cr: int, cc: int, arm: int) -> None:
    for k in range(arm + 1):
        for p in ((cr, cc + k), (cr, cc - k), (cr + k, cc), (cr - k, cc)):
            cells.add(p)


def _add_x_skeleton(cells: set[Pos], h: int, w: int, cr: int, cc: int, arm: int) -> None:
    for k in range(arm + 1):
        for p in ((cr + k, cc + k), (cr + k, cc - k), (cr - k, cc + k), (cr - k, cc - k)):
            cells.add(p)


def _adjacent_to_shape(r: int, c: int, shape: set[Pos]) -> bool:
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        if (r + dr, c + dc) in shape:
            return True
    return False


def _mover_candidates(h: int, w: int, shape: set[Pos], cr: int, cc: int) -> list[tuple[Pos, Pos]]:
    out: list[tuple[Pos, Pos]] = []
    for r in range(h):
        for c in range(w):
            if (r, c) in shape:
                continue
            rr, rc = _rot_cw(r, c, cr, cc)
            if not _in_bounds(h, w, rr, rc):
                continue
            if (rr, rc) in shape:
                continue
            if (rr, rc) == (r, c):
                continue
            out.append(((r, c), (rr, rc)))
    return out


def generate(
    rng: random.Random | None = None,
    *,
    min_h: int = 9,
    max_h: int = 13,
    min_w: int = 9,
    max_w: int = 13,
) -> dict[str, Grid]:
    rr = rng or random.Random()

    for _ in range(1200):
        h = rr.randint(min_h, max_h)
        w = rr.randint(min_w, max_w)
        inp = _empty(h, w)

        cr = rr.randint(2, h - 3)
        cc = rr.randint(2, w - 3)
        max_arm = min(cr, h - 1 - cr, cc, w - 1 - cc)
        if max_arm < 2:
            continue

        shape: set[Pos] = set()
        arm = rr.randint(2, max_arm)
        if rr.random() < 0.5:
            _add_plus_skeleton(shape, h, w, cr, cc, arm)
        else:
            _add_x_skeleton(shape, h, w, cr, cc, arm)

        # Add extra 4-orbit points to get varied 4-part structures.
        extra = rr.randint(1, 4)
        for _ in range(extra):
            dr = rr.randint(-max_arm, max_arm)
            dc = rr.randint(-max_arm, max_arm)
            if dr == 0 and dc == 0:
                continue
            r0, c0 = cr + dr, cc + dc
            if not _orbit_fully_in_bounds(h, w, cr, cc, r0, c0):
                continue
            orbit = set(_orbit4(cr, cc, r0, c0))
            candidate = shape | orbit
            # Keep the main structure as one 8-connected component.
            if _is_connected_8(candidate):
                shape = candidate

        if len(shape) < 8 or not _is_occupancy_cw_closed(shape, cr, cc) or not _is_connected_8(shape):
            continue

        base_color = rr.randint(1, 9)
        for r, c in shape:
            inp[r][c] = base_color

        # Miscolorings on the shape can break visual symmetry.
        mis_n = rr.randint(1, min(4, len(shape) // 4))
        for r, c in rr.sample(list(shape), mis_n):
            inp[r][c] = rr.randint(1, 9)

        pairs = _mover_candidates(h, w, shape, cr, cc)
        if not pairs:
            continue
        # Prefer adjacency-allowed placements.
        pairs.sort(
            key=lambda p: (
                0 if _adjacent_to_shape(p[0][0], p[0][1], shape) else 1,
                abs(p[0][0] - cr) + abs(p[0][1] - cc),
            )
        )
        (sr, sc), (tr, tc) = rr.choice(pairs[: max(1, min(12, len(pairs)))])
        mover_color = rr.randint(1, 9)
        inp[sr][sc] = mover_color

        out = transform_t15(inp)
        # Ensure output matches intended destination.
        if out[tr][tc] != mover_color or out[sr][sc] != 0:
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to sample valid t15 instance")

verifier_py:
"""Verifier for Test2/t15 partition-clockwise move rule."""

from __future__ import annotations

from typing import List

from generator import transform_t15

Grid = List[List[int]]


def verify_t15(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t15(inp)

generator_py:
"""Generator for Test2/t16: edge fragments assemble to a target grey shape.

Orthogonally-connected task-color islands are fused transitively whenever they king-touch,
so diagonal contact defines a single prototype (no special-case ridge split).

Interior grey is matched on 4-connectivity only. Generator rejects layouts where grey clues
would be ambiguous (king-only bridges between disjoint grey components, grey king-adjacent
to task colour).

Rigid assemblies union **every permutation** of prototype placement order (same translations,
orthogonal contacts only): anchoring lex-first signature alone skipped valid tilings reachable
only when another piece seeds the incremental placement chain.

"""

from __future__ import annotations

import math
import random
from collections import deque
from itertools import permutations
from typing import Iterable, List, Sequence, Tuple

Grid = List[List[int]]
Pos = Tuple[int, int]
ShapeSig = Tuple[Pos, ...]

BG = 0
GREY = 5


def _empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _in_bounds(h: int, w: int, r: int, c: int) -> bool:
    return 0 <= r < h and 0 <= c < w


def _neighbors4(r: int, c: int) -> Iterable[Pos]:
    yield (r + 1, c)
    yield (r - 1, c)
    yield (r, c + 1)
    yield (r, c - 1)


def _normalize(cells: Iterable[Pos]) -> ShapeSig:
    cells_t = tuple(cells)
    if not cells_t:
        return ()
    min_r = min(r for r, _ in cells_t)
    min_c = min(c for _, c in cells_t)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells_t))


def _translate(sig: ShapeSig, dr: int, dc: int) -> set[Pos]:
    return {(r + dr, c + dc) for r, c in sig}


def _extract_components(grid: Grid, target_color: int) -> list[set[Pos]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen: set[Pos] = set()
    comps: list[set[Pos]] = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != target_color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp: set[Pos] = set()
            while q:
                rr, cc = q.popleft()
                comp.add((rr, cc))
                for nr, nc in _neighbors4(rr, cc):
                    if _in_bounds(h, w, nr, nc) and grid[nr][nc] == target_color and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append(comp)
    return comps


def _neighbors8(r: int, c: int) -> Iterable[Pos]:
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            yield (r + dr, c + dc)


def _orthogonal_adjacent_cells(a: set[Pos], b: set[Pos]) -> bool:
    for r, c in a:
        for nr, nc in _neighbors4(r, c):
            if (nr, nc) in b:
                return True
    return False


def _comps_king_touch(a: set[Pos], b: set[Pos]) -> bool:
    for r, c in a:
        for nr, nc in _neighbors8(r, c):
            if (nr, nc) in b:
                return True
    return False


def _merge_colored_fragments_king_linked(color_frags: Sequence[set[Pos]]) -> list[set[Pos]]:
    """Fuse pairwise king-touching orthogonal color components into rigid prototypes."""
    n = len(color_frags)
    if n <= 1:
        return [*color_frags]

    parent = list(range(n))

    def find(i: int) -> int:
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i: int, j: int) -> None:
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[rj] = ri

    for i in range(n):
        for j in range(i + 1, n):
            if _comps_king_touch(color_frags[i], color_frags[j]):
                union(i, j)

    buckets: dict[int, set[Pos]] = {}
    for i in range(n):
        r = find(i)
        buckets.setdefault(r, set()).update(color_frags[i])
    return list(buckets.values())


def _assemble_signatures_ordered(
    ordered: Sequence[ShapeSig],
    *,
    max_states: int,
    seen_states: set[tuple[int, ShapeSig]],
    out: set[ShapeSig],
) -> None:
    """DFS one placement order (ordered[0] anchors first). Mutates ``seen_states``, ``out``."""
    first = set(ordered[0])
    rest = ordered[1:]
    budget = max_states

    def rec(idx: int, union: set[Pos]) -> None:
        nonlocal budget
        if budget <= 0:
            return
        budget -= 1

        key = (idx, _normalize(union))
        if key in seen_states:
            return
        seen_states.add(key)

        if idx == len(rest):
            out.add(_normalize(union))
            return

        piece = rest[idx]
        translations: set[Pos] = set()
        for ur, uc in union:
            for ar, ac in ((ur + 1, uc), (ur - 1, uc), (ur, uc + 1), (ur, uc - 1)):
                for pr, pc in piece:
                    translations.add((ar - pr, ac - pc))

        for tr, tc in sorted(translations):
            placed = _translate(piece, tr, tc)
            if union & placed:
                continue
            if not any((nr, nc) in union for r, c in placed for nr, nc in _neighbors4(r, c)):
                continue
            rec(idx + 1, union | placed)

    rec(0, first)


def _assemble_signatures(piece_sigs: Sequence[ShapeSig], *, max_states: int = 500_000) -> set[ShapeSig]:
    """Enumerate unions over translations and **all orders** of snapping pieces onto the union."""
    pieces = tuple(piece_sigs)
    if not pieces:
        return set()

    n = len(pieces)
    fac = math.factorial(n)
    per_budget = max(max_states // fac, min(80_000, max_states))

    out: set[ShapeSig] = set()
    for perm in permutations(pieces):
        seen_perm: set[tuple[int, ShapeSig]] = set()
        _assemble_signatures_ordered(perm, max_states=per_budget, seen_states=seen_perm, out=out)
    return out


def _all_assemblies(piece_sigs: Sequence[ShapeSig]) -> set[ShapeSig]:
    sigs = _assemble_signatures(piece_sigs)
    if not sigs:
        raise ValueError("could not assemble colored edge fragments")
    return sigs


def _sample_mode_count(rr: random.Random, n_modes: int) -> int:
    """Bias toward 1-2 assembly modes, with all modes selected rarely."""
    if n_modes <= 1:
        return 1
    if n_modes == 2:
        return 1 if rr.random() < 0.7 else 2

    # n_modes >= 3: strongly favor 1 or 2; all modes are uncommon.
    choices: list[tuple[int, float]] = [
        (1, 0.45),
        (2, 0.35),
        (3, 0.12),
        (n_modes, 0.03),
    ]
    # Add medium counts (4..n-1) with low probability mass.
    middle = [k for k in range(4, n_modes) if k != n_modes]
    if middle:
        rem = 0.05 / len(middle)
        for k in middle:
            choices.append((k, rem))
    total = sum(w for _, w in choices)
    x = rr.random() * total
    acc = 0.0
    for k, w in choices:
        acc += w
        if x <= acc:
            return min(k, n_modes)
    return min(2, n_modes)


def transform_t16(inp: Grid) -> Grid:
    """Recolor interior orth-grey blobs whose shape equals a rigid orthogonal assembly."""
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("input grid must be rectangular")

    h = len(inp)
    colors = sorted({v for row in inp for v in row if v not in (BG, GREY)})
    if len(colors) != 1:
        raise ValueError("expected exactly one non-grey, non-background color")
    color = colors[0]

    raw_color = _extract_components(inp, color)
    prototypes = _merge_colored_fragments_king_linked(raw_color)
    if len(prototypes) < 2:
        raise ValueError("expected at least two colored prototypes after diagonal fusion")

    piece_sigs = [_normalize(comp) for comp in prototypes]
    target_sigs = _all_assemblies(piece_sigs)

    out = [row[:] for row in inp]
    for r in range(h):
        for c in range(w):
            if out[r][c] == color:
                out[r][c] = BG

    grey_comps = _extract_components(inp, GREY)
    for comp in grey_comps:
        if _normalize(comp) not in target_sigs:
            continue
        for r, c in comp:
            out[r][c] = color
    return out


def _grey_has_king_only_bridge(inp: Grid) -> bool:
    """True if two distinct orth-grey components touch at a diagonal only."""
    comps = _extract_components(inp, GREY)
    for i in range(len(comps)):
        for j in range(i + 1, len(comps)):
            if _comps_king_touch(comps[i], comps[j]) and not _orthogonal_adjacent_cells(comps[i], comps[j]):
                return True
    return False


def _grey_king_adjacent_to_task_color(inp: Grid, task_color: int) -> bool:
    h, w = len(inp), len(inp[0])
    for r in range(h):
        for c in range(w):
            if inp[r][c] != GREY:
                continue
            for nr, nc in _neighbors8(r, c):
                if _in_bounds(h, w, nr, nc) and inp[nr][nc] == task_color:
                    return True
    return False


def _random_polyomino(rr: random.Random, size: int) -> ShapeSig:
    cells: set[Pos] = {(0, 0)}
    while len(cells) < size:
        r, c = rr.choice(tuple(cells))
        nr, nc = rr.choice([(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)])
        cells.add((nr, nc))
    return _normalize(cells)


def _biased_poly_sizes(rr: random.Random, n: int, *, bare: bool) -> list[int]:
    """Prefer triomino/tetromino-sized lumps (authored tasks rarely look like domino salads)."""
    choices = [2, 3, 4, 5]
    weights = [0.06, 0.38, 0.44, 0.12] if bare else [0.05, 0.33, 0.42, 0.20]
    return [rr.choices(choices, weights=weights, k=1)[0] for _ in range(n)]


def _on_perimeter(r: int, c: int, h: int, w: int) -> bool:
    return r == 0 or c == 0 or r == h - 1 or c == w - 1


def _enumerate_diagonal_singleton_chains_from_perimeter_anchor(h: int, w: int, length: int) -> list[set[Pos]]:
    """Straight lattice-diagonal chains whose **first** cell is on the perimeter.

    Interior cells along the ridge are allowed (matches authored ridges that dip one row/col inward).
    Length ≥ 4 is impossible if every cell must stay on the boundary—that old rule suppressed longer chains.
    """
    assert length >= 2
    dirs = ((1, 1), (1, -1), (-1, 1), (-1, -1))
    raw: list[set[Pos]] = []
    for r in range(h):
        for c in range(w):
            if not _on_perimeter(r, c, h, w):
                continue
            for dr, dc in dirs:
                cells: list[Pos] = []
                ok = True
                for k in range(length):
                    rr_, cc_ = r + k * dr, c + k * dc
                    if not _in_bounds(h, w, rr_, cc_):
                        ok = False
                        break
                    cells.append((rr_, cc_))
                if ok and len(set(cells)) == length:
                    raw.append(set(cells))
    seen: set[tuple[Pos, ...]] = set()
    uniq: list[set[Pos]] = []
    for s in raw:
        sig = tuple(sorted(s))
        if sig not in seen:
            seen.add(sig)
            uniq.append(s)
    return uniq


def _try_place_diagonal_singleton_chain(
    rr: random.Random,
    occupied: set[Pos],
    h: int,
    w: int,
    *,
    length: int,
) -> set[Pos] | None:
    cand = _enumerate_diagonal_singleton_chains_from_perimeter_anchor(h, w, length)
    if not cand:
        return None
    # Several shuffles — ordering matters when singletons share rows/cols from sorting alone.
    for _ in range(4):
        rr.shuffle(cand)
        for chain in cand:
            acc = set(occupied)
            ok = True
            for cell in sorted(chain):
                solo = {cell}
                if not _can_place(solo, acc, h, w, forbid_adj4=True):
                    ok = False
                    break
                acc |= solo
            if ok:
                return chain
    return None


def _raw_has_king_diagonal_bridge(frags: Sequence[set[Pos]]) -> bool:
    """Some orth-islands touch king-only (diagonal cue), matching authored motifs."""
    for i in range(len(frags)):
        for j in range(i + 1, len(frags)):
            if _comps_king_touch(frags[i], frags[j]) and not _orthogonal_adjacent_cells(frags[i], frags[j]):
                return True
    return False


def _max_diag_singleton_chain_len(inp: Grid, color: int) -> int:
    """Longest run of task-coloured monominos along one lattice-diagonal ray (king-only chain)."""
    pts = {next(iter(f)) for f in _extract_components(inp, color) if len(f) == 1}
    if not pts:
        return 0
    best = 0
    dirs = ((1, 1), (1, -1), (-1, 1), (-1, -1))
    for r, c in pts:
        for dr, dc in dirs:
            k = 0
            cr, cc = r, c
            while (cr, cc) in pts:
                k += 1
                cr, cc = cr + dr, cc + dc
            best = max(best, k)
    return best


def _edge_offsets_for_piece(sig: ShapeSig, h: int, w: int, edge: str) -> list[Pos]:
    max_r = max(r for r, _ in sig)
    max_c = max(c for _, c in sig)
    out: list[Pos] = []
    if edge == "top":
        for dc in range(0, w - max_c):
            out.append((0, dc))
    elif edge == "bottom":
        base_r = h - 1 - max_r
        for dc in range(0, w - max_c):
            out.append((base_r, dc))
    elif edge == "left":
        for dr in range(0, h - max_r):
            out.append((dr, 0))
    elif edge == "right":
        base_c = w - 1 - max_c
        for dr in range(0, h - max_r):
            out.append((dr, base_c))
    return out


def _can_place(
    cells: set[Pos],
    occupied: set[Pos],
    h: int,
    w: int,
    *,
    forbid_adj4: bool,
    forbid_king_near: set[Pos] | None = None,
) -> bool:
    for r, c in cells:
        if not _in_bounds(h, w, r, c):
            return False
        if (r, c) in occupied:
            return False
    if forbid_adj4:
        for r, c in cells:
            for nr, nc in _neighbors4(r, c):
                if (nr, nc) in occupied:
                    return False
    if forbid_king_near:
        ban = forbid_king_near
        for r, c in cells:
            for nr, nc in _neighbors8(r, c):
                if _in_bounds(h, w, nr, nc) and (nr, nc) in ban:
                    return False
    return True


def _place_piece_on_edge(
    rr: random.Random,
    sig: ShapeSig,
    edge: str,
    occupied: set[Pos],
    h: int,
    w: int,
    *,
    forbid_king_near: set[Pos] | None = None,
) -> set[Pos] | None:
    offsets = _edge_offsets_for_piece(sig, h, w, edge)
    rr.shuffle(offsets)
    for dr, dc in offsets:
        cells = _translate(sig, dr, dc)
        if _can_place(cells, occupied, h, w, forbid_adj4=True, forbid_king_near=forbid_king_near):
            return cells
    return None


def _place_interior_shape(
    rr: random.Random,
    sig: ShapeSig,
    occupied: set[Pos],
    h: int,
    w: int,
) -> set[Pos] | None:
    max_r = max(r for r, _ in sig)
    max_c = max(c for _, c in sig)
    if h - 2 - max_r < 1 or w - 2 - max_c < 1:
        return None
    candidates: list[Pos] = []
    for dr in range(1, h - 1 - max_r):
        for dc in range(1, w - 1 - max_c):
            candidates.append((dr, dc))
    rr.shuffle(candidates)
    for dr, dc in candidates:
        cells = _translate(sig, dr, dc)
        if _can_place(cells, occupied, h, w, forbid_adj4=True):
            return cells
    return None


def generate(
    rng: random.Random | None = None,
    *,
    min_h: int = 11,
    max_h: int = 16,
    min_w: int = 11,
    max_w: int = 16,
    ridge_chain_target: int | None = None,
) -> dict[str, Grid]:
    rr = rng or random.Random()

    if ridge_chain_target is not None and ridge_chain_target not in (2, 3, 4):
        raise ValueError("ridge_chain_target must be one of {2, 3, 4} or None")

    # ``diag_triple`` is **always** three king-linked singletons (train-style ridge).
    # Length-four ridges use ``diag_quad`` so triple sketches are not diluted toward quad.
    sketches = ["bare", "diag_pair", "diag_triple", "diag_quad", "mixed"]
    sketch_w = [0.07, 0.18, 0.38, 0.12, 0.25]

    for _ in range(28000):
        eff_min_h, eff_min_w = min_h, min_w
        if ridge_chain_target in (3, 4):
            eff_min_h = max(min_h, 13)
            eff_min_w = max(min_w, 13)
        h = rr.randint(eff_min_h, max_h)
        w = rr.randint(eff_min_w, max_w)
        inp = _empty(h, w)

        color = rr.choice([1, 2, 3, 4, 6, 7, 8, 9])
        occupied: set[Pos] = set()
        forbid_king_near: set[Pos] | None = None
        ridge_chain_len: int | None = None

        if ridge_chain_target is not None:
            sketch = "__ridge_target__"
            ridge_chain_len = ridge_chain_target
        else:
            sketch = rr.choices(sketches, weights=sketch_w, k=1)[0]
            if sketch == "diag_triple":
                ridge_chain_len = 3
            elif sketch == "diag_quad":
                ridge_chain_len = 4
            elif sketch == "diag_pair":
                ridge_chain_len = 2
            elif sketch == "mixed":
                ridge_chain_len = rr.choices([2, 3, 4], weights=[0.22, 0.46, 0.32])[0]

        if ridge_chain_len is not None:
            ridge = _try_place_diagonal_singleton_chain(rr, occupied, h, w, length=ridge_chain_len)
            if ridge is None:
                continue
            occupied |= ridge
            forbid_king_near = set(ridge)
            n_poly_extra = rr.randint(1, 2)
            sizes = _biased_poly_sizes(rr, n_poly_extra, bare=False)
        else:
            # Orth-edge lumps only (still forbid orthogonal overlap); mostly tri/tet pentomino mixes.
            n_poly_extra = rr.randint(2, 3)
            sizes = _biased_poly_sizes(rr, n_poly_extra, bare=True)

        piece_sigs = [_random_polyomino(rr, sz) for sz in sizes]

        edges = ["top", "bottom", "left", "right"]
        rr.shuffle(edges)
        piece_edges = [edges[i % len(edges)] for i in range(len(piece_sigs))]
        rr.shuffle(piece_edges)

        ok = True
        for sig, edge in zip(piece_sigs, piece_edges):
            placed = _place_piece_on_edge(
                rr,
                sig,
                edge,
                occupied,
                h,
                w,
                forbid_king_near=forbid_king_near,
            )
            if placed is None:
                ok = False
                break
            occupied |= placed
        if not ok:
            continue

        for r in range(h):
            for c in range(w):
                if (r, c) in occupied:
                    inp[r][c] = color

        raw_frags = _extract_components(inp, color)
        if ridge_chain_target is not None:
            if _max_diag_singleton_chain_len(inp, color) < ridge_chain_target:
                continue
        if ridge_chain_len is not None:
            if not _raw_has_king_diagonal_bridge(raw_frags):
                continue
        elif sketch == "bare":
            if _raw_has_king_diagonal_bridge(raw_frags):
                continue

        prototypes = _merge_colored_fragments_king_linked(raw_frags)
        if len(prototypes) < 2:
            continue
        merged_sigs = [_normalize(p) for p in prototypes]
        try:
            assemblies_set = _all_assemblies(merged_sigs)
        except ValueError:
            continue
        assemblies = sorted(assemblies_set)
        if len(assemblies) < 2 or len(assemblies) > 420:
            continue
        if any(len(sig) < 4 or len(sig) > 12 for sig in assemblies):
            continue

        # Place a sampled subset of assembly interpretations.
        n_target_modes = _sample_mode_count(rr, len(assemblies))
        selected = rr.sample(assemblies, n_target_modes)
        match_count = 0
        for sig in selected:
            placed = _place_interior_shape(rr, sig, occupied, h, w)
            if placed is None:
                continue
            for r, c in placed:
                inp[r][c] = GREY
            occupied |= placed
            match_count += 1
        if match_count < len(selected):
            continue
        # Optionally add a few duplicate matches from random assembly modes.
        extra_matches = rr.randint(0, 2)
        for _ in range(extra_matches):
            sig = rr.choice(selected)
            placed = _place_interior_shape(rr, sig, occupied, h, w)
            if placed is None:
                continue
            for r, c in placed:
                inp[r][c] = GREY
            occupied |= placed
            match_count += 1
        if match_count == 0:
            continue

        # Place non-matching grey distractors.
        n_distractors = rr.randint(2, 5)
        for _ in range(n_distractors):
            for _inner in range(20):
                cand = _random_polyomino(rr, rr.randint(1, 10))
                if _normalize(cand) in assemblies_set:
                    continue
                placed = _place_interior_shape(rr, cand, occupied, h, w)
                if placed is None:
                    continue
                for r, c in placed:
                    inp[r][c] = GREY
                occupied |= placed
                break

        if _grey_has_king_only_bridge(inp) or _grey_king_adjacent_to_task_color(inp, color):
            continue

        out = transform_t16(inp)
        if out == inp:
            continue
        if not any(out[r][c] == color and inp[r][c] == GREY for r in range(h) for c in range(w)):
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to sample valid t16 instance")

verifier_py:
"""Verifier for Test2/t16 edge-assembly recoloring."""

from __future__ import annotations

from typing import List

from generator import transform_t16

Grid = List[List[int]]


def verify_t16(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t16(inp)

generator_py:
"""Generator for Test2/t17 (pattern fall).

The prototype is always **fully visible** somewhere on the grid (an unclipped copy),
with at least one placement **strictly inside** the outer border (not on row/column 0
or the last row/column).

**Inference.** Prefer strictly interior 4‑connected foreground blobs of size 2–10
(unique normalised shape, or most frequent among ties). If that does not determine the
prototype (merged blobs, ambiguous fragments), fall back to the **largest** ``n``≤10
connected shape that **occurs as an induced subgraph of the foreground** (orthogonal
connectivity first, then king) and admits an exact disjoint cover of the foreground.

The fallback never scans the full catalogue of fixed ``n``‑ominoes (that was
prohibitively slow); it only considers shapes that literally appear on the grid.

``generate()`` samples orth‑connected prototypes with two fully interior placements.
"""

from __future__ import annotations

import random
from collections import Counter, deque
from typing import Callable, Iterable, List, Tuple

Grid = List[List[int]]
Pos = Tuple[int, int]
ShapeSig = Tuple[Pos, ...]

BG = 0


def _empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _in_bounds(h: int, w: int, r: int, c: int) -> bool:
    return 0 <= r < h and 0 <= c < w


def _max_orth_component_size(fg: set[Pos]) -> int:
    """Largest 4‑connected size among cells in ``fg`` (induced on the grid)."""
    if not fg:
        return 0
    seen: set[Pos] = set()
    best = 0
    for start in sorted(fg):
        if start in seen:
            continue
        q = deque([start])
        seen.add(start)
        comp: set[Pos] = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in _neighbors4(r, c):
                p = (nr, nc)
                if p in fg and p not in seen:
                    seen.add(p)
                    comp.add(p)
                    q.append(p)
        if len(comp) > best:
            best = len(comp)
    return best


def _max_king_component_size(fg: set[Pos]) -> int:
    """Largest 8‑connected size among ``fg``."""
    if not fg:
        return 0
    seen: set[Pos] = set()
    best = 0
    for start in sorted(fg):
        if start in seen:
            continue
        q = deque([start])
        seen.add(start)
        comp: set[Pos] = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in _neighbors8(r, c):
                p = (nr, nc)
                if p in fg and p not in seen:
                    seen.add(p)
                    comp.add(p)
                    q.append(p)
        if len(comp) > best:
            best = len(comp)
    return best


def _orth_connected_components(inp: Grid, color: int) -> list[set[Pos]]:
    h = len(inp)
    w = len(inp[0]) if h else 0
    seen: set[Pos] = set()
    comps: list[set[Pos]] = []
    for r in range(h):
        for c in range(w):
            if inp[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp: set[Pos] = set()
            while q:
                rr, cc = q.popleft()
                comp.add((rr, cc))
                for nr, nc in _neighbors4(rr, cc):
                    if _in_bounds(h, w, nr, nc) and inp[nr][nc] == color and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append(comp)
    return comps


def _is_strictly_interior(comp: set[Pos], h: int, w: int) -> bool:
    if not comp:
        return False
    return (
        min(r for r, _ in comp) > 0
        and max(r for r, _ in comp) < h - 1
        and min(c for _, c in comp) > 0
        and max(c for _, c in comp) < w - 1
    )


def _try_infer_proto_from_interior_blobs(
    inp: Grid, color: int
) -> tuple[ShapeSig, list[tuple[int, int]]] | None:
    """Use strictly interior 4‑connected blobs of size 2–10 (unique or most frequent)."""
    h = len(inp)
    w = len(inp[0]) if h else 0
    fg0 = {(r, c) for r in range(h) for c in range(w) if inp[r][c] == color}
    sigs: list[ShapeSig] = []
    for comp in _orth_connected_components(inp, color):
        if not _is_strictly_interior(comp, h, w):
            continue
        if 2 <= len(comp) <= 10:
            sigs.append(_normalize(comp))
    if not sigs:
        return None
    if len(sigs) == 1:
        sig = sigs[0]
        anchors = _try_infer_anchors_for_proto(inp, color, sig, fg0)
        return (sig, anchors) if anchors is not None else None
    cnt = Counter(sigs)
    max_c = max(cnt.values())
    for sig in sorted(s for s, c in cnt.items() if c == max_c):
        anchors = _try_infer_anchors_for_proto(inp, color, sig, fg0)
        if anchors is not None:
            return sig, anchors
    return None


def _neighbors4(r: int, c: int) -> Iterable[Pos]:
    yield (r + 1, c)
    yield (r - 1, c)
    yield (r, c + 1)
    yield (r, c - 1)


def _normalize(cells: Iterable[Pos]) -> ShapeSig:
    cells_t = tuple(cells)
    if not cells_t:
        return ()
    min_r = min(r for r, _ in cells_t)
    min_c = min(c for _, c in cells_t)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells_t))


def _neighbors8(r: int, c: int) -> Iterable[Pos]:
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr or dc:
                yield (r + dr, c + dc)


def _induced_connected_exact_size(
    fg: set[Pos],
    neighbor_iter: Callable[[int, int], Iterable[Pos]],
    n: int,
    max_calls: int,
) -> set[ShapeSig]:
    """Connected ``n``‑subsets of ``fg`` (``neighbor_iter``), translation‑normalised. Pruned to exact size only."""
    uniq: set[ShapeSig] = set()
    calls = 0

    def rec(active: frozenset[Pos]) -> None:
        nonlocal calls
        calls += 1
        if calls > max_calls:
            return
        na = len(active)
        if na == n:
            uniq.add(_normalize(active))
            return
        if na > n:
            return
        cand: set[Pos] = set()
        for r, c in active:
            for nr, nc in neighbor_iter(r, c):
                if (nr, nc) in fg and (nr, nc) not in active:
                    cand.add((nr, nc))
        for nb in sorted(cand):
            rec(active | {nb})

    for start in sorted(fg):
        rec(frozenset({start}))
    return uniq


def _draw_shape(grid: Grid, color: int, sig: ShapeSig, top: int, left: int) -> None:
    h = len(grid)
    w = len(grid[0]) if h else 0
    for dr, dc in sig:
        rr, cc = top + dr, left + dc
        if _in_bounds(h, w, rr, cc):
            grid[rr][cc] = color


def _visible_from_anchor(sig: ShapeSig, top: int, left: int, h: int, w: int) -> set[Pos]:
    out: set[Pos] = set()
    for dr, dc in sig:
        rr, cc = top + dr, left + dc
        if _in_bounds(h, w, rr, cc):
            out.add((rr, cc))
    return out


def _strict_interior_full_placement_count(sig: ShapeSig, fg: set[Pos], h: int, w: int) -> int:
    """How many anchors place a full unclipped copy strictly inside the outer border and inside ``fg``."""
    max_r = max(r for r, _ in sig)
    max_c = max(c for _, c in sig)
    n = 0
    for top in range(-max_r, h):
        for left in range(-max_c, w):
            vis = _visible_from_anchor(sig, top, left, h, w)
            if len(vis) != len(sig) or not vis.issubset(fg):
                continue
            if min(r for r, _ in vis) <= 0:
                continue
            if max(r for r, _ in vis) >= h - 1:
                continue
            if min(c for _, c in vis) <= 0:
                continue
            if max(c for _, c in vis) >= w - 1:
                continue
            n += 1
    return n


def _strict_interior_full_placement_exists(sig: ShapeSig, fg: set[Pos], h: int, w: int) -> bool:
    """True iff some anchor places the entire prototype on-grid, strictly inside the border (unclipped copy)."""
    return _strict_interior_full_placement_count(sig, fg, h, w) > 0


def _try_infer_anchors_for_proto(
    inp: Grid, color: int, sig: ShapeSig, fg: set[Pos] | None = None
) -> list[tuple[int, int]] | None:
    """Return anchors whose disjoint clipped placements cover all ``color`` cells, or ``None``."""
    h = len(inp)
    w = len(inp[0]) if h else 0
    if fg is None:
        fg = {(r, c) for r in range(h) for c in range(w) if inp[r][c] == color}
    if not fg:
        return []

    max_r = max(r for r, _ in sig)
    max_c = max(c for _, c in sig)

    vis_to_anchor: dict[frozenset[Pos], tuple[int, int]] = {}
    for top in range(-max_r, h):
        for left in range(-max_c, w):
            vis = frozenset(_visible_from_anchor(sig, top, left, h, w))
            if not vis or not vis.issubset(fg):
                continue
            prev = vis_to_anchor.get(vis)
            if prev is None or (top, left) < prev:
                vis_to_anchor[vis] = (top, left)

    if not vis_to_anchor:
        return None

    sets = sorted(vis_to_anchor.items(), key=lambda kv: (-len(kv[0]), kv[1]))
    cell_to_set_ids: dict[Pos, list[int]] = {p: [] for p in fg}
    for idx, (vis, _anchor) in enumerate(sets):
        for p in vis:
            cell_to_set_ids[p].append(idx)

    if any(len(cell_to_set_ids[p]) == 0 for p in fg):
        return None

    covered: set[Pos] = set()
    chosen_ids: list[int] = []

    def _dfs_cover() -> bool:
        if len(covered) == len(fg):
            return True
        uncovered = [p for p in fg if p not in covered]
        pivot = min(
            uncovered,
            key=lambda p: sum(1 for sid in cell_to_set_ids[p] if not (sets[sid][0] & covered)),
        )
        cands = [sid for sid in cell_to_set_ids[pivot] if not (sets[sid][0] & covered)]
        cands.sort(key=lambda sid: (-len(sets[sid][0]), sets[sid][1]))
        for sid in cands:
            vis, _anchor = sets[sid]
            if vis & covered:
                continue
            chosen_ids.append(sid)
            covered.update(vis)
            if _dfs_cover():
                return True
            chosen_ids.pop()
            covered.difference_update(vis)
        return False

    if not _dfs_cover():
        return None

    return [sets[sid][1] for sid in chosen_ids]


def _infer_anchors_for_proto(inp: Grid, color: int, sig: ShapeSig) -> list[tuple[int, int]]:
    out = _try_infer_anchors_for_proto(inp, color, sig)
    if out is None:
        raise ValueError("could not decompose foreground into clipped prototype placements")
    return out


def _resolve_proto_signature(inp: Grid, color: int) -> tuple[ShapeSig, list[tuple[int, int]]]:
    """Interior blobs first; else largest induced foreground shape (orth, then king) with exact cover."""
    hinted = _try_infer_proto_from_interior_blobs(inp, color)
    if hinted is not None:
        return hinted

    h = len(inp)
    w = len(inp[0]) if h else 0
    fg = {(r, c) for r in range(h) for c in range(w) if inp[r][c] == color}

    nf = len(fg)
    max_orth = _max_orth_component_size(fg)
    max_king = _max_king_component_size(fg)
    for neighbors, budget, n_hi in (
        (_neighbors4, 200_000, min(10, nf, max_orth)),
        (_neighbors8, 400_000, min(10, nf, max_king)),
    ):
        if n_hi < 2:
            continue
        for n in range(n_hi, 1, -1):
            raw = _induced_connected_exact_size(fg, neighbors, n, max_calls=budget)
            scored: list[tuple[int, ShapeSig]] = []
            for s in raw:
                pc = _strict_interior_full_placement_count(s, fg, h, w)
                if pc > 0:
                    scored.append((-pc, s))
            scored.sort(key=lambda t: (t[0], t[1]))
            for _neg_pc, sig in scored:
                anchors = _try_infer_anchors_for_proto(inp, color, sig, fg)
                if anchors is not None:
                    return sig, anchors

    raise ValueError("no prototype (2–10 cells, orth or king) tiles the foreground")


def _pattern_fall_output(
    inp: Grid,
    color: int,
    proto_sig: ShapeSig,
    anchors: list[tuple[int, int]] | None = None,
) -> Grid:
    """Stamp each inferred anchor placement downward by the prototype height (authoritative rule)."""
    h = len(inp)
    w = len(inp[0]) if h else 0
    if anchors is None:
        anchors = _infer_anchors_for_proto(inp, color, proto_sig)
    shape_h = max(r for r, _ in proto_sig) + 1
    anchors = sorted(set(anchors))
    out = _empty(h, w)
    for top, left in anchors:
        _draw_shape(out, color, proto_sig, top + shape_h, left)
    return out


def transform_t17(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("input grid must be rectangular")

    h = len(inp)
    colors = sorted({v for row in inp for v in row if v != BG})
    if len(colors) != 1:
        raise ValueError("expected exactly one foreground color")
    color = colors[0]

    fg = {(r, c) for r in range(h) for c in range(w) if inp[r][c] == color}
    if not fg:
        raise ValueError("no foreground components found")

    proto_sig, anchors = _resolve_proto_signature(inp, color)
    return _pattern_fall_output(inp, color, proto_sig, anchors)


def _random_connected_shape(rr: random.Random, height: int, width: int) -> ShapeSig:
    cols: list[int] = [rr.randint(0, width - 1)]
    for _r in range(1, height):
        prev = cols[-1]
        cands = [c for c in (prev - 1, prev, prev + 1) if 0 <= c < width]
        cols.append(rr.choice(cands))

    cells: set[Pos] = {(r, c) for r, c in enumerate(cols)}
    max_cells = 10
    max_extra = max(0, max_cells - len(cells))
    extra_n = rr.randint(0, min(max(2, height + width), max_extra))
    for _ in range(extra_n):
        r = rr.randint(0, height - 1)
        c = rr.randint(0, width - 1)
        if len(cells) >= max_cells:
            break
        if any((nr, nc) in cells for nr, nc in _neighbors4(r, c)):
            cells.add((r, c))
    return _normalize(cells)


def generate(
    rng: random.Random | None = None,
    *,
    min_h: int = 10,
    max_h: int = 16,
    min_w: int = 10,
    max_w: int = 16,
) -> dict[str, Grid]:
    rr = rng or random.Random()

    # Enough placement draws per candidate grid; low values waste outer iterations.
    for _ in range(1000):
        h = rr.randint(min_h, max_h)
        w = rr.randint(min_w, max_w)
        color = rr.choice([1, 2, 3, 4, 6, 7, 8, 9])

        shape_h = rr.randint(2, min(6, h - 4))
        shape_w = rr.randint(2, min(6, w - 4))
        sig = _random_connected_shape(rr, shape_h, shape_w)
        if not (2 <= len(sig) <= 10):
            continue

        n_instances = rr.randint(6, 16)
        anchors: list[tuple[int, int]] = []
        occupied: set[Pos] = set()
        top_cut_count = 0
        bot_cut_count = 0
        left_cut_count = 0
        right_cut_count = 0
        full_count = 0

        for _j in range(n_instances * 14):
            if len(anchors) >= n_instances:
                break
            top = rr.randint(-shape_h + 1, h - 1)
            left = rr.randint(-shape_w + 1, w - 1)
            visible = _visible_from_anchor(sig, top, left, h, w)
            if not visible:
                continue
            expanded = set(visible)
            for r, c in list(visible):
                for nr, nc in _neighbors4(r, c):
                    if _in_bounds(h, w, nr, nc):
                        expanded.add((nr, nc))
            if occupied & expanded:
                continue
            anchors.append((top, left))
            occupied |= expanded
            if top < 0:
                top_cut_count += 1
            if top + shape_h - 1 >= h:
                bot_cut_count += 1
            if left < 0:
                left_cut_count += 1
            if left + shape_w - 1 >= w:
                right_cut_count += 1
            if (
                0 <= top
                and top + shape_h - 1 < h
                and 0 <= left
                and left + shape_w - 1 < w
                and len(visible) == len(sig)
            ):
                full_count += 1

        if len(anchors) < 5:
            continue
        if full_count < 2:
            continue
        if rr.random() < 0.75 and (top_cut_count + bot_cut_count) == 0:
            continue
        if rr.random() < 0.7 and (left_cut_count + right_cut_count) == 0:
            continue

        inp = _empty(h, w)
        for top, left in anchors:
            _draw_shape(inp, color, sig, top, left)

        try:
            out = transform_t17(inp)
        except ValueError:
            continue
        if out == inp:
            continue
        if not any(out[r][c] == color and inp[r][c] == BG for r in range(h) for c in range(w)):
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to sample valid t17 instance")

verifier_py:
"""Verifier for Test2/t17 recurring-pattern downward shift."""

from __future__ import annotations

from typing import List

from generator import transform_t17

Grid = List[List[int]]


def verify_t17(inp: Grid) -> Grid:
