generator_py:
"""Generator for t33: odd one out rectangle."""

from __future__ import annotations

import json
import random
from pathlib import Path
from typing import Dict, Iterable, List, Sequence, Set, Tuple

from verifier import _extract_objects, _normalize, _odd_candidates, verify_t33

Grid = List[List[int]]
Cell = Tuple[int, int]
Shape = Tuple[Cell, ...]

MAX_DIM = 22  # intentionally smaller than the global 30x30 cap


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _dims(shape: Shape) -> Tuple[int, int]:
    if not shape:
        return (0, 0)
    return max(r for r, _ in shape) + 1, max(c for _, c in shape) + 1


def _paint(grid: Grid, shape: Shape, r0: int, c0: int, color: int) -> None:
    for r, c in shape:
        grid[r0 + r][c0 + c] = color


def _shape_to_grid(shape: Shape, color: int) -> Grid:
    h, w = _dims(shape)
    g = _empty(h, w)
    _paint(g, shape, 0, 0, color)
    return g


def _shape_signature(shape: Shape) -> Shape:
    return _normalize(shape)


def _random_connected_partition(rr: random.Random, H: int, W: int, m: int) -> Tuple[Shape, ...] | None:
    cells = [(r, c) for r in range(H) for c in range(W)]
    cell_set = set(cells)
    min_piece_area = 2
    if H * W < m * min_piece_area:
        return None
    for _ in range(500):
        seeds = rr.sample(cells, m)
        pieces = [{s} for s in seeds]
        unassigned = cell_set - set(seeds)
        while unassigned:
            frontier = []
            sizes = [len(p) for p in pieces]
            min_size = min(sizes)
            for i, piece in enumerate(pieces):
                nbrs = set()
                for r, c in piece:
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        q = (r + dr, c + dc)
                        if q in unassigned:
                            nbrs.add(q)
                # bias toward growing smaller pieces
                weight = 3 if len(piece) == min_size else 1
                frontier.extend([(i, q)] * weight for q in nbrs)
            flat = [item for sub in frontier for item in sub]
            if not flat:
                break
            i, q = rr.choice(flat)
            pieces[i].add(q)
            unassigned.remove(q)
        if unassigned:
            continue
        sizes = [len(p) for p in pieces]
        if min(sizes) < min_piece_area:
            continue
        # keep pieces reasonably balanced
        if max(sizes) > H * W - (m - 1) * min_piece_area:
            continue
        shapes = tuple(_normalize(piece) for piece in pieces)
        if len({_shape_signature(s) for s in shapes}) != m:
            continue
        return shapes
    return None


def _random_connected_shape(rr: random.Random, area: int, max_h: int = 6, max_w: int = 6) -> Shape | None:
    for _ in range(300):
        cells = {(0, 0)}
        frontier = {(0, 1), (1, 0), (-1, 0), (0, -1)}
        while len(cells) < area and frontier:
            cell = rr.choice(list(frontier))
            frontier.remove(cell)
            cells.add(cell)
            r, c = cell
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                q = (r + dr, c + dc)
                if q not in cells:
                    frontier.add(q)
        shape = _normalize(cells)
        h, w = _dims(shape)
        if len(shape) == area and h <= max_h and w <= max_w:
            return shape
    return None


def _has_clearance(occupied: Set[Cell], shape: Shape, r0: int, c0: int, h: int, w: int) -> bool:
    for r, c in shape:
        rr, cc = r0 + r, c0 + c
        if not (0 <= rr < h and 0 <= cc < w):
            return False
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if (rr + dr, cc + dc) in occupied:
                    return False
    return True


def _place_shapes(rr: random.Random, shapes: Sequence[Shape], colors: Sequence[int], h: int, w: int) -> Grid | None:
    grid = _empty(h, w)
    occupied: Set[Cell] = set()
    slots = [
        (1, 1),
        (1, w - 8),
        (h - 8, 1),
        (h - 8, w - 8),
        (1, w // 2 - 3),
        (h // 2 - 3, 1),
        (h // 2 - 3, w - 8),
        (h - 8, w // 2 - 3),
    ]
    rr.shuffle(slots)
    order = list(range(len(shapes)))
    rr.shuffle(order)
    positions: Dict[int, Tuple[int, int]] = {}
    for idx, base in zip(order, slots):
        shape = shapes[idx]
        sh, sw = _dims(shape)
        placed = False
        for _ in range(150):
            r0 = max(0, min(h - sh, base[0] + rr.randint(-1, 1)))
            c0 = max(0, min(w - sw, base[1] + rr.randint(-1, 1)))
            if _has_clearance(occupied, shape, r0, c0, h, w):
                positions[idx] = (r0, c0)
                for r, c in shape:
                    occupied.add((r0 + r, c0 + c))
                placed = True
                break
        if not placed:
            return None
    for idx, shape in enumerate(shapes):
        r0, c0 = positions[idx]
        _paint(grid, shape, r0, c0, colors[idx])
    return grid


def _dims_ok(grid: Grid) -> bool:
    return len(grid) <= MAX_DIM and len(grid[0]) <= MAX_DIM


def _make_case(rr: random.Random) -> dict[str, Grid] | None:
    # Strongly favor 4 total pieces: odd one out + 3 rectangle pieces.
    # Keep some 5-piece cases and only rare 6-piece cases for variety.
    total_pieces = rr.choices([4, 5, 6], weights=[72, 25, 3])[0]
    rect_piece_count = total_pieces - 1

    rect_dims = [(3, 4), (3, 5), (4, 4), (4, 5), (5, 5), (4, 6)]
    rr.shuffle(rect_dims)
    rect_shapes: Tuple[Shape, ...] | None = None
    chosen_dims = None
    for H, W in rect_dims:
        rect_shapes = _random_connected_partition(rr, H, W, rect_piece_count)
        if rect_shapes is not None:
            chosen_dims = (H, W)
            break
    if rect_shapes is None:
        return None

    rect_sigs = {_shape_signature(s) for s in rect_shapes}
    total_rect_area = sum(len(s) for s in rect_shapes)

    odd_shape = None
    for _ in range(500):
        area = rr.randint(3, min(8, total_rect_area - 1))
        cand = _random_connected_shape(rr, area)
        if cand is None:
            continue
        if _shape_signature(cand) in rect_sigs:
            continue
        odd_shape = cand
        break
    if odd_shape is None:
        return None

    shapes = list(rect_shapes) + [odd_shape]
    colors = rr.sample(range(1, 10), len(shapes))

    max_h = max(_dims(s)[0] for s in shapes)
    max_w = max(_dims(s)[1] for s in shapes)
    grid_h = rr.randint(max(10, max_h + 4), min(MAX_DIM, 16 + (1 if total_pieces >= 5 else 0)))
    grid_w = rr.randint(max(10, max_w + 4), min(MAX_DIM, 16 + (1 if total_pieces >= 5 else 0)))
    grid = _place_shapes(rr, shapes, colors, grid_h, grid_w)
    if grid is None:
        return None

    if not _dims_ok(grid):
        return None
    out = verify_t33(grid)
    if not out:
        return None
    objs = _extract_objects(grid)
    if len(objs) != len(shapes):
        return None
    # Explicit single-solution constraint: exactly one removable object must make
    # the rest translatable into a rectangle, and it must be the intended odd one.
    if len(_odd_candidates(objs)) != 1:
        return None
    if out != _shape_to_grid(odd_shape, colors[-1]):
        # verifier chose a different odd object or failed orientation
        return None
    return {"input": grid, "output": out}


def generate(rng: random.Random | None = None) -> dict[str, Grid]:
    rr = rng if rng is not None else random
    for _ in range(1500):
        ex = _make_case(rr)
        if ex is not None and verify_t33(ex["input"]) == ex["output"]:
            return ex
    raise RuntimeError("failed to generate valid t33 sample")

verifier_py:
"""Verifier for t33: odd one out rectangle.

The input contains several colored objects. Exactly one object is the odd one
out. If that object is removed, the remaining objects can be translated (without
rotation) to tile one filled rectangle. The output is the odd object alone,
cropped to its bounding box and preserving its original orientation and color.
"""

from __future__ import annotations

from itertools import combinations
from math import isqrt
from typing import Dict, Iterable, List, Sequence, Set, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]
Shape = Tuple[Cell, ...]


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _normalize(cells: Iterable[Cell]) -> Shape:
    pts = list(cells)
    if not pts:
        return tuple()
    min_r = min(r for r, _ in pts)
    min_c = min(c for _, c in pts)
    return tuple(sorted((r - min_r, c - min_c) for r, c in pts))


def _dims(shape: Shape) -> Tuple[int, int]:
    if not shape:
        return (0, 0)
    return max(r for r, _ in shape) + 1, max(c for _, c in shape) + 1


def _paint(grid: Grid, shape: Shape, r0: int, c0: int, color: int) -> None:
    for r, c in shape:
        grid[r0 + r][c0 + c] = color


def _extract_objects(grid: Grid) -> List[dict]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen: Set[Cell] = set()
    objs: List[dict] = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells: List[Cell] = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (rr + dr, cc + dc)
                    qr, qc = q
                    if 0 <= qr < h and 0 <= qc < w and q not in seen and grid[qr][qc] == color:
                        seen.add(q)
                        stack.append(q)
            min_r = min(rr for rr, _ in cells)
            min_c = min(cc for _, cc in cells)
            shape = _normalize(cells)
            objs.append({
                "color": color,
                "cells": tuple(sorted(cells)),
                "origin": (min_r, min_c),
                "shape": shape,
                "area": len(cells),
            })
    objs.sort(key=lambda o: (o["origin"], o["color"], o["area"]))
    return objs


def _factor_pairs(area: int) -> List[Tuple[int, int]]:
    out: List[Tuple[int, int]] = []
    for h in range(2, isqrt(area) + 1):
        if area % h == 0:
            w = area // h
            out.append((h, w))
            if h != w:
                out.append((w, h))
    return out


def _placements_for(shape: Shape, H: int, W: int) -> List[Shape]:
    ph, pw = _dims(shape)
    out: List[Shape] = []
    if ph > H or pw > W:
        return out
    for r0 in range(H - ph + 1):
        for c0 in range(W - pw + 1):
            out.append(tuple(sorted((r0 + r, c0 + c) for r, c in shape)))
    return out


def _can_tile_rectangle(shapes: Sequence[Shape]) -> bool:
    area = sum(len(s) for s in shapes)
    if len(shapes) < 2:
        return False
    for H, W in _factor_pairs(area):
        target = {(r, c) for r in range(H) for c in range(W)}
        options: Dict[int, List[Set[Cell]]] = {}
        valid = True
        for i, shape in enumerate(shapes):
            opts = [set(p) for p in _placements_for(shape, H, W)]
            if not opts:
                valid = False
                break
            options[i] = opts
        if not valid:
            continue

        def backtrack(used: Set[Cell], remaining: Set[int]) -> bool:
            if not remaining:
                return used == target
            uncovered = target - used
            coverable: Set[Cell] = set()
            for idx in remaining:
                for p in options[idx]:
                    if not (p & used):
                        coverable |= p
            if uncovered - coverable:
                return False

            best_idx = None
            best_valid: List[Set[Cell]] | None = None
            for idx in remaining:
                val = [p for p in options[idx] if not (p & used)]
                if best_valid is None or len(val) < len(best_valid):
                    best_idx = idx
                    best_valid = val
                if best_valid == []:
                    return False
            assert best_idx is not None and best_valid is not None
            rem2 = set(remaining)
            rem2.remove(best_idx)
            for p in best_valid:
                if backtrack(used | p, rem2):
                    return True
            return False

        if backtrack(set(), set(range(len(shapes)))):
            return True
    return False


def _odd_candidates(objs: Sequence[dict]) -> List[int]:
    out: List[int] = []
    n = len(objs)
    for odd in range(n):
        shapes = [objs[i]["shape"] for i in range(n) if i != odd]
        if _can_tile_rectangle(shapes):
            out.append(odd)
    return out


def _shape_to_grid(shape: Shape, color: int) -> Grid:
    h, w = _dims(shape)
    g = _empty(h, w)
    _paint(g, shape, 0, 0, color)
    return g


def verify_t33(grid: Grid) -> Grid:
    objs = _extract_objects(grid)
    if len(objs) < 3:
        return []
    cands = _odd_candidates(objs)
    if len(cands) != 1:
        return []
    odd = objs[cands[0]]
    return _shape_to_grid(odd["shape"], odd["color"])

generator_py:
"""Generator for t34: recover an occluded pattern, then rotate by the red-corner cue.

Task rule:
- The input contains a cyan square occluder with exactly one red cell at one corner.
- The output is the pattern hidden beneath the square, rotated so that the red corner
  would move to the top-left of the square.
  * red already top-left     -> no rotation
  * red top-right            -> rotate hidden patch 90° counterclockwise
  * red bottom-left          -> rotate hidden patch 90° clockwise
  * red bottom-right         -> rotate hidden patch 180°

Solver model classes supported:
1) nested concentric rectangular rings,
2) row-constant stripe fields recoverable by bridging across the square, and
3) diagonal-repeat fields with step (s, s) for small s.

Generator constraints / ambiguity controls:
- Underlying colors never use cyan (8) or red (2), reserving those for the occluder.
- Generated examples come from one of the three supported pattern families.
- Examples are filtered so the intended family is the one selected by the verifier.
- Generated backgrounds are visually structured rather than noisy: diagonal examples
  use regular stripe/band patterns, row examples use coherent horizontal bands,
  and ring examples use concentric frames.
- The occluded patch is non-trivial (contains at least one non-black cell and some
  visible context exists around it).
"""

from __future__ import annotations

import json
import random
from typing import Dict, List, Optional, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]
PALETTE = [0, 1, 3, 4, 5, 6, 7, 9]
NONZERO_PALETTE = [1, 3, 4, 5, 6, 7, 9]
CYAN = 8
RED = 2


def _empty(h: int, w: int, fill: int = 0) -> Grid:
    return [[fill for _ in range(w)] for _ in range(h)]


def _rot_ccw(m: Grid) -> Grid:
    return [list(row) for row in zip(*m)][::-1]


def _rot_cw(m: Grid) -> Grid:
    return [list(row) for row in zip(*m[::-1])]


def _rot_180(m: Grid) -> Grid:
    return [row[::-1] for row in m[::-1]]


def _copy_grid(g: Grid) -> Grid:
    return [row[:] for row in g]


def _find_square(grid: Grid) -> tuple[int, int, int, int, str]:
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v in (CYAN, RED)]
    if not pts:
        raise ValueError('No cyan/red occluder found')
    rs = [r for r, _ in pts]
    cs = [c for _, c in pts]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    if r1 - r0 != c1 - c0:
        raise ValueError('Occluder must be a square')
    size = r1 - r0 + 1
    if size < 2:
        raise ValueError('Occluder square too small')
    red_cells = [(r, c) for r, c in pts if grid[r][c] == RED]
    if len(red_cells) != 1:
        raise ValueError('Expected exactly one red direction cell')
    red = red_cells[0]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if grid[r][c] not in (CYAN, RED):
                raise ValueError('Occluder square must contain only cyan/red cells')
    corner_map = {
        (r0, c0): 'tl',
        (r0, c1): 'tr',
        (r1, c0): 'bl',
        (r1, c1): 'br',
    }
    if red not in corner_map:
        raise ValueError('Red direction cell must be at a corner of the cyan square')
    return r0, r1, c0, c1, corner_map[red]


def _orient_hidden(hidden: Grid, corner: str) -> Grid:
    if corner == 'tl':
        return hidden
    if corner == 'tr':
        return _rot_ccw(hidden)
    if corner == 'bl':
        return _rot_cw(hidden)
    if corner == 'br':
        return _rot_180(hidden)
    raise ValueError(f'Unknown corner {corner}')


def _ring_candidate(grid: Grid) -> Optional[Grid]:
    h, w = len(grid), len(grid[0])
    r0, r1, c0, c1, _ = _find_square(grid)
    depth_color: Dict[int, int] = {}
    for r in range(h):
        for c in range(w):
            if r0 <= r <= r1 and c0 <= c <= c1:
                continue
            d = min(r, c, h - 1 - r, w - 1 - c)
            v = grid[r][c]
            if d in depth_color and depth_color[d] != v:
                return None
            depth_color[d] = v
    hidden: Grid = []
    for r in range(r0, r1 + 1):
        row: List[int] = []
        for c in range(c0, c1 + 1):
            d = min(r, c, h - 1 - r, w - 1 - c)
            if d not in depth_color:
                return None
            row.append(depth_color[d])
        hidden.append(row)
    return hidden


def _row_bridge_candidate(grid: Grid) -> Optional[Grid]:
    h, w = len(grid), len(grid[0])
    r0, r1, c0, c1, _ = _find_square(grid)
    if c0 == 0 or c1 == w - 1:
        return None
    hidden: Grid = []
    for r in range(r0, r1 + 1):
        lv = grid[r][c0 - 1]
        rv = grid[r][c1 + 1]
        if lv != rv:
            return None
        hidden.append([lv] * (c1 - c0 + 1))
    return hidden


def _diag_candidate(grid: Grid, step: int) -> Optional[Grid]:
    h, w = len(grid), len(grid[0])
    r0, r1, c0, c1, _ = _find_square(grid)
    groups: Dict[Tuple[int, int], int] = {}
    for r in range(h):
        for c in range(w):
            if r0 <= r <= r1 and c0 <= c <= c1:
                continue
            key = (r - c, r % step)
            v = grid[r][c]
            if key in groups and groups[key] != v:
                return None
            groups[key] = v
    hidden: Grid = []
    for r in range(r0, r1 + 1):
        row: List[int] = []
        for c in range(c0, c1 + 1):
            key = (r - c, r % step)
            if key not in groups:
                return None
            row.append(groups[key])
        hidden.append(row)
    return hidden


def _recover_hidden(grid: Grid) -> tuple[Grid, str]:
    # Preference order chosen to match the supplied task references.
    cand = _ring_candidate(grid)
    if cand is not None:
        return cand, 'ring'
    cand = _row_bridge_candidate(grid)
    if cand is not None:
        return cand, 'row'
    for step in (1, 2, 3, 4):
        cand = _diag_candidate(grid, step)
        if cand is not None:
            return cand, f'diag{step}'
    raise ValueError('Could not infer hidden pattern from supported families')


def transform_t34(grid: Grid) -> Grid:
    if not grid or not grid[0] or any(len(row) != len(grid[0]) for row in grid):
        raise ValueError('Input grid must be non-empty and rectangular')
    hidden, _family = _recover_hidden(grid)
    _r0, _r1, _c0, _c1, corner = _find_square(grid)
    return _orient_hidden(hidden, corner)


# ---------------------------------------------------------------------------
# Generation helpers
# ---------------------------------------------------------------------------


def _overlay_occluder(full: Grid, r0: int, c0: int, size: int, corner: str) -> tuple[Grid, Grid]:
    hidden = [row[c0:c0 + size] for row in full[r0:r0 + size]]
    inp = _copy_grid(full)
    for r in range(r0, r0 + size):
        for c in range(c0, c0 + size):
            inp[r][c] = CYAN
    red_pos = {
        'tl': (r0, c0),
        'tr': (r0, c0 + size - 1),
        'bl': (r0 + size - 1, c0),
        'br': (r0 + size - 1, c0 + size - 1),
    }[corner]
    inp[red_pos[0]][red_pos[1]] = RED
    return inp, _orient_hidden(hidden, corner)


def _gen_diag(rng: random.Random) -> Optional[tuple[Grid, Grid, str]]:
    """Generate a clear diagonal stripe/band field, not random sparse noise."""
    h = rng.randint(10, 18)
    w = rng.randint(10, 18)
    size = rng.randint(4, min(6, h - 2, w - 2))
    r0 = rng.randint(1, h - size - 1)
    c0 = rng.randint(1, w - size - 1)
    # Step 1 is the clearest; step 2 appears occasionally to match the reference variety.
    step = rng.choice([1, 1, 1, 2])

    period = rng.choice([3, 4])
    active_width = rng.choice([1, 1, 2])
    stripe_colors = rng.sample(NONZERO_PALETTE, rng.randint(2, 4))
    phase = rng.randrange(period)
    full = _empty(h, w)
    for r in range(h):
        for c in range(w):
            d = r - c + phase
            if d % period < active_width:
                # Color changes only by diagonal band and the optional step lane,
                # producing a regular readable pattern rather than per-cell noise.
                full[r][c] = stripe_colors[((d // period) + (r % step)) % len(stripe_colors)]
            else:
                full[r][c] = 0

    hidden = [row[c0:c0 + size] for row in full[r0:r0 + size]]
    hidden_vals = [v for row in hidden for v in row]
    if all(v == 0 for v in hidden_vals) or len(set(hidden_vals)) < 2:
        return None
    # Ensure row-bridge candidate fails so the intended family is diagonal.
    if all(full[r][c0 - 1] == full[r][c0 + size] for r in range(r0, r0 + size)):
        return None
    corner = rng.choice(['tl', 'tr', 'bl', 'br'])
    inp, out = _overlay_occluder(full, r0, c0, size, corner)
    return inp, out, f'diag{step}'


def _gen_row(rng: random.Random) -> Optional[tuple[Grid, Grid, str]]:
    """Generate coherent horizontal color bands, not independent random rows."""
    size = rng.randint(3, 6)
    h = rng.randint(size + 4, size + 10)
    w = rng.randint(size + 6, size + 14)
    r0 = rng.randint(1, h - size - 1)
    c0 = rng.randint(1, w - size - 1)
    full = _empty(h, w)
    band_colors = rng.sample(NONZERO_PALETTE, rng.randint(2, 4))
    band_height = rng.choice([1, 2, 2, 3])
    include_black_gaps = rng.random() < 0.35
    phase = rng.randrange(len(band_colors))
    for r in range(h):
        band = (r // band_height + phase) % (len(band_colors) + (1 if include_black_gaps else 0))
        color = 0 if include_black_gaps and band == len(band_colors) else band_colors[band]
        for c in range(w):
            full[r][c] = color
    hidden = [row[c0:c0 + size] for row in full[r0:r0 + size]]
    vals = [hidden[i][0] for i in range(size)]
    if len(set(vals)) < 2 or all(v == 0 for v in vals):
        return None
    corner = rng.choice(['tl', 'tr', 'bl', 'br'])
    inp, out = _overlay_occluder(full, r0, c0, size, corner)
    return inp, out, 'row'


def _gen_ring(rng: random.Random) -> Optional[tuple[Grid, Grid, str]]:
    h = rng.randint(9, 17)
    w = rng.randint(9, 17)
    max_depth = min(h, w) // 2
    if max_depth < 3:
        return None
    ring_colors = [rng.choice(NONZERO_PALETTE)]
    while len(ring_colors) < max_depth + 1:
        prev = ring_colors[-1]
        choices = [c for c in NONZERO_PALETTE if c != prev]
        ring_colors.append(rng.choice(choices))
    full = _empty(h, w)
    for r in range(h):
        for c in range(w):
            d = min(r, c, h - 1 - r, w - 1 - c)
            full[r][c] = ring_colors[d]

    size = rng.randint(3, min(6, h - 2, w - 2))
    # Keep the square away from the border so there is visible context all around.
    r0 = rng.randint(1, h - size - 1)
    c0 = rng.randint(1, w - size - 1)
    hidden = [row[c0:c0 + size] for row in full[r0:r0 + size]]
    if len(set(v for row in hidden for v in row)) < 2:
        return None
    corner = rng.choice(['tl', 'tr', 'bl', 'br'])
    inp, out = _overlay_occluder(full, r0, c0, size, corner)
    return inp, out, 'ring'


def generate(rng: random.Random | None = None) -> Dict[str, Grid]:
    rng = rng or random.Random()
    families = ['diag', 'row', 'ring']
    for _ in range(5000):
        family = rng.choices(families, weights=[0.25, 0.30, 0.45], k=1)[0]
        made: Optional[tuple[Grid, Grid, str]]
        if family == 'diag':
            made = _gen_diag(rng)
        elif family == 'row':
            made = _gen_row(rng)
        else:
            made = _gen_ring(rng)
        if made is None:
            continue
        inp, out, intended = made
        try:
            recovered_hidden, recovered_family = _recover_hidden(inp)
            _r0, _r1, _c0, _c1, corner = _find_square(inp)
            predicted = _orient_hidden(recovered_hidden, corner)
        except Exception:
            continue
        if predicted != out:
            continue
        # Ensure the verifier selects the intended family type.
        if intended == 'row' and recovered_family != 'row':
            continue
        if intended == 'ring' and recovered_family != 'ring':
            continue
        if intended.startswith('diag') and not recovered_family.startswith('diag'):
            continue
        return {'input': inp, 'output': out}
    raise RuntimeError('Failed to generate valid t34 example')


if __name__ == '__main__':
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for t34: recover the occluded patch and rotate by the red-corner cue."""

from __future__ import annotations

from typing import List

from generator import transform_t34

Grid = List[List[int]]


def verify_t34(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError('Input grid must be non-empty')
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError('Input grid must be rectangular')
    return transform_t34(inp)

generator_py:
"""Generator for Test2/t35: repair the order of frame sequence.

Rule:
- The input shows a horizontal sequence of same-sized "image" frames separated
  by vertical cyan lines.
- In the correct order, the frames show a natural visual progression.
- The output reorders the frames into that progression.

Generation constraints used to keep examples well-formed and unambiguous:
- all frames have the same size and are separated only by cyan columns;
- first and last frames are kept in their correct positions;
- at least two intermediate frames are out of order;
- generated sequences are from a diverse set of simple monotone progression
  families, so the intended ordering can be recovered deterministically from
  the frame content;
- the output contains exactly the same frames as the input, just reordered.
"""

from __future__ import annotations

import json
import random
from typing import List, Sequence, Tuple

Grid = List[List[int]]
Frame = List[List[int]]
Cell = Tuple[int, int]

BG = 0
CYAN = 8
COLORS = [1, 2, 3, 4, 5, 6, 7, 9]


def _empty(h: int, w: int, fill: int = BG) -> Grid:
    return [[fill for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _occupied(frame: Frame) -> list[Cell]:
    return [(r, c) for r, row in enumerate(frame) for c, v in enumerate(row) if v != BG]


def _split_frames(grid: Grid) -> list[Frame]:
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    h, w = len(grid), len(grid[0])
    sep_cols = [c for c in range(w) if all(grid[r][c] == CYAN for r in range(h))]
    frames: list[Frame] = []
    start = 0
    for c in sep_cols + [w]:
        if c <= start:
            raise ValueError("empty frame")
        frames.append([row[start:c] for row in grid])
        start = c + 1
    if len(frames) < 3:
        raise ValueError("expected at least three frames")
    fh, fw = len(frames[0]), len(frames[0][0])
    if any(len(f) != fh or len(f[0]) != fw for f in frames):
        raise ValueError("all frames must share the same size")
    return frames


def _join_frames(frames: Sequence[Frame]) -> Grid:
    h = len(frames[0])
    out: Grid = []
    for r in range(h):
        row: list[int] = []
        for i, frame in enumerate(frames):
            if i:
                row.append(CYAN)
            row.extend(frame[r])
        out.append(row)
    return out


def _signature(frame: Frame) -> tuple[tuple[int, ...], ...]:
    return tuple(tuple(row) for row in frame)


def _mean_col(frame: Frame) -> float:
    occ = _occupied(frame)
    return sum(c for _, c in occ) / len(occ)


def _mean_row(frame: Frame) -> float:
    occ = _occupied(frame)
    return sum(r for r, _ in occ) / len(occ)


def _count(frame: Frame) -> int:
    return len(_occupied(frame))


def _two_dot_3x3_rank(frame: Frame) -> int | None:
    """Rank the two-dot 3x3 motif that appears in the reference examples."""
    if len(frame) != 3 or len(frame[0]) != 3:
        return None
    occ = sorted(_occupied(frame))
    rank = {
        ((0, 1), (2, 0)): 0,
        ((0, 0), (2, 1)): 1,
        ((1, 0), (2, 2)): 2,
        ((1, 2), (2, 0)): 3,
        ((0, 2), (2, 1)): 4,
        ((0, 1), (2, 2)): 5,
    }
    return rank.get(tuple(occ))


def _frame_sort_key(frame: Frame) -> tuple[float, float, float, float, tuple[tuple[int, ...], ...]]:
    occ = _occupied(frame)
    if not occ:
        raise ValueError("frames must not be empty")
    special = _two_dot_3x3_rank(frame)
    if special is not None:
        return (0, special, 0, 0, _signature(frame))
    return (1, _mean_col(frame), _count(frame), _mean_row(frame), _signature(frame))


def transform_t35(grid: Grid) -> Grid:
    frames = _split_frames(grid)
    ordered = sorted(frames, key=_frame_sort_key)
    return _join_frames(ordered)


# ---------------------------------------------------------------------------
# Generator families
# ---------------------------------------------------------------------------


def _frame_from_cells(h: int, w: int, cells: Sequence[Cell], color: int) -> Frame:
    f = _empty(h, w)
    for r, c in cells:
        if 0 <= r < h and 0 <= c < w:
            f[r][c] = color
    return f


def _single_dot_sequence(rng: random.Random) -> list[Frame]:
    h = rng.randint(3, 7)
    w = rng.randint(5, 7)
    color = rng.choice(COLORS)
    if rng.random() < 0.5:
        cells = [(round((h - 1) * (1 - c / (w - 1))), c) for c in range(w)]
    else:
        row = rng.randrange(h)
        cells = [(row, c) for c in range(w)]
    return [_frame_from_cells(h, w, [cell], color) for cell in cells]


def _growing_triangle_sequence(rng: random.Random) -> list[Frame]:
    h = rng.randint(4, 6)
    w = rng.randint(4, 6)
    n = rng.randint(4, min(6, w + 1))
    color = rng.choice(COLORS)
    frames: list[Frame] = []
    for k in range(1, n + 1):
        width = max(1, round((w * k) / n))
        cells: list[Cell] = []
        for r in range(h):
            row_fill = min(width, max(0, h - r))
            for c in range(row_fill):
                cells.append((r, c))
        frames.append(_frame_from_cells(h, w, cells, color))
    return frames


def _sliding_diagonal_sequence(rng: random.Random) -> list[Frame]:
    """A clean grow-to-full-diagonal-then-shrink sequence.

    The longest middle frame is symmetric and touches both opposite corners,
    avoiding the odd half-diagonal peak that looked visually arbitrary.
    """
    size = rng.choice([5, 7])
    color = rng.choice(COLORS)
    frames: list[Frame] = []
    for center in range(size):
        length = 2 * min(center, size - 1 - center) + 1
        if center == size // 2:
            length = size
        start = center - length // 2
        cols = range(start, start + length)
        cells = [(size - 1 - c, c) for c in cols]
        frames.append(_frame_from_cells(size, size, cells, color))
    return frames


def _vertical_bar_sweep_sequence(rng: random.Random) -> list[Frame]:
    """A vertical line propagates horizontally, perpendicular to its orientation."""
    h = rng.randint(4, 7)
    w = rng.randint(5, 7)
    color = rng.choice(COLORS)
    r0 = rng.randint(0, 1)
    r1 = rng.randint(h - 2, h - 1)
    cells_by_col = [[(r, c) for r in range(r0, r1 + 1)] for c in range(w)]
    return [_frame_from_cells(h, w, cells, color) for cells in cells_by_col]


def _horizontal_bar_sweep_sequence(rng: random.Random) -> list[Frame]:
    """A horizontal line propagates downward, perpendicular to its orientation."""
    h = rng.randint(5, 7)
    w = rng.randint(4, 7)
    color = rng.choice(COLORS)
    c0 = rng.randint(0, 1)
    c1 = rng.randint(w - 2, w - 1)
    cells_by_row = [[(r, c) for c in range(c0, c1 + 1)] for r in range(h)]
    return [_frame_from_cells(h, w, cells, color) for cells in cells_by_row]


def _center_growth_sequence(rng: random.Random) -> list[Frame]:
    """A centered shape grows outward, keeping one consistent shape family.

    Within a single example, all frames are either diamonds or squares; the
    shape type does not switch mid-sequence.
    """
    size = rng.choice([5, 7])
    color = rng.choice(COLORS)
    center = size // 2
    shape_kind = rng.choice(["diamond", "square"])
    frames: list[Frame] = []
    for radius in range(0, center + 1):
        if shape_kind == "diamond":
            cells = [
                (r, c)
                for r in range(size)
                for c in range(size)
                if abs(r - center) + abs(c - center) <= radius
            ]
        else:
            cells = [
                (r, c)
                for r in range(center - radius, center + radius + 1)
                for c in range(center - radius, center + radius + 1)
            ]
        frames.append(_frame_from_cells(size, size, cells, color))
    return frames


def _rightward_fill_sequence(rng: random.Random) -> list[Frame]:
    """A block grows by filling successive columns from left to right."""
    h = rng.randint(3, 6)
    w = rng.randint(5, 7)
    color = rng.choice(COLORS)
    top = rng.randint(0, 1)
    bottom = rng.randint(h - 2, h - 1)
    frames: list[Frame] = []
    for upto in range(w):
        cells = [(r, c) for r in range(top, bottom + 1) for c in range(upto + 1)]
        frames.append(_frame_from_cells(h, w, cells, color))
    return frames


def _two_dot_cycle_sequence(rng: random.Random) -> list[Frame]:
    color = rng.choice(COLORS)
    patterns = [
        [(0, 1), (2, 0)],
        [(0, 0), (2, 1)],
        [(1, 0), (2, 2)],
        [(1, 2), (2, 0)],
        [(0, 2), (2, 1)],
        [(0, 1), (2, 2)],
    ]
    return [_frame_from_cells(3, 3, cells, color) for cells in patterns]


def _make_disordered(frames: list[Frame], rng: random.Random) -> list[Frame]:
    if len(frames) < 4:
        raise ValueError("need at least four frames")
    middle = frames[1:-1]
    for _ in range(200):
        shuffled = middle[:]
        rng.shuffle(shuffled)
        if shuffled != middle and sum(1 for a, b in zip(shuffled, middle) if a != b) >= 2:
            return [frames[0]] + shuffled + [frames[-1]]
    raise RuntimeError("could not disorder frames")


def generate(rng: random.Random | None = None) -> dict[str, Grid]:
    rng = rng or random.Random()
    for _ in range(2000):
        family = rng.choices(
            [
                _single_dot_sequence,
                _growing_triangle_sequence,
                _sliding_diagonal_sequence,
                _two_dot_cycle_sequence,
                _vertical_bar_sweep_sequence,
                _horizontal_bar_sweep_sequence,
                _center_growth_sequence,
                _rightward_fill_sequence,
            ],
            # Reduce the old diagonal grow/move/shrink family and add several
            # clearer perpendicular-motion / growth families for diversity.
            weights=[2, 3, 1, 1, 4, 3, 3, 3],
        )[0]
        ordered = family(rng)
        if len({_signature(f) for f in ordered}) != len(ordered):
            continue
        if sorted(ordered, key=_frame_sort_key) != ordered:
            continue
        if len(ordered) < 4:
            continue
        inp_frames = _make_disordered(ordered, rng)
        inp = _join_frames(inp_frames)
        out = _join_frames(ordered)
        if transform_t35(inp) != out:
            continue
        return {"input": inp, "output": out}
    raise RuntimeError("failed to generate a valid t35 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t35 repair-frame-order task."""

from __future__ import annotations

from typing import List

from generator import transform_t35

Grid = List[List[int]]


def verify_t35(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t35(inp)

generator_py:
"""Generator for Test2/t36: follow the GPS-like relative-turn instructions.

Rule:
- The top row contains a yellow start token, then a sequence of (location color,
  turn color) pairs, then a cyan end token.
- The lower part of the grid is a lattice of gray 3x3 node-tiles separated by
  blank spacer rows/cols. Each node has a colored center.
- Start at the unique yellow node center (4). Move to a neighboring node whose
  color matches the first location token. There is no direction token for the
  start node.
- At each visited internal node, use the paired direction token to turn relative
  to the direction you were just traveling:
    * blue (1) = straight,
    * red (2) = right,
    * green (3) = left.
- Move one edge in that new direction to the next node. The next node must match
  the next location token, and after the final internal node, the final turn
  must take you to the cyan end node (8).
- In the output, the top-row instructions are deleted and the taken route is
  drawn in yellow as a 1-cell-thick polyline through the visited nodes and
  corridors. The cyan destination center remains cyan.

Generation constraints used to keep examples well-formed and unambiguous:
- the full instruction sequence (location + turn) yields exactly one valid path;
- the first move is unambiguous: exactly one neighbor of the yellow start
  matches the first location color;
- after that, the sequence of location colors alone yields at least two valid
  candidate paths, so the turn colors are actually needed;
- the intended path and at least one alternative color-only path have the same
  start, end, and length, but differ in their turn pattern;
- node colors avoid gray/yellow/cyan except for the unique start/end nodes.
"""

from __future__ import annotations

import json
import random
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

Grid = List[List[int]]
Node = Tuple[int, int]

BG = 0
BLUE = 1   # straight
RED = 2    # right
GREEN = 3  # left
YELLOW = 4
GRAY = 5
CYAN = 8
LOC_COLORS = [1, 2, 3, 6, 7, 9]
DIRS = {
    'U': (-1, 0),
    'R': (0, 1),
    'D': (1, 0),
    'L': (0, -1),
}
DIR_ORDER = ['U', 'R', 'D', 'L']
TURN_COLOR = {'S': BLUE, 'R': RED, 'L': GREEN}


def _empty(h: int, w: int, fill: int = 0) -> Grid:
    return [[fill for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _neighbors(node: Node, nrows: int, ncols: int) -> list[Node]:
    r, c = node
    out: list[Node] = []
    for dr, dc in DIRS.values():
        nr, nc = r + dr, c + dc
        if 0 <= nr < nrows and 0 <= nc < ncols:
            out.append((nr, nc))
    return out


def _dir_between(a: Node, b: Node) -> str:
    dr = b[0] - a[0]
    dc = b[1] - a[1]
    for d, (rr, cc) in DIRS.items():
        if (dr, dc) == (rr, cc):
            return d
    raise ValueError('nodes are not orthogonally adjacent')


def _turn_from(prev_dir: str, next_dir: str) -> str:
    i = DIR_ORDER.index(prev_dir)
    j = DIR_ORDER.index(next_dir)
    diff = (j - i) % 4
    if diff == 0:
        return 'S'
    if diff == 1:
        return 'R'
    if diff == 3:
        return 'L'
    raise ValueError('U-turns are not allowed in generated paths')


def _apply_turn(prev_dir: str, turn_color: int) -> str:
    i = DIR_ORDER.index(prev_dir)
    if turn_color == BLUE:
        return prev_dir
    if turn_color == RED:
        return DIR_ORDER[(i + 1) % 4]
    if turn_color == GREEN:
        return DIR_ORDER[(i - 1) % 4]
    raise ValueError('invalid turn color')


def _node_center(node: Node) -> tuple[int, int]:
    r, c = node
    return 3 + 4 * r, 2 + 4 * c


def _parse_nodes(grid: Grid) -> tuple[int, int, dict[Node, int]]:
    h, w = len(grid), len(grid[0])
    if (h - 2) % 4 != 0 or (w - 1) % 4 != 0:
        raise ValueError('grid dimensions do not match the node lattice layout')
    nrows = (h - 2) // 4
    ncols = (w - 1) // 4
    colors: dict[Node, int] = {}
    for r in range(nrows):
        for c in range(ncols):
            rr, cc = _node_center((r, c))
            colors[(r, c)] = grid[rr][cc]
    return nrows, ncols, colors


def _instruction_tokens(grid: Grid) -> list[int]:
    return [v for v in grid[0] if v != BG]


def _find_unique(colors: dict[Node, int], color: int) -> Node:
    nodes = [node for node, v in colors.items() if v == color]
    if len(nodes) != 1:
        raise ValueError(f'expected exactly one node of color {color}, got {len(nodes)}')
    return nodes[0]


def _count_color_only_paths(colors: dict[Node, int], nrows: int, ncols: int, start: Node, end: Node, locs: list[int]) -> int:
    k = len(locs)
    count = 0
    used = {start}

    def dfs(node: Node, idx: int) -> None:
        nonlocal count
        if count >= 50:
            return
        if idx == k:
            if end in _neighbors(node, nrows, ncols) and end not in used:
                count += 1
            return
        target_color = locs[idx]
        for nb in _neighbors(node, nrows, ncols):
            if nb in used or colors[nb] != target_color:
                continue
            used.add(nb)
            dfs(nb, idx + 1)
            used.remove(nb)

    if k == 0:
        return 1 if end in _neighbors(start, nrows, ncols) else 0
    dfs(start, 0)
    return count


def _first_step_is_unambiguous(colors: dict[Node, int], nrows: int, ncols: int, start: Node, first_loc: int) -> bool:
    """Exactly one adjacent node to the start matches the first location token."""
    return sum(1 for nb in _neighbors(start, nrows, ncols) if colors[nb] == first_loc) == 1


def _full_instruction_paths(colors: dict[Node, int], nrows: int, ncols: int, start: Node, end: Node, locs: list[int], turns: list[int]) -> list[list[Node]]:
    k = len(locs)
    out: list[list[Node]] = []
    if k != len(turns):
        raise ValueError('locations and turn counts must match')
    if k == 0:
        return [[start, end]] if end in _neighbors(start, nrows, ncols) else []
    for first in _neighbors(start, nrows, ncols):
        if colors[first] != locs[0]:
            continue
        prev_dir = _dir_between(start, first)
        path = [start, first]
        used = {start, first}
        cur = first
        ok = True
        for i in range(k):
            out_dir = _apply_turn(prev_dir, turns[i])
            dr, dc = DIRS[out_dir]
            nxt = (cur[0] + dr, cur[1] + dc)
            if not (0 <= nxt[0] < nrows and 0 <= nxt[1] < ncols):
                ok = False
                break
            if i == k - 1:
                if nxt != end or nxt in used:
                    ok = False
                    break
                path.append(end)
            else:
                if nxt in used or colors[nxt] != locs[i + 1]:
                    ok = False
                    break
                path.append(nxt)
                used.add(nxt)
                prev_dir = out_dir
                cur = nxt
        if ok:
            out.append(path)
    return out


def transform_t36(grid: Grid) -> Grid:
    if not _rectangular(grid):
        raise ValueError('input grid must be non-empty and rectangular')
    tokens = _instruction_tokens(grid)
    if len(tokens) < 4 or len(tokens) % 2 != 0:
        raise ValueError('instruction strip must have start, end, and one or more pairs')
    if tokens[0] != YELLOW or tokens[-1] != CYAN:
        raise ValueError('instruction strip must start with yellow and end with cyan')
    locs = tokens[1:-1:2]
    turns = tokens[2:-1:2]
    nrows, ncols, colors = _parse_nodes(grid)
    start = _find_unique(colors, YELLOW)
    end = _find_unique(colors, CYAN)
    candidates = _full_instruction_paths(colors, nrows, ncols, start, end, locs, turns)
    if len(candidates) != 1:
        raise ValueError(f'expected exactly one full-instruction path, got {len(candidates)}')
    path = candidates[0]

    out = [row[:] for row in grid]
    # Delete the instruction strip.
    out[0] = [BG] * len(out[0])

    # Draw all but the last segment inclusive of both ends.
    for i in range(len(path) - 2):
        a = path[i]
        b = path[i + 1]
        r1, c1 = _node_center(a)
        r2, c2 = _node_center(b)
        if r1 == r2:
            step = 1 if c2 > c1 else -1
            for c in range(c1, c2 + step, step):
                out[r1][c] = YELLOW
        else:
            step = 1 if r2 > r1 else -1
            for r in range(r1, r2 + step, step):
                out[r][c1] = YELLOW

    # Final segment: stop just before the cyan center.
    if len(path) >= 2:
        a = path[-2]
        b = path[-1]
        r1, c1 = _node_center(a)
        r2, c2 = _node_center(b)
        if r1 == r2:
            step = 1 if c2 > c1 else -1
            for c in range(c1, c2, step):
                out[r1][c] = YELLOW
        else:
            step = 1 if r2 > r1 else -1
            for r in range(r1, r2, step):
                out[r][c1] = YELLOW
        out[r2][c2] = CYAN
    return out


# ---------------------------------------------------------------------------
# Generator
# ---------------------------------------------------------------------------


def _random_simple_path(rng: random.Random, nrows: int, ncols: int, length_edges: int) -> Optional[list[Node]]:
    nodes = [(r, c) for r in range(nrows) for c in range(ncols)]
    start = rng.choice(nodes)
    path = [start]
    used = {start}
    for _ in range(length_edges):
        cur = path[-1]
        options = [nb for nb in _neighbors(cur, nrows, ncols) if nb not in used]
        if not options:
            return None
        nxt = rng.choice(options)
        path.append(nxt)
        used.add(nxt)
    return path


def _all_simple_paths_of_length(start: Node, end: Node, nrows: int, ncols: int, length_edges: int, limit: int = 200) -> list[list[Node]]:
    out: list[list[Node]] = []
    used = {start}
    path = [start]

    def dfs(node: Node, steps: int) -> None:
        if len(out) >= limit:
            return
        if steps == length_edges:
            if node == end:
                out.append(path[:])
            return
        remaining = length_edges - steps
        # Cheap pruning by Manhattan distance.
        md = abs(node[0] - end[0]) + abs(node[1] - end[1])
        if md > remaining or (remaining - md) % 2 != 0:
            return
        for nb in _neighbors(node, nrows, ncols):
            if nb in used:
                continue
            used.add(nb)
            path.append(nb)
            dfs(nb, steps + 1)
            path.pop()
            used.remove(nb)

    dfs(start, 0)
    return out


def _instruction_from_path(path: list[Node], node_colors: dict[Node, int]) -> tuple[list[int], list[int], list[int]]:
    # returns tokens, loc sequence, turns
    locs = [node_colors[path[i]] for i in range(1, len(path) - 1)]
    turns: list[int] = []
    for i in range(1, len(path) - 1):
        prev_dir = _dir_between(path[i - 1], path[i])
        next_dir = _dir_between(path[i], path[i + 1])
        turns.append(TURN_COLOR[_turn_from(prev_dir, next_dir)])
    tokens = [YELLOW]
    for loc, turn in zip(locs, turns):
        tokens.extend([loc, turn])
    tokens.append(CYAN)
    return tokens, locs, turns


def _render_instance(nrows: int, ncols: int, colors: dict[Node, int], tokens: list[int]) -> Grid:
    h = 2 + 4 * nrows
    w = 1 + 4 * ncols
    grid = _empty(h, w, BG)

    # Top-row instruction strip.
    grid[0][0] = tokens[0]
    k = (len(tokens) - 2) // 2
    for i in range(k):
        grid[0][3 + 4 * i] = tokens[1 + 2 * i]
        grid[0][4 + 4 * i] = tokens[2 + 2 * i]
    grid[0][3 + 4 * k] = tokens[-1]

    # Node lattice.
    for r in range(nrows):
        for c in range(ncols):
            top = 2 + 4 * r
            left = 1 + 4 * c
            for dc in range(3):
                grid[top][left + dc] = GRAY
                grid[top + 2][left + dc] = GRAY
            for dr in range(3):
                grid[top + dr][left] = GRAY
                grid[top + dr][left + 2] = GRAY
            grid[top + 1][left + 1] = colors[(r, c)]
    return grid


def generate(rng: random.Random | None = None, nrows: int | None = None, ncols: int | None = None) -> dict[str, Grid]:
    rng = rng or random.Random()
    for _attempt in range(10000):
        rr = nrows if nrows is not None else rng.randint(3, 5)
        cc = ncols if ncols is not None else rng.randint(3, 5)
        length_edges = cc

        # Create intended path P.
        P = _random_simple_path(rng, rr, cc, length_edges)
        if P is None:
            continue
        start, end = P[0], P[-1]
        # Need at least one alternative path Q of the same length between same endpoints.
        all_paths = _all_simple_paths_of_length(start, end, rr, cc, length_edges, limit=500)
        alts = [q for q in all_paths if q != P]
        if not alts:
            continue
        # Prefer an alternative that is internally disjoint from P for easier color assignment.
        disjoint_alts = [q for q in alts if set(q[1:-1]).isdisjoint(set(P[1:-1]))]
        Q = rng.choice(disjoint_alts if disjoint_alts else alts)

        # Assign node colors.
        colors: dict[Node, int] = {}
        for r in range(rr):
            for c in range(cc):
                colors[(r, c)] = rng.choice(LOC_COLORS)
        colors[start] = YELLOW
        colors[end] = CYAN

        internal_colors = [rng.choice(LOC_COLORS) for _ in range(1, len(P) - 1)]
        for i, color in enumerate(internal_colors, start=1):
            colors[P[i]] = color
            colors[Q[i]] = color

        tokens, locs, turns = _instruction_from_path(P, colors)
        # Extra safety: top strip must fit the width pattern, which is ensured by length_edges == ncols.
        if len(tokens) != 2 * cc:
            continue

        # Check ambiguity / uniqueness constraints.
        if not _first_step_is_unambiguous(colors, rr, cc, start, locs[0]):
            continue
        color_only_count = _count_color_only_paths(colors, rr, cc, start, end, locs)
        if color_only_count < 2:
            continue
        full_paths = _full_instruction_paths(colors, rr, cc, start, end, locs, turns)
        if len(full_paths) != 1 or full_paths[0] != P:
            continue

        inp = _render_instance(rr, cc, colors, tokens)
        try:
            out = transform_t36(inp)
        except Exception:
            continue
        if out == inp:
            continue
        return {'input': inp, 'output': out}
    raise RuntimeError('failed to generate a valid t36 sample')


if __name__ == '__main__':
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t36 follow-GPS task."""

from __future__ import annotations

from typing import List

from generator import transform_t36

Grid = List[List[int]]


def verify_t36(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError('input grid must be non-empty')
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError('ragged input grid')
    return transform_t36(inp)

generator_py:
"""Generator for Test2/t37: row-wise shift with top-row recoloring markers.

Rule:
- The input contains a large single-color shape away from the top row and left
  column.
- Cells in the left column mark row shifts:
    * red (2) means shift that row's shape cells right by 1,
    * green (3) means shift that row's shape cells left by 1.
- Cells in the top row mark highlight colors for columns.
- For a row that is shifted, every shape cell in that row moves one step in the
  row's marked direction. Before moving, if the cell's column has a nonzero
  top-row marker, its color is changed to that top-row marker color.
- Shape cells on unmarked rows do not move and are not recolored.
- All markers in the top row and left column are removed in the output.

Generation constraints used to keep examples well-formed and unambiguous:
- the shape is a connected interior blob, usually symmetric and often left
  clean, with a smaller fraction using light symmetric edge erosion and a
  minority being irregular; it is kept at least one cell away from all borders
  so row-shifts stay in bounds;
- top-row highlight colors are chosen distinct from the shift-marker colors to
  reduce confusion;
- every top-row highlight marker affects at least one moving shape cell;
- there is at least one left-shift row and one right-shift row in most samples;
- output rows remain collision-free because each marked row shifts rigidly as a
  whole.
"""

from __future__ import annotations

import json
import random
from collections import deque
from typing import List, Sequence, Tuple

Grid = List[List[int]]
Mask = List[List[int]]

BG = 0
RED = 2
GREEN = 3
HIGHLIGHT_COLORS = [1, 4, 5, 6, 7, 8, 9]
SHAPE_COLORS = [1, 4, 5, 6, 7, 8, 9]


def _empty(h: int, w: int, fill: int = 0) -> Grid:
    return [[fill for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _neighbors4(r: int, c: int, h: int, w: int):
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w:
            yield nr, nc


def _is_connected(mask: Mask) -> bool:
    h, w = len(mask), len(mask[0])
    cells = [(r, c) for r in range(h) for c in range(w) if mask[r][c]]
    if not cells:
        return False
    q = deque([cells[0]])
    seen = {cells[0]}
    while q:
        r, c = q.popleft()
        for nr, nc in _neighbors4(r, c, h, w):
            if mask[nr][nc] and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc))
    return len(seen) == len(cells)


def _shape_rows(mask: Mask) -> list[int]:
    return [r for r, row in enumerate(mask) if any(row)]


def _shape_cols(mask: Mask) -> list[int]:
    h, w = len(mask), len(mask[0])
    return [c for c in range(w) if any(mask[r][c] for r in range(h))]


def _postprocess_blob_mask(mask: Mask, rng: random.Random, allow_irregular: bool, apply_erosion: bool) -> Mask | None:
    h, w = len(mask), len(mask[0])
    if sum(v for row in mask for v in row) < 12:
        return None

    # Optional light random edge erosion while preserving connectivity. For
    # symmetric masks, erode in mirrored pairs so the overall symmetry is preserved.
    if apply_erosion:
        candidates = []
        for r in range(1, h - 1):
            for c in range(1, w - 1):
                if not mask[r][c]:
                    continue
                nbrs = sum(mask[nr][nc] for nr, nc in _neighbors4(r, c, h, w))
                if 1 <= nbrs <= 3:
                    candidates.append((r, c))
        rng.shuffle(candidates)
        remove_budget = rng.randint(1, min(6 if allow_irregular else 4, len(candidates))) if candidates else 0
        used = set()
        for i in range(remove_budget):
            if i >= len(candidates):
                break
            r, c = candidates[i]
            if (r, c) in used:
                continue
            to_remove = [(r, c)]
            if not allow_irregular:
                mr = h - 1 - r
                mc = w - 1 - c
                mirrors = {(r, c), (mr, c), (r, mc), (mr, mc)}
                to_remove = [(rr, cc) for rr, cc in mirrors if 0 <= rr < h and 0 <= cc < w and mask[rr][cc]]
            for rr, cc in to_remove:
                mask[rr][cc] = 0
            if not _is_connected(mask) or sum(v for row in mask for v in row) < 12:
                for rr, cc in to_remove:
                    mask[rr][cc] = 1
            else:
                used.update(to_remove)

    rows = _shape_rows(mask)
    cols = _shape_cols(mask)
    if len(rows) < 4 or len(cols) < 4:
        return None
    # Avoid empty rows/cols inside the occupied span becoming too fragmented.
    if max(rows) - min(rows) + 1 > len(rows) + 3:
        return None
    if max(cols) - min(cols) + 1 > len(cols) + 3:
        return None
    return mask


def _generate_symmetric_blob_mask(rng: random.Random, h: int, w: int, apply_erosion: bool) -> Mask | None:
    bh = rng.randint(max(4, h // 3), max(5, min(h, h - 1)))
    bw = rng.randint(max(4, w // 3), max(5, min(w, w - 1)))
    top = rng.randint(0, h - bh)
    left = rng.randint(0, w - bw)
    cy = top + (bh - 1) / 2.0
    cx = left + (bw - 1) / 2.0
    ay = max(1.8, bh / rng.uniform(2.0, 2.7))
    ax = max(1.8, bw / rng.uniform(2.0, 2.7))
    mode = rng.choice(['ellipse', 'diamond', 'super'])

    mask = _empty(h, w, 0)
    for r in range(top, top + bh):
        for c in range(left, left + bw):
            dy = (r - cy) / ay
            dx = (c - cx) / ax
            if mode == 'ellipse':
                inside = dx * dx + dy * dy <= 1.0
            elif mode == 'diamond':
                inside = abs(dx) + abs(dy) <= 1.05
            else:
                inside = abs(dx) ** 1.6 + abs(dy) ** 1.6 <= 1.2
            if inside:
                mask[r][c] = 1
    return _postprocess_blob_mask(mask, rng, allow_irregular=False, apply_erosion=apply_erosion)


def _generate_irregular_blob_mask(rng: random.Random, h: int, w: int) -> Mask | None:
    bh = rng.randint(max(4, h // 3), max(5, min(h, h - 1)))
    bw = rng.randint(max(4, w // 3), max(5, min(w, w - 1)))
    top = rng.randint(0, h - bh)
    left = rng.randint(0, w - bw)
    cy = top + (bh - 1) / 2.0
    cx = left + (bw - 1) / 2.0
    ay = max(1.8, bh / rng.uniform(2.1, 2.8))
    ax = max(1.8, bw / rng.uniform(2.1, 2.8))
    mode = rng.choice(['ellipse', 'diamond', 'super'])

    mask = _empty(h, w, 0)
    for r in range(top, top + bh):
        for c in range(left, left + bw):
            dy = (r - cy) / ay
            dx = (c - cx) / ax
            if mode == 'ellipse':
                inside = dx * dx + dy * dy <= 1.0
            elif mode == 'diamond':
                inside = abs(dx) + abs(dy) <= 1.05
            else:
                inside = abs(dx) ** 1.6 + abs(dy) ** 1.6 <= 1.2
            if inside:
                mask[r][c] = 1
    return _postprocess_blob_mask(mask, rng, allow_irregular=True, apply_erosion=True)


def _generate_blob_mask(rng: random.Random, h: int, w: int) -> Mask:
    """Generate a connected blob inside an h x w interior canvas.

    About 50% of samples are clean symmetric shapes, 25% are symmetric with
    light edge erosion, and 25% are more irregular.
    """
    for _ in range(4000):
        p = rng.random()
        if p < 0.50:
            mask = _generate_symmetric_blob_mask(rng, h, w, apply_erosion=False)
        elif p < 0.75:
            mask = _generate_symmetric_blob_mask(rng, h, w, apply_erosion=True)
        else:
            mask = _generate_irregular_blob_mask(rng, h, w)
        if mask is not None:
            return mask
    raise RuntimeError('failed to generate blob mask')


def transform_t37(grid: Grid) -> Grid:
    if not _rectangular(grid):
        raise ValueError('input grid must be non-empty and rectangular')
    h, w = len(grid), len(grid[0])
    if h < 3 or w < 3:
        raise ValueError('grid too small')

    top_markers = {c: grid[0][c] for c in range(1, w) if grid[0][c] != BG}
    row_dirs = {}
    for r in range(1, h):
        if grid[r][0] == RED:
            row_dirs[r] = 1
        elif grid[r][0] == GREEN:
            row_dirs[r] = -1
        elif grid[r][0] != BG:
            raise ValueError('left-column markers must be red, green, or blank')

    out = _empty(h, w, BG)
    for r in range(1, h):
        delta = row_dirs.get(r, 0)
        for c in range(1, w):
            v = grid[r][c]
            if v == BG:
                continue
            # Treat every nonzero cell outside marker row/col as part of the shape.
            new_c = c + delta
            if not (1 <= new_c < w):
                raise ValueError('shape moved out of bounds')
            color = top_markers[c] if delta != 0 and c in top_markers else v
            out[r][new_c] = color
    return out


# ---------------------------------------------------------------------------
# Generator
# ---------------------------------------------------------------------------


def _render_input(mask: Mask, shape_color: int, row_markers: dict[int, int], col_markers: dict[int, int]) -> Grid:
    ih, iw = len(mask), len(mask[0])
    h, w = ih + 1, iw + 1
    grid = _empty(h, w, BG)
    for c, color in col_markers.items():
        grid[0][c] = color
    for r, color in row_markers.items():
        grid[r][0] = color
    for r in range(ih):
        for c in range(iw):
            if mask[r][c]:
                grid[r + 1][c + 1] = shape_color
    return grid


def generate(
    rng: random.Random | None = None,
    h: int | None = None,
    w: int | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()
    for _ in range(5000):
        hh = h if h is not None else rng.randint(11, 20)
        ww = w if w is not None else rng.randint(11, 20)
        if not (8 <= hh <= 30 and 8 <= ww <= 30):
            continue

        interior_h, interior_w = hh - 1, ww - 1
        # Blob generated in a cropped interior canvas to keep one-cell margin after shifting.
        small_mask = _generate_blob_mask(rng, interior_h - 2, interior_w - 2)
        mask = _empty(interior_h, interior_w, 0)
        for r in range(interior_h - 2):
            for c in range(interior_w - 2):
                mask[r + 1][c + 1] = small_mask[r][c]

        rows = _shape_rows(mask)
        cols = _shape_cols(mask)
        if len(rows) < 4 or len(cols) < 4:
            continue

        shape_color = rng.choice(SHAPE_COLORS)
        available_highlights = [c for c in HIGHLIGHT_COLORS if c != shape_color]

        # Choose marked rows among occupied rows. Prefer both directions.
        num_marked_rows = rng.randint(2, min(6, len(rows)))
        marked_rows0 = sorted(rng.sample(rows, num_marked_rows))
        row_markers: dict[int, int] = {}
        if num_marked_rows >= 2:
            dirs = [RED, GREEN]
            for _ in range(num_marked_rows - 2):
                dirs.append(rng.choice([RED, GREEN]))
            rng.shuffle(dirs)
        else:
            dirs = [rng.choice([RED, GREEN])]
        for rr0, marker in zip(marked_rows0, dirs):
            row_markers[rr0 + 1] = marker

        # Columns eligible for top markers are occupied by at least one moving cell.
        moving_cols0 = sorted({c for r0 in marked_rows0 for c, v in enumerate(mask[r0]) if v})
        if len(moving_cols0) < 1:
            continue
        num_col_markers = rng.randint(1, min(5, len(moving_cols0), len(available_highlights)))
        chosen_cols0 = sorted(rng.sample(moving_cols0, num_col_markers))
        chosen_colors = rng.sample(available_highlights, num_col_markers)
        col_markers = {c0 + 1: col for c0, col in zip(chosen_cols0, chosen_colors)}

        # Make sure each top marker affects at least one moving cell.
        if not all(any(mask[r0][c0] for r0 in marked_rows0) for c0 in chosen_cols0):
            continue

        inp = _render_input(mask, shape_color, row_markers, col_markers)
        try:
            out = transform_t37(inp)
        except Exception:
            continue
        if out == inp:
            continue

        # Ensure at least one recolor occurs and both directions are often represented.
        recolor_count = sum(
            1
            for r0 in marked_rows0
            for c0 in chosen_cols0
            if mask[r0][c0]
        )
        if recolor_count == 0:
            continue
        if RED not in row_markers.values() or GREEN not in row_markers.values():
            if rng.random() < 0.8:
                continue

        return {'input': inp, 'output': out}
    raise RuntimeError('failed to generate a valid t37 sample')


if __name__ == '__main__':
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t37 row-shift highlight task."""

from __future__ import annotations

from typing import List

from generator import transform_t37

Grid = List[List[int]]


def verify_t37(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError('input grid must be non-empty')
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError('ragged input grid')
    return transform_t37(inp)

generator_py:
"""Generator for Test2/t38: recover the atomic template from an inverse fractal.

Rule:
- The input is a self-similar fractal built from a small atomic template.
- The atomic template is a binary shape of size HxW.
- Starting from a single filled cell, each recursion replaces every filled cell
  by a copy of the whole template, so after depth n the grid size is H^n x W^n.
- Most occupied cells in the final fractal use a base color; a small number of
  occupied cells use a distinct highlight color.
- The output is the atomic template itself, using the base color on occupied
  template cells, except that a template cell is recolored with the highlight
  color iff at least one highlighted input cell belongs to that template
  position's residue class (equivalently: has those coordinates modulo H and W).

Generation constraints used to keep examples well-formed and unambiguous:
- the atomic template is not all-empty or all-full, has at least two occupied
  cells, and has no empty rows or columns;
- the chosen template is rejected if it admits multiple valid fractal
  factorizations under the transform used here;
- highlight cells are a small minority of the occupied cells;
- highlight density is coordinated with template size and fractal size so that
  very small highlighted template sets do not produce many repeated highlights
  in the input;
- at least one template position is highlighted in the output;
- dimensions remain within the ARC 30x30 limit.
"""

from __future__ import annotations

import json
import random
from typing import Iterable, List, Optional, Sequence, Tuple

Grid = List[List[int]]
Mask = List[List[int]]

BG = 0
COLORS = [1, 2, 3, 4, 5, 6, 7, 8, 9]


def _empty(h: int, w: int, fill: int = 0) -> Grid:
    return [[fill for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _nonzero_mask(grid: Grid) -> Mask:
    return [[1 if v != BG else 0 for v in row] for row in grid]


def _mask_dims(mask: Mask) -> tuple[int, int]:
    return len(mask), len(mask[0])


def _mask_equal(a: Mask, b: Mask) -> bool:
    return a == b


def _mask_block(mask: Mask, r0: int, r1: int, c0: int, c1: int) -> Mask:
    return [row[c0:c1] for row in mask[r0:r1]]


def _mask_any(mask: Mask) -> bool:
    return any(v for row in mask for v in row)


def _mask_occupied_positions(mask: Mask) -> list[tuple[int, int]]:
    return [(r, c) for r, row in enumerate(mask) for c, v in enumerate(row) if v]


def _compose_fractal(template: Mask, depth: int) -> Mask:
    """Return the binary fractal mask generated from template at the given depth."""
    cur = [[1]]
    th, tw = _mask_dims(template)
    for _ in range(depth):
        ch, cw = _mask_dims(cur)
        out = _empty(ch * th, cw * tw, 0)
        for r in range(ch):
            for c in range(cw):
                if cur[r][c] == 0:
                    continue
                for tr in range(th):
                    for tc in range(tw):
                        if template[tr][tc]:
                            out[r * th + tr][c * tw + tc] = 1
        cur = out
    return cur


def _valid_decomposition_levels(mask: Mask, H: int, W: int) -> Optional[Mask]:
    """If mask is a fractal generated from some HxW template, return that template mask.

    More precisely, this checks whether repeated HxW decomposition yields the
    same top-level pattern at every level and eventually bottoms out at [[1]].
    """
    h, w = _mask_dims(mask)
    current = [row[:] for row in mask]
    top_pattern: Optional[Mask] = None

    while True:
        ch, cw = _mask_dims(current)
        if ch == 1 and cw == 1:
            return top_pattern if current[0][0] == 1 else None
        if ch % H != 0 or cw % W != 0:
            return None
        bh, bw = ch // H, cw // W
        if bh < 1 or bw < 1:
            return None

        pattern = _empty(H, W, 0)
        rep: Optional[Mask] = None
        for i in range(H):
            for j in range(W):
                block = _mask_block(current, i * bh, (i + 1) * bh, j * bw, (j + 1) * bw)
                has = _mask_any(block)
                if not has:
                    pattern[i][j] = 0
                else:
                    if rep is None:
                        rep = block
                    elif not _mask_equal(rep, block):
                        return None
                    pattern[i][j] = 1
        if rep is None:
            return None
        if top_pattern is None:
            top_pattern = pattern
        elif not _mask_equal(top_pattern, pattern):
            return None
        current = rep


def _infer_template_candidates(mask: Mask) -> list[tuple[int, int, Mask]]:
    h, w = _mask_dims(mask)
    out: list[tuple[int, int, Mask]] = []
    for H in range(2, h + 1):
        for W in range(2, w + 1):
            template = _valid_decomposition_levels(mask, H, W)
            if template is None:
                continue
            out.append((H, W, template))
    return out


def _choose_base_and_highlight(grid: Grid) -> tuple[int, int]:
    nonzero = [v for row in grid for v in row if v != BG]
    colors = sorted(set(nonzero))
    if len(colors) != 2:
        raise ValueError("expected exactly two nonzero colors")
    counts = {c: nonzero.count(c) for c in colors}
    highlight = min(colors, key=lambda c: counts[c])
    base = max(colors, key=lambda c: counts[c])
    if counts[highlight] >= counts[base]:
        raise ValueError("highlight color must be a strict minority")
    return base, highlight


def transform_t38(grid: Grid) -> Grid:
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    base, highlight = _choose_base_and_highlight(grid)
    mask = _nonzero_mask(grid)
    candidates = _infer_template_candidates(mask)
    if not candidates:
        raise ValueError("no valid template factorization found")
    # If multiple factorizations are mathematically possible, use the smallest
    # atomic template. This matches the intended inverse-fractal interpretation
    # and the provided task examples.
    H, W, template = min(candidates, key=lambda x: (x[0] * x[1], x[0], x[1]))

    out = _empty(H, W, BG)
    for r, c in _mask_occupied_positions(template):
        out[r][c] = base

    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == highlight:
                rr, cc = r % H, c % W
                if template[rr][cc]:
                    out[rr][cc] = highlight
    return out


# ---------------------------------------------------------------------------
# Generator
# ---------------------------------------------------------------------------


def _random_template(rng: random.Random, H: int, W: int) -> Mask:
    for _ in range(5000):
        mask = [[1 if rng.random() < 0.45 else 0 for _ in range(W)] for _ in range(H)]
        occ = sum(v for row in mask for v in row)
        if occ < 2 or occ == H * W:
            continue
        # Require every row and every column to contain at least one occupied cell,
        # so the atomic template has no empty rows or columns.
        if any(sum(mask[r][c] for c in range(W)) == 0 for r in range(H)):
            continue
        if any(sum(mask[r][c] for r in range(H)) == 0 for c in range(W)):
            continue
        # Avoid degenerate single-row/col occupancy only.
        occ_rows = {r for r, row in enumerate(mask) for c, v in enumerate(row) if v}
        occ_cols = {c for r, row in enumerate(mask) for c, v in enumerate(row) if v}
        if len(occ_rows) == 1 or len(occ_cols) == 1:
            continue
        return mask
    raise RuntimeError("failed to generate template")


def _render_colored(mask: Mask, base: int, highlight: int, highlighted_positions: set[tuple[int, int]]) -> Grid:
    h, w = _mask_dims(mask)
    out = _empty(h, w, BG)
    for r in range(h):
        for c in range(w):
            if not mask[r][c]:
                continue
            out[r][c] = highlight if (r, c) in highlighted_positions else base
    return out


def _choose_output_highlight_count(template_occ_count: int, fractal_occ_count: int, depth: int, rng: random.Random) -> int:
    """Choose how many template cells are highlighted in the output.

    Larger fractals tend to get slightly more highlighted template positions, so
    tiny highlighted-template sets are less common on big inputs.
    """
    max_k = min(template_occ_count, max(1, template_occ_count // 2 + 1))
    if fractal_occ_count >= 90 or depth >= 4:
        min_k = min(max_k, 3)
    elif fractal_occ_count >= 30 or depth >= 3:
        min_k = min(max_k, 2)
    else:
        min_k = 1
    return rng.randint(min_k, max_k)


def _highlight_leaf_positions(
    fractal_mask: Mask,
    H: int,
    W: int,
    template_occ: list[tuple[int, int]],
    desired_output_highlights: set[tuple[int, int]],
    rng: random.Random,
) -> set[tuple[int, int]]:
    """Choose a sparse set of highlighted leaf cells.

    Every highlighted template residue is represented at least once. For small
    highlighted template sets (especially 1-2 cells), avoid repeating the same
    residue many times across the input fractal, since that can make the template
    too easy to spot.
    """
    leaves_by_residue: dict[tuple[int, int], list[tuple[int, int]]] = {(r, c): [] for (r, c) in template_occ}
    fh, fw = _mask_dims(fractal_mask)
    for r in range(fh):
        for c in range(fw):
            if fractal_mask[r][c]:
                residue = (r % H, c % W)
                if residue in leaves_by_residue:
                    leaves_by_residue[residue].append((r, c))

    desired_list = sorted(desired_output_highlights)
    chosen: set[tuple[int, int]] = set()
    chosen_per_residue: dict[tuple[int, int], int] = {res: 0 for res in desired_list}

    # Ensure each desired template position gets at least one highlighted leaf.
    for residue in desired_list:
        pick = rng.choice(leaves_by_residue[residue])
        chosen.add(pick)
        chosen_per_residue[residue] += 1

    k = len(desired_list)
    occ_count = sum(v for row in fractal_mask for v in row)

    # Coordinate extra input highlights with template-highlight count and input size.
    if k <= 2:
        extras_budget = 0
        per_residue_cap = 1
    elif k == 3:
        extras_budget = rng.randint(0, 1 if occ_count < 80 else 2)
        per_residue_cap = 2
    else:
        size_factor = 0 if occ_count < 40 else (1 if occ_count < 120 else 2)
        extras_budget = rng.randint(0, min(k - 1 + size_factor, 2 * k))
        per_residue_cap = 2 if occ_count < 120 else 3

    selectable = [res for res in desired_list if len(leaves_by_residue[res]) > chosen_per_residue[res]]
    for _ in range(extras_budget):
        selectable = [
            res for res in desired_list
            if chosen_per_residue[res] < per_residue_cap
            and len(leaves_by_residue[res]) > chosen_per_residue[res]
        ]
        if not selectable:
            break
        residue = rng.choice(selectable)
        candidates = [p for p in leaves_by_residue[residue] if p not in chosen]
        if not candidates:
            continue
        pick = rng.choice(candidates)
        chosen.add(pick)
        chosen_per_residue[residue] += 1
    return chosen


def generate(
    rng: random.Random | None = None,
    template_h: int | None = None,
    template_w: int | None = None,
    depth: int | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()

    for _attempt in range(5000):
        H = template_h if template_h is not None else rng.randint(2, 4)
        W = template_w if template_w is not None else rng.randint(2, 4)
        n = depth if depth is not None else rng.randint(2, 4)
        if H ** n > 30 or W ** n > 30:
            continue

        template = _random_template(rng, H, W)
        fractal_mask = _compose_fractal(template, n)
        occ_count = sum(v for row in fractal_mask for v in row)
        template_occ = _mask_occupied_positions(template)
        if occ_count <= len(template_occ):
            continue

        # Choose colors.
        base, highlight = rng.sample(COLORS, 2)
        # Choose a non-empty subset of template positions to appear highlighted in the output,
        # coordinating this with fractal size so larger inputs tend to have somewhat richer
        # highlight structure.
        k = _choose_output_highlight_count(len(template_occ), occ_count, n, rng)
        desired_output_highlights = set(rng.sample(template_occ, k))
        leaf_highlights = _highlight_leaf_positions(fractal_mask, H, W, template_occ, desired_output_highlights, rng)
        if not leaf_highlights:
            continue
        # Keep highlight color a clear minority.
        if len(leaf_highlights) * 3 >= occ_count * 2:  # < 2/3? stronger than necessary; effectively tiny minority here
            continue

        inp = _render_colored(fractal_mask, base, highlight, leaf_highlights)
        out = _render_colored(template, base, highlight, desired_output_highlights)

        # Reject ambiguous template factorizations under the verifier.
        try:
            got = transform_t38(inp)
        except Exception:
            continue
        if got != out:
            continue
        candidates = _infer_template_candidates(_nonzero_mask(inp))
        fh, fw = len(inp), len(inp[0])
        nontrivial = [c for c in candidates if c[0] * c[1] < fh * fw]
        if not nontrivial:
            continue
        best_area = min(c[0] * c[1] for c in nontrivial)
        best = [c for c in nontrivial if c[0] * c[1] == best_area]
        if len(best) != 1:
            continue
        bH, bW, bT = best[0]
        if bH != H or bW != W or bT != template:
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to generate a valid t38 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t38 inverse fractal template extraction."""

from __future__ import annotations

from typing import List

from generator import transform_t38

Grid = List[List[int]]


def verify_t38(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t38(inp)

generator_py:
"""Generator for Test2/t39: shortest directed path across cannon-islands.

Rule:
- The input contains several 3x3 hollow square "islands" laid out on a grid.
- The island borders use one outline color.
- A red cell (color 2) at the midpoint of one side of an island is a one-way
  cannon, allowing movement from that island to the adjacent island in that
  direction.
- One island center contains a yellow cell (color 4), the source.
- One island center contains a cyan cell (color 8), the target.
- Follow the unique shortest directed path from source to target.
- In the output, every red cannon used on that path is recolored gray (color 5),
  the source center is cleared to background, and the target center is recolored
  yellow.

Generation constraints used to keep examples well-formed and unambiguous:
- islands form a complete rectangular lattice of 2..5 rows and 2..5 columns;
- only valid in-bounds one-step directional cannons are used;
- there is exactly one source and one target;
- a path from source to target exists and the shortest directed path is unique;
- generated tasks prefer nontrivial paths of length at least 2;
- most islands are given at least one outgoing cannon so red markers are spread
  more uniformly across the lattice, making the true path less visually obvious;
- most generated examples also contain at least one longer alternative directed
  route from source to target, so the task is not just following the only
  apparent non-cycling path.
"""

from __future__ import annotations

import json
import random
from collections import deque
from typing import Dict, List, Tuple

Grid = List[List[int]]
Node = Tuple[int, int]

BG = 0
RED = 2
YELLOW = 4
GRAY = 5
CYAN = 8
OUTLINE_COLORS = [1, 3, 6, 7, 9]
DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPPOSITE = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
MID_POS = {
    'U': (0, 1),
    'D': (2, 1),
    'L': (1, 0),
    'R': (1, 2),
}


class Island:
    def __init__(self, top: int, left: int, center: int, mids: Dict[str, int]):
        self.top = top
        self.left = left
        self.center = center
        self.mids = dict(mids)


def _empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _is_island_at(grid: Grid, r: int, c: int) -> bool:
    h, w = len(grid), len(grid[0])
    if r + 2 >= h or c + 2 >= w:
        return False
    border_positions = [(0,0),(0,1),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)]
    for dr, dc in border_positions:
        if grid[r + dr][c + dc] == BG:
            return False
    center = grid[r + 1][c + 1]
    if center not in (BG, YELLOW, CYAN):
        return False
    return True


def _parse_islands(grid: Grid) -> tuple[dict[Node, Island], list[int], list[int]]:
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    h, w = len(grid), len(grid[0])
    found: list[tuple[int, int]] = []
    for r in range(h - 2):
        for c in range(w - 2):
            if _is_island_at(grid, r, c):
                found.append((r, c))
    if not found:
        raise ValueError("no islands found")

    # islands are separated, so every valid top-left is distinct.
    rows = sorted({r for r, _ in found})
    cols = sorted({c for _, c in found})
    islands: dict[Node, Island] = {}
    for r, c in found:
        ri = rows.index(r)
        ci = cols.index(c)
        sub = [grid[r + rr][c:c + 3] for rr in range(3)]
        center = sub[1][1]
        mids = {d: sub[dr][dc] for d, (dr, dc) in MID_POS.items()}
        islands[(ri, ci)] = Island(r, c, center, mids)

    # Validate a full rectangular lattice.
    for ri in range(len(rows)):
        for ci in range(len(cols)):
            if (ri, ci) not in islands:
                raise ValueError("islands must form a complete rectangular lattice")
    return islands, rows, cols


def _graph_from_islands(islands: dict[Node, Island], nrows: int, ncols: int) -> dict[Node, list[tuple[Node, str]]]:
    graph: dict[Node, list[tuple[Node, str]]] = {node: [] for node in islands}
    for (r, c), isl in islands.items():
        for d, val in isl.mids.items():
            if val != RED:
                continue
            dr, dc = DIRS[d]
            nb = (r + dr, c + dc)
            if 0 <= nb[0] < nrows and 0 <= nb[1] < ncols:
                graph[(r, c)].append((nb, d))
    return graph


def _find_source_target(islands: dict[Node, Island]) -> tuple[Node, Node]:
    src = [node for node, isl in islands.items() if isl.center == YELLOW]
    tgt = [node for node, isl in islands.items() if isl.center == CYAN]
    if len(src) != 1 or len(tgt) != 1:
        raise ValueError("expected exactly one yellow source and one cyan target")
    return src[0], tgt[0]


def _shortest_path_unique(graph: dict[Node, list[tuple[Node, str]]], src: Node, tgt: Node) -> tuple[list[tuple[Node, str]], bool]:
    dist: dict[Node, int] = {src: 0}
    count: dict[Node, int] = {src: 1}
    parent: dict[Node, tuple[Node, str]] = {}
    q = deque([src])
    while q:
        u = q.popleft()
        for v, d in graph[u]:
            nd = dist[u] + 1
            if v not in dist:
                dist[v] = nd
                count[v] = count[u]
                parent[v] = (u, d)
                q.append(v)
            elif nd == dist[v]:
                count[v] = min(2, count[v] + count[u])
                # keep existing parent for deterministic reconstruction if needed
    if tgt not in dist:
        return [], False
    path: list[tuple[Node, str]] = []
    cur = tgt
    while cur != src:
        prev, d = parent[cur]
        path.append((prev, d))
        cur = prev
    path.reverse()
    return path, count[tgt] == 1


def _has_longer_alternative_path(
    graph: dict[Node, list[tuple[Node, str]]],
    src: Node,
    tgt: Node,
    shortest_len: int,
    max_extra: int = 6,
) -> bool:
    """Return whether there exists a simple source->target path longer than the shortest.

    We only search up to shortest_len + max_extra to keep generation fast.
    That is sufficient for generating plausible decoy routes.
    """
    max_len = shortest_len + max_extra

    def dfs(node: Node, depth: int, seen: set[Node]) -> bool:
        if depth > max_len:
            return False
        if node == tgt:
            return depth > shortest_len
        # Even in the best case, we can only increase length from here. If we have
        # already exceeded the cap, stop.
        for nxt, _ in graph[node]:
            if nxt in seen:
                continue
            seen.add(nxt)
            if dfs(nxt, depth + 1, seen):
                return True
            seen.remove(nxt)
        return False

    return dfs(src, 0, {src})


def transform_t39(grid: Grid) -> Grid:
    islands, rows, cols = _parse_islands(grid)
    nrows, ncols = len(rows), len(cols)
    graph = _graph_from_islands(islands, nrows, ncols)
    src, tgt = _find_source_target(islands)
    path, reachable_unique = _shortest_path_unique(graph, src, tgt)
    if not path:
        raise ValueError("no directed path from source to target")
    # Provided tasks / generated tasks are unique; if not unique, the generator avoids it.
    out = [row[:] for row in grid]
    # Clear source center.
    src_isl = islands[src]
    out[src_isl.top + 1][src_isl.left + 1] = BG
    # Recolor used cannons gray.
    for node, d in path:
        isl = islands[node]
        dr, dc = MID_POS[d]
        out[isl.top + dr][isl.left + dc] = GRAY
    # Recolor target center yellow.
    tgt_isl = islands[tgt]
    out[tgt_isl.top + 1][tgt_isl.left + 1] = YELLOW
    return out


# ---------------------------------------------------------------------------
# Generator
# ---------------------------------------------------------------------------


def _grid_graph_neighbors(node: Node, nrows: int, ncols: int) -> list[tuple[Node, str]]:
    r, c = node
    out = []
    for d, (dr, dc) in DIRS.items():
        nr, nc = r + dr, c + dc
        if 0 <= nr < nrows and 0 <= nc < ncols:
            out.append(((nr, nc), d))
    return out


def _add_uniform_background_edges(edges: dict[Node, set[str]], nodes: list[Node], nrows: int, ncols: int, rng: random.Random) -> None:
    """Densify outgoing edges across the whole lattice for visual uniformity."""
    shuffled = nodes[:]
    rng.shuffle(shuffled)

    # First pass: give most islands at least one outgoing cannon.
    for node in shuffled:
        neighbors = _grid_graph_neighbors(node, nrows, ncols)
        if not neighbors:
            continue
        if len(edges[node]) == 0 and rng.random() < 0.92:
            # Prefer directions not directly heading toward the target path structure, to create decoys.
            _, d = rng.choice(neighbors)
            edges[node].add(d)

    # Second pass: many islands get a second cannon as well.
    rng.shuffle(shuffled)
    for node in shuffled:
        neighbors = _grid_graph_neighbors(node, nrows, ncols)
        available = [d for _, d in neighbors if d not in edges[node]]
        if not available:
            continue
        min_desired = 1
        max_desired = min(3, len(neighbors))
        desired = min_desired
        if len(neighbors) >= 2 and rng.random() < 0.68:
            desired = 2
        if len(neighbors) >= 3 and rng.random() < 0.18:
            desired = 3
        desired = min(desired, max_desired)
        while len(edges[node]) < desired and available:
            d = rng.choice(available)
            edges[node].add(d)
            available.remove(d)


def _edge_distribution_ok(edges: dict[Node, set[str]], nrows: int, ncols: int) -> bool:
    nodes = [(r, c) for r in range(nrows) for c in range(ncols)]
    active_nodes = sum(1 for node in nodes if edges[node])
    total_nodes = len(nodes)
    min_active_ratio = 0.60 if total_nodes <= 9 else 0.72
    if active_nodes < int((total_nodes * min_active_ratio) + 0.999999):
        return False

    # Avoid visually empty rows/columns in larger lattices.
    if nrows >= 3:
        row_active = [sum(1 for c in range(ncols) if edges[(r, c)]) for r in range(nrows)]
        if min(row_active) < max(1, ncols // 3):
            return False
    if ncols >= 3:
        col_active = [sum(1 for r in range(nrows) if edges[(r, c)]) for c in range(ncols)]
        if min(col_active) < max(1, nrows // 3):
            return False
    return True


def _render_instance(nrows: int, ncols: int, gap_r: int, gap_c: int, margin_t: int, margin_l: int,
                     outline: int, edges: dict[Node, set[str]], src: Node, tgt: Node) -> Grid:
    h = margin_t * 2 + nrows * 3 + (nrows - 1) * gap_r
    w = margin_l * 2 + ncols * 3 + (ncols - 1) * gap_c
    grid = _empty(h, w)
    for r in range(nrows):
        for c in range(ncols):
            top = margin_t + r * (3 + gap_r)
            left = margin_l + c * (3 + gap_c)
            # outline
            for dc in range(3):
                grid[top][left + dc] = outline
                grid[top + 2][left + dc] = outline
            for dr in range(3):
                grid[top + dr][left] = outline
                grid[top + dr][left + 2] = outline
            # cannons
            for d in edges[(r, c)]:
                dr, dc = MID_POS[d]
                grid[top + dr][left + dc] = RED
            # centers
            if (r, c) == src:
                grid[top + 1][left + 1] = YELLOW
            elif (r, c) == tgt:
                grid[top + 1][left + 1] = CYAN
    return grid


def generate(
    rng: random.Random | None = None,
    nrows: int | None = None,
    ncols: int | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()

    for _attempt in range(5000):
        rr = nrows if nrows is not None else rng.randint(2, 5)
        cc = ncols if ncols is not None else rng.randint(2, 5)
        if rr * cc < 4:
            # still allow 2x2 minimum; no special rejection here
            pass
        gap_r = rng.randint(1, 2)
        gap_c = rng.randint(1, 2)
        margin_t = rng.randint(1, 2)
        margin_l = rng.randint(1, 2)
        h = margin_t * 2 + rr * 3 + (rr - 1) * gap_r
        w = margin_l * 2 + cc * 3 + (cc - 1) * gap_c
        if h > 30 or w > 30:
            continue

        nodes = [(r, c) for r in range(rr) for c in range(cc)]
        src, tgt = rng.sample(nodes, 2)
        edges: dict[Node, set[str]] = {node: set() for node in nodes}

        # Add a guaranteed random simple path first.
        cur = src
        visited = {src}
        forced_path: list[tuple[Node, str]] = []
        # Bias a wandering path toward tgt.
        for _ in range(rr * cc * 3):
            if cur == tgt:
                break
            choices = _grid_graph_neighbors(cur, rr, cc)
            # Prefer unvisited neighbors; with some probability prefer moves reducing manhattan distance.
            unvisited = [x for x in choices if x[0] not in visited]
            if not unvisited:
                unvisited = choices
            def score(item):
                (nr, nc), _ = item
                return abs(nr - tgt[0]) + abs(nc - tgt[1]) + rng.random() * 0.35
            if rng.random() < 0.7:
                nxt, d = min(unvisited, key=score)
            else:
                nxt, d = rng.choice(unvisited)
            forced_path.append((cur, d))
            edges[cur].add(d)
            cur = nxt
            visited.add(cur)
        if cur != tgt:
            # Finish with a direct Manhattan walk.
            while cur != tgt:
                cr, cc2 = cur
                if cr < tgt[0]:
                    d = 'D'
                elif cr > tgt[0]:
                    d = 'U'
                elif cc2 < tgt[1]:
                    d = 'R'
                else:
                    d = 'L'
                edges[cur].add(d)
                forced_path.append((cur, d))
                dr, dc = DIRS[d]
                cur = (cur[0] + dr, cur[1] + dc)
        # Add extra background edges so the red markers are visually spread around the whole grid.
        _add_uniform_background_edges(edges, nodes, rr, cc, rng)
        if not _edge_distribution_ok(edges, rr, cc):
            continue

        graph = {node: [((node[0] + DIRS[d][0], node[1] + DIRS[d][1]), d) for d in sorted(edges[node])] for node in nodes}
        path, unique = _shortest_path_unique(graph, src, tgt)
        if not path or not unique:
            continue
        if len(path) < 2:
            continue

        has_alt = _has_longer_alternative_path(graph, src, tgt, len(path), max_extra=max(4, rr + cc))
        # Prefer samples with at least one longer decoy path, but still allow a
        # minority of simpler cases for variety.
        if not has_alt and rng.random() < 0.8:
            continue

        outline = rng.choice(OUTLINE_COLORS)
        inp = _render_instance(rr, cc, gap_r, gap_c, margin_t, margin_l, outline, edges, src, tgt)
        try:
            out = transform_t39(inp)
        except Exception:
            continue
        if out == inp:
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to generate a valid t39 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t39 directed island shortest path."""

from __future__ import annotations

from typing import List

from generator import transform_t39

Grid = List[List[int]]


def verify_t39(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t39(inp)

generator_py:
"""Generator for Test2/t40: remove red-marked hollow blocks and unsupported blocks.

Rule:
- The input contains several hollow rectangular blocks.
- Some blocks are marked red by filling the entire interior of the block with
  red cells (color 2).
- In the output, every red-marked block is removed.
- Then any remaining block that is no longer supported is also removed,
  recursively.
- A block is supported if either:
    * its bottom edge lies on the bottom row of the grid, or
    * there exists at least one remaining block whose top edge is exactly one
      row below its bottom edge, with overlapping horizontal span.

Generation constraints used to keep examples well-formed and unambiguous:
- every object is a single hollow axis-aligned rectangle with size at least 3x3;
- blocks do not overlap; blocks on the same level are separated by gaps;
- colors are unique across blocks in generated samples to simplify perception;
- the full interior of each marked block is filled red;
- support relations form a layered DAG, so the cascade is unambiguous.
"""

from __future__ import annotations

import json
import random
from collections import deque
from dataclasses import dataclass
from typing import List, Tuple

Grid = List[List[int]]

BG = 0
RED = 2
USABLE_COLORS = [1, 3, 4, 5, 6, 7, 8, 9]


@dataclass(frozen=True)
class Block:
    color: int
    r0: int
    r1: int
    c0: int
    c1: int
    marked: bool

    @property
    def width(self) -> int:
        return self.c1 - self.c0 + 1

    @property
    def height(self) -> int:
        return self.r1 - self.r0 + 1


def _empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _outline_cells(r0: int, r1: int, c0: int, c1: int) -> set[tuple[int, int]]:
    cells: set[tuple[int, int]] = set()
    for c in range(c0, c1 + 1):
        cells.add((r0, c))
        cells.add((r1, c))
    for r in range(r0, r1 + 1):
        cells.add((r, c0))
        cells.add((r, c1))
    return cells


def _connected_components_of_color(grid: Grid, color: int) -> list[set[tuple[int, int]]]:
    h, w = len(grid), len(grid[0])
    seen: set[tuple[int, int]] = set()
    comps: list[set[tuple[int, int]]] = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp: set[tuple[int, int]] = set()
            while q:
                rr, cc = q.popleft()
                comp.add((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append(comp)
    return comps


def _parse_blocks(grid: Grid) -> list[Block]:
    if not _rectangular(grid):
        raise ValueError("grid must be non-empty and rectangular")
    h, w = len(grid), len(grid[0])
    blocks: list[Block] = []

    colors = sorted({v for row in grid for v in row if v not in (BG, RED)})
    for color in colors:
        for comp in _connected_components_of_color(grid, color):
            rs = [r for r, _ in comp]
            cs = [c for _, c in comp]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            if r1 - r0 + 1 < 3 or c1 - c0 + 1 < 3:
                raise ValueError("every block must be at least 3x3")
            outline = _outline_cells(r0, r1, c0, c1)
            if comp != outline:
                raise ValueError("non-red component is not a hollow rectangle outline")
            marked = any(grid[r][c] == RED for r in range(r0 + 1, r1) for c in range(c0 + 1, c1))
            blocks.append(Block(color=color, r0=r0, r1=r1, c0=c0, c1=c1, marked=marked))

    # Validate that every red cell lies inside exactly one block interior.
    red_positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == RED]
    for r, c in red_positions:
        owners = [b for b in blocks if b.r0 < r < b.r1 and b.c0 < c < b.c1]
        if len(owners) != 1:
            raise ValueError("every red cell must lie in the interior of exactly one block")
    return blocks


def _supports(lower: Block, upper: Block) -> bool:
    if lower.r0 != upper.r1 + 1:
        return False
    return max(lower.c0, upper.c0) <= min(lower.c1, upper.c1)


def transform_t40(grid: Grid) -> Grid:
    blocks = _parse_blocks(grid)
    h, w = len(grid), len(grid[0])

    removed: set[int] = {i for i, b in enumerate(blocks) if b.marked}
    changed = True
    while changed:
        changed = False
        for i, blk in enumerate(blocks):
            if i in removed:
                continue
            if blk.r1 == h - 1:
                continue  # rests on ground
            supported = any(j not in removed and _supports(blocks[j], blk) for j in range(len(blocks)) if j != i)
            if not supported:
                removed.add(i)
                changed = True

    out = _empty(h, w)
    for i, blk in enumerate(blocks):
        if i in removed:
            continue
        for r, c in _outline_cells(blk.r0, blk.r1, blk.c0, blk.c1):
            out[r][c] = blk.color
    return out


# ---------------------------------------------------------------------------
# Generator
# ---------------------------------------------------------------------------


def _intervals_nonoverlapping(intervals: list[tuple[int, int]]) -> bool:
    intervals = sorted(intervals)
    return all(intervals[i][1] < intervals[i + 1][0] for i in range(len(intervals) - 1))


def _choose_red_cells(blk: Block, rng: random.Random) -> list[tuple[int, int]]:
    del rng  # marking is deterministic: mark the whole interior
    return [(r, c) for r in range(blk.r0 + 1, blk.r1) for c in range(blk.c0 + 1, blk.c1)]


def _render_blocks(h: int, w: int, blocks: list[Block], red_cells_by_idx: dict[int, list[tuple[int, int]]]) -> Grid:
    grid = _empty(h, w)
    for idx, blk in enumerate(blocks):
        for r, c in _outline_cells(blk.r0, blk.r1, blk.c0, blk.c1):
            if grid[r][c] != BG:
                raise ValueError("block overlap in render")
            grid[r][c] = blk.color
        for r, c in red_cells_by_idx.get(idx, []):
            if grid[r][c] != BG:
                raise ValueError("red-cell overlap in render")
            grid[r][c] = RED
    return grid


def generate(
    rng: random.Random | None = None,
    h: int | None = None,
    w: int | None = None,
    num_levels: int | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()

    for _attempt in range(4000):
        hh = h if h is not None else rng.randint(12, 22)
        ww = w if w is not None else rng.randint(12, 24)
        levels = num_levels if num_levels is not None else rng.randint(2, 4)
        if not (6 <= hh <= 30 and 6 <= ww <= 30):
            continue

        blocks: list[Block] = []
        colors = USABLE_COLORS[:]
        rng.shuffle(colors)
        color_idx = 0

        # Level 0: base blocks on the ground.
        level_blocks: list[list[int]] = []
        current_level_indices: list[int] = []
        num_base = rng.randint(1, 3)
        x = rng.randint(0, 2)
        intervals: list[tuple[int, int]] = []
        base_top_rows: list[int] = []
        for _ in range(num_base):
            max_base_width = min(8, ww - x - 1)
            if max_base_width < 4:
                break
            width = rng.randint(4, max_base_width)
            height = rng.randint(3, 6)
            c0, c1 = x, x + width - 1
            r1 = hh - 1
            r0 = r1 - height + 1
            if r0 < 0:
                break
            intervals.append((c0, c1))
            if not _intervals_nonoverlapping(intervals):
                intervals.pop()
                break
            blk = Block(color=colors[color_idx], r0=r0, r1=r1, c0=c0, c1=c1, marked=False)
            color_idx += 1
            blocks.append(blk)
            current_level_indices.append(len(blocks) - 1)
            base_top_rows.append(r0)
            x = c1 + rng.randint(1, 3) + 1
            if x + 3 >= ww or color_idx >= len(colors):
                break
        if not current_level_indices:
            continue
        level_blocks.append(current_level_indices)

        # Higher levels.
        prev_level = current_level_indices
        while len(level_blocks) < levels and color_idx < len(colors):
            parent_top = min(blocks[i].r0 for i in prev_level)
            if parent_top < 4:
                break
            count_here = rng.randint(1, min(2, len(prev_level)))
            new_level: list[int] = []
            used_intervals: list[tuple[int, int]] = []
            support_groups = []
            shuffled = prev_level[:]
            rng.shuffle(shuffled)
            # partition some supports into 1- or 2-block groups
            while shuffled and len(support_groups) < count_here:
                take = 1 if len(shuffled) == 1 or rng.random() < 0.65 else 2
                grp = sorted(shuffled[:take], key=lambda i: blocks[i].c0)
                del shuffled[:take]
                support_groups.append(grp)
            for grp in support_groups:
                sup_r0 = min(blocks[i].r0 for i in grp)
                if len({blocks[i].r0 for i in grp}) != 1:
                    continue
                upper_height = rng.randint(3, min(5, sup_r0 - 1))
                r1 = sup_r0 - 1
                r0 = r1 - upper_height + 1
                if r0 < 0:
                    continue
                union_c0 = min(blocks[i].c0 for i in grp)
                union_c1 = max(blocks[i].c1 for i in grp)
                max_width = min(8, union_c1 - union_c0 + 1)
                if max_width < 3:
                    continue
                width = rng.randint(3, max_width)
                start_min = union_c0
                start_max = union_c1 - width + 1
                if start_min > start_max:
                    continue
                c0 = rng.randint(start_min, start_max)
                c1 = c0 + width - 1
                used_intervals.append((c0, c1))
                if not _intervals_nonoverlapping(used_intervals):
                    used_intervals.pop()
                    continue
                blk = Block(color=colors[color_idx], r0=r0, r1=r1, c0=c0, c1=c1, marked=False)
                color_idx += 1
                blocks.append(blk)
                new_level.append(len(blocks) - 1)
                if color_idx >= len(colors):
                    break
            if not new_level:
                break
            level_blocks.append(new_level)
            prev_level = new_level

        if len(blocks) < 2:
            continue

        # Mark some blocks, preferring non-base blocks but allowing any.
        candidate_ids = list(range(len(blocks)))
        non_ground = [i for i, b in enumerate(blocks) if b.r1 < hh - 1]
        rng.shuffle(candidate_ids)
        rng.shuffle(non_ground)
        marked_ids: set[int] = set()
        if non_ground:
            marked_ids.add(non_ground[0])
        marked_target = rng.randint(1, min(3, max(1, len(blocks) // 2)))
        for i in candidate_ids:
            if len(marked_ids) >= marked_target:
                break
            if rng.random() < 0.35:
                marked_ids.add(i)
        # Create marked versions.
        rendered_blocks: list[Block] = []
        red_cells_by_idx: dict[int, list[tuple[int, int]]] = {}
        for i, b in enumerate(blocks):
            marked = i in marked_ids
            rendered_blocks.append(Block(color=b.color, r0=b.r0, r1=b.r1, c0=b.c0, c1=b.c1, marked=marked))
            if marked:
                red_cells_by_idx[i] = _choose_red_cells(rendered_blocks[-1], rng)

        try:
            inp = _render_blocks(hh, ww, rendered_blocks, red_cells_by_idx)
            out = transform_t40(inp)
        except Exception:
            continue

        if out == inp:
            continue

        # Ensure at least one marked block is removed and, ideally, some unmarked cascade occurs.
        parsed = _parse_blocks(inp)
        initially_marked = {i for i, b in enumerate(parsed) if b.marked}
        remaining_out_colors = {(r, c) for r in range(hh) for c in range(ww) if out[r][c] != BG}
        # Count removed blocks by comparing whether any outline cell remains.
        removed_ids = set()
        for i, b in enumerate(parsed):
            if not any((r, c) in remaining_out_colors for r, c in _outline_cells(b.r0, b.r1, b.c0, b.c1)):
                removed_ids.add(i)
        if not initially_marked <= removed_ids:
            continue
        if len(removed_ids) < len(initially_marked):
            continue
        # Prefer examples with at least one cascade block beyond the marked set.
        if len(removed_ids - initially_marked) == 0 and rng.random() < 0.8:
            continue

        return {"input": inp, "output": out}

    raise RuntimeError("failed to generate a valid t40 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

