generator_py:
"""Generator for Test2/t43: reverse the front-to-back occlusion order of objects.

Rule:
- The input shows several recognizable objects stacked/occluding one another.
- Their front-to-back order is uniquely identifiable from the visible overlaps.
- Reconstruct each full object, then reverse the depth order: the previous
  backmost object becomes frontmost, and the previous frontmost object becomes
  backmost.

Generation constraints used to keep examples well-formed and unambiguous:
- objects come from recognizable families: filled rectangles, rectangle outlines,
  straight lines, filled diamonds, plus/cross shapes, and exact masks;
- hidden parts of an object occur only beneath another non-background object;
- the overlap graph induces a unique front-to-back order;
- there is at least one true overlap/occlusion;
- generated samples reject side-touching-only contacts that can look like mere adjacency rather than occlusion.
"""

from __future__ import annotations

import json
import random
from collections import defaultdict, deque
from typing import List, Sequence, Set, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]
Mask = Set[Cell]

BG = 0
COLORS = list(range(1, 10))
NEI4 = [(1, 0), (-1, 0), (0, 1), (0, -1)]


def _empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _visible_cells_by_color(grid: Grid) -> dict[int, Mask]:
    out: dict[int, Mask] = defaultdict(set)
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != BG:
                out[v].add((r, c))
    return dict(out)


def _bbox(cells: Mask) -> tuple[int, int, int, int]:
    rs = [r for r, _ in cells]
    cs = [c for _, c in cells]
    return min(rs), max(rs), min(cs), max(cs)


def _bbox_cells(min_r: int, max_r: int, min_c: int, max_c: int) -> Mask:
    return {(r, c) for r in range(min_r, max_r + 1) for c in range(min_c, max_c + 1)}


def _rect_outline_cells(min_r: int, max_r: int, min_c: int, max_c: int) -> Mask:
    cells: Mask = set()
    for c in range(min_c, max_c + 1):
        cells.add((min_r, c))
        cells.add((max_r, c))
    for r in range(min_r, max_r + 1):
        cells.add((r, min_c))
        cells.add((r, max_c))
    return cells


def _diamond_cells(min_r: int, max_r: int, min_c: int, max_c: int) -> Mask:
    if (max_r - min_r) % 2 != 0 or (max_c - min_c) % 2 != 0:
        return set()
    cr = (min_r + max_r) // 2
    cc = (min_c + max_c) // 2
    radius_r = max_r - cr
    radius_c = max_c - cc
    if radius_r != radius_c:
        return set()
    rad = radius_r
    return {
        (r, c)
        for r in range(min_r, max_r + 1)
        for c in range(min_c, max_c + 1)
        if abs(r - cr) + abs(c - cc) <= rad
    }


def _plus_cells(min_r: int, max_r: int, min_c: int, max_c: int) -> Mask:
    h = max_r - min_r + 1
    w = max_c - min_c + 1
    if h < 3 or w < 3:
        return set()
    center_rows = {min_r + h // 2} if h % 2 else {min_r + h // 2 - 1, min_r + h // 2}
    center_cols = {min_c + w // 2} if w % 2 else {min_c + w // 2 - 1, min_c + w // 2}
    return {
        (r, c)
        for r in range(min_r, max_r + 1)
        for c in range(min_c, max_c + 1)
        if r in center_rows or c in center_cols
    }


def _right_triangle_outline_cells(min_r: int, max_r: int, min_c: int, max_c: int, orientation: str) -> Mask:
    """Return a square right-triangle outline.

    Orientations identify the right-angle corner: tl, tr, bl, br.
    """
    height = max_r - min_r
    width = max_c - min_c
    if height != width or height < 2:
        return set()
    cells: Mask = set()
    if orientation == "tl":
        for c in range(min_c, max_c + 1):
            cells.add((min_r, c))
        for r in range(min_r, max_r + 1):
            cells.add((r, min_c))
            cells.add((r, max_c - (r - min_r)))
    elif orientation == "tr":
        for c in range(min_c, max_c + 1):
            cells.add((min_r, c))
        for r in range(min_r, max_r + 1):
            cells.add((r, max_c))
            cells.add((r, min_c + (r - min_r)))
    elif orientation == "bl":
        for c in range(min_c, max_c + 1):
            cells.add((max_r, c))
        for r in range(min_r, max_r + 1):
            cells.add((r, min_c))
            cells.add((r, min_c + (max_r - r)))
    elif orientation == "br":
        for c in range(min_c, max_c + 1):
            cells.add((max_r, c))
        for r in range(min_r, max_r + 1):
            cells.add((r, max_c))
            cells.add((r, max_c - (max_r - r)))
    else:
        raise ValueError(orientation)
    return cells


def _extras_are_occluded(mask: Mask, visible: Mask, nonzero: Mask) -> bool:
    return visible <= mask and (mask - visible) <= (nonzero - visible)


def _touches_all_bbox_sides(visible: Mask, min_r: int, max_r: int, min_c: int, max_c: int) -> bool:
    return (
        any(r == min_r for r, _ in visible)
        and any(r == max_r for r, _ in visible)
        and any(c == min_c for _, c in visible)
        and any(c == max_c for _, c in visible)
    )


def _infer_mask_for_color(visible: Mask, nonzero: Mask) -> Mask:
    min_r, max_r, min_c, max_c = _bbox(visible)
    candidates: list[tuple[int, int, str, Mask]] = []

    def add(priority: int, name: str, mask: Mask) -> None:
        if mask and _extras_are_occluded(mask, visible, nonzero):
            candidates.append((priority, len(mask - visible), name, mask))

    if min_r == max_r or min_c == max_c:
        add(0, "line", _bbox_cells(min_r, max_r, min_c, max_c))

    rect = _bbox_cells(min_r, max_r, min_c, max_c)
    if _touches_all_bbox_sides(visible, min_r, max_r, min_c, max_c):
        add(1, "filled_rect", rect)

    outline = _rect_outline_cells(min_r, max_r, min_c, max_c)
    if visible <= outline and _touches_all_bbox_sides(visible, min_r, max_r, min_c, max_c):
        add(1, "rect_outline", outline)

    # Filled diamond. Try the visible bounding box and small one-cell expansions,
    # since an extremal diamond cell can be hidden by a front object.
    for er0 in range(max(0, min_r - 1), min_r + 1):
        for er1 in range(max_r, max_r + 2):
            for ec0 in range(max(0, min_c - 1), min_c + 1):
                for ec1 in range(max_c, max_c + 2):
                    diamond = _diamond_cells(er0, er1, ec0, ec1)
                    if diamond and visible <= diamond:
                        add(1, "diamond", diamond)

    plus = _plus_cells(min_r, max_r, min_c, max_c)
    if plus and visible <= plus and _touches_all_bbox_sides(visible, min_r, max_r, min_c, max_c):
        add(1, "plus", plus)

    # Right-triangle outlines. These cover examples where an object is a
    # recognizable triangular outline, with one leg and the diagonal partly
    # hidden by objects in front.
    for er0 in range(max(0, min_r - 1), min_r + 1):
        for er1 in range(max_r, max_r + 2):
            for ec0 in range(max(0, min_c - 1), min_c + 1):
                for ec1 in range(max_c, max_c + 2):
                    for orient in ("tl", "tr", "bl", "br"):
                        tri = _right_triangle_outline_cells(er0, er1, ec0, ec1, orient)
                        if tri and visible <= tri:
                            add(1, "right_triangle", tri)

    add(9, "exact", set(visible))

    if not candidates:
        raise ValueError("could not infer a recognizable object mask")
    candidates.sort(key=lambda x: (x[0], x[1], x[2]))
    return set(candidates[0][3])


def _infer_masks(grid: Grid) -> dict[int, Mask]:
    by_color = _visible_cells_by_color(grid)
    nonzero = set().union(*by_color.values()) if by_color else set()
    return {color: _infer_mask_for_color(cells, nonzero) for color, cells in by_color.items()}


def _front_order(grid: Grid, masks: dict[int, Mask]) -> list[int]:
    visible = _visible_cells_by_color(grid)
    colors = sorted(masks)
    edges: dict[int, set[int]] = {c: set() for c in colors}
    indeg = {c: 0 for c in colors}

    for front_color, cells in visible.items():
        for cell in cells:
            for back_color, mask in masks.items():
                if back_color != front_color and cell in mask:
                    if back_color not in edges[front_color]:
                        edges[front_color].add(back_color)
                        indeg[back_color] += 1

    order: list[int] = []
    ready = sorted([c for c in colors if indeg[c] == 0])
    while ready:
        c = ready.pop(0)
        order.append(c)
        for nb in sorted(edges[c]):
            indeg[nb] -= 1
            if indeg[nb] == 0:
                ready.append(nb)
                ready.sort()

    if len(order) != len(colors):
        raise ValueError("occlusion order contains a cycle")
    return order




def _overlap_size(mask_a: Mask, mask_b: Mask) -> int:
    return len(mask_a & mask_b)


def _touching_nonoverlap(mask_a: Mask, mask_b: Mask) -> bool:
    """Return True if two masks side-touch without overlapping.

    Such contacts are visually ambiguous in this task because they can look like
    either simple adjacency or an occluded edge.
    """
    if mask_a & mask_b:
        return False
    for r, c in mask_a:
        for dr, dc in NEI4:
            if (r + dr, c + dc) in mask_b:
                return True
    return False


def _adjacent_visible_color_pairs(grid: Grid) -> set[tuple[int, int]]:
    h, w = len(grid), len(grid[0])
    pairs: set[tuple[int, int]] = set()
    for r in range(h):
        for c in range(w):
            a = grid[r][c]
            if a == BG:
                continue
            for dr, dc in ((1, 0), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    b = grid[nr][nc]
                    if b != BG and b != a:
                        pairs.add(tuple(sorted((a, b))))
    return pairs


def _has_ambiguous_contacts(inp: Grid, masks: dict[int, Mask]) -> bool:
    """Heuristic filter for ambiguity.

    Reject cases where two different objects are visibly side-adjacent but their
    full masks never overlap. Those are the examples most likely to read as
    mere touching rather than one object covering another. Also reject very
    weak overlaps (single-cell intersections) when the pair is visibly adjacent.
    """
    for a, b in _adjacent_visible_color_pairs(inp):
        ma, mb = masks[a], masks[b]
        ov = _overlap_size(ma, mb)
        if ov <= 1:
            return True
    for colors in [(a, b) for a in masks for b in masks if a < b]:
        a, b = colors
        if _touching_nonoverlap(masks[a], masks[b]):
            return True
    return False

def _render(h: int, w: int, masks: dict[int, Mask], paint_order: Sequence[int]) -> Grid:
    grid = _empty(h, w)
    for color in paint_order:
        for r, c in masks[color]:
            if 0 <= r < h and 0 <= c < w:
                grid[r][c] = color
    return grid


def transform_t43(grid: Grid) -> Grid:
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    h, w = len(grid), len(grid[0])
    masks = _infer_masks(grid)
    # `order` is front-to-back in the input. Painting in that order reverses
    # the stack because later-painted objects become frontmost.
    order = _front_order(grid, masks)
    return _render(h, w, masks, order)


# ---------------------------------------------------------------------------
# Generator
# ---------------------------------------------------------------------------


def _make_filled_rect(r0: int, c0: int, h: int, w: int) -> Mask:
    return {(r, c) for r in range(r0, r0 + h) for c in range(c0, c0 + w)}


def _make_rect_outline(r0: int, c0: int, h: int, w: int) -> Mask:
    return _rect_outline_cells(r0, r0 + h - 1, c0, c0 + w - 1)


def _make_line_horizontal(r: int, c0: int, length: int) -> Mask:
    return {(r, c) for c in range(c0, c0 + length)}


def _make_line_vertical(c: int, r0: int, length: int) -> Mask:
    return {(r, c) for r in range(r0, r0 + length)}


def _make_diamond(cr: int, cc: int, radius: int) -> Mask:
    return {
        (r, c)
        for r in range(cr - radius, cr + radius + 1)
        for c in range(cc - radius, cc + radius + 1)
        if abs(r - cr) + abs(c - cc) <= radius
    }


def _random_mask(rng: random.Random, h: int, w: int, kind: str) -> Mask:
    if kind == "filled_rect":
        rh = rng.randint(3, max(3, min(7, h - 2)))
        rw = rng.randint(3, max(3, min(8, w - 2)))
        return _make_filled_rect(rng.randint(1, h - rh - 1), rng.randint(1, w - rw - 1), rh, rw)
    if kind == "rect_outline":
        rh = rng.randint(5, max(5, min(10, h - 2)))
        rw = rng.randint(5, max(5, min(10, w - 2)))
        return _make_rect_outline(rng.randint(1, h - rh - 1), rng.randint(1, w - rw - 1), rh, rw)
    if kind == "hline":
        length = rng.randint(6, max(6, w - 2))
        return _make_line_horizontal(rng.randint(1, h - 2), rng.randint(0, w - length), length)
    if kind == "vline":
        length = rng.randint(6, max(6, h - 2))
        return _make_line_vertical(rng.randint(1, w - 2), rng.randint(0, h - length), length)
    if kind == "diamond":
        rad = rng.randint(2, max(2, min(4, (h - 3) // 2, (w - 3) // 2)))
        return _make_diamond(rng.randint(rad + 1, h - rad - 2), rng.randint(rad + 1, w - rad - 2), rad)
    raise ValueError(kind)


def generate(
    rng: random.Random | None = None,
    h: int | None = None,
    w: int | None = None,
    num_objects: int | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()
    for _attempt in range(8000):
        hh = h if h is not None else rng.randint(12, 22)
        ww = w if w is not None else rng.randint(12, 22)
        n = num_objects if num_objects is not None else rng.randint(2, 4)
        if n < 2:
            continue
        colors = rng.sample(COLORS, n)

        kind_pool = ["filled_rect", "rect_outline", "hline", "vline", "diamond"]
        kinds = [rng.choice(kind_pool) for _ in range(n)]
        masks: dict[int, Mask] = {}
        ok = True
        for color, kind in zip(colors, kinds):
            try:
                masks[color] = _random_mask(rng, hh, ww, kind)
            except Exception:
                ok = False
                break
        if not ok:
            continue

        back_to_front = colors[:]
        rng.shuffle(back_to_front)

        # Require overlaps and visibility for all objects.
        overlap_pairs = 0
        for i in range(n):
            for j in range(i + 1, n):
                if masks[colors[i]] & masks[colors[j]]:
                    overlap_pairs += 1
        if overlap_pairs < n - 1:
            continue

        inp = _render(hh, ww, masks, back_to_front)
        if _has_ambiguous_contacts(inp, masks):
            continue
        visible = _visible_cells_by_color(inp)
        if set(visible) != set(colors):
            continue

        try:
            inferred_masks = _infer_masks(inp)
            if inferred_masks != masks:
                continue
            out = transform_t43(inp)
        except Exception:
            continue

        expected = _render(hh, ww, masks, list(reversed(back_to_front)))
        if out != expected:
            continue
        if out == inp:
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to generate a valid t43 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t43 reverse occlusion order rule."""

from __future__ import annotations

from typing import List

from generator import transform_t43

Grid = List[List[int]]


def verify_t43(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t43(inp)

generator_py:
"""Generator for Test2/t44: count rotations needed to align outline gaps.

Rule:
- The input has two cells of one marker color: one at the center of a nest of
  concentric square outlines, and one on the grid edge aligned horizontally or
  vertically with the center.
- Each square outline has exactly one gap at the midpoint of one side.
- Starting from the innermost outline and moving outward, count how many
  clockwise 90-degree rotations are needed to move that outline's gap to the
  side facing the edge marker / clear path.
- The output has width 3 and one row per outline. A count n in {0,1,2,3} is
  encoded by filling the first n cells of the row with that outline's color.

Generation constraints used to keep examples well-formed and unambiguous:
- exactly one marker color appears exactly twice, once at the center and once
  on an aligned edge;
- every outline is a square border centered on the center marker;
- every outline has exactly one midpoint-side gap;
- outlines are sorted by radius from inner to outer;
- same-colored outlines are not adjacent/merged into one component.
"""

from __future__ import annotations

import json
import random
from collections import deque
from typing import Iterable, List, Sequence, Set, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]

BG = 0
COLORS = list(range(1, 10))
NEI4 = [(-1, 0), (1, 0), (0, -1), (0, 1)]

SIDE_TO_INDEX = {"top": 0, "right": 1, "bottom": 2, "left": 3}
INDEX_TO_SIDE = {v: k for k, v in SIDE_TO_INDEX.items()}


def _empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _is_edge(cell: Cell, h: int, w: int) -> bool:
    r, c = cell
    return r == 0 or c == 0 or r == h - 1 or c == w - 1


def _find_markers(grid: Grid) -> tuple[int, Cell, Cell, str]:
    """Return marker color, center cell, edge cell, and target side."""
    h, w = len(grid), len(grid[0])
    by_color: dict[int, list[Cell]] = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != BG:
                by_color.setdefault(v, []).append((r, c))

    candidates: list[tuple[int, Cell, Cell, str]] = []
    for color, cells in by_color.items():
        if len(cells) != 2:
            continue
        edge_cells = [p for p in cells if _is_edge(p, h, w)]
        center_cells = [p for p in cells if not _is_edge(p, h, w)]
        if len(edge_cells) != 1 or len(center_cells) != 1:
            continue
        edge = edge_cells[0]
        center = center_cells[0]
        if edge[0] == center[0]:
            target = "left" if edge[1] < center[1] else "right"
        elif edge[1] == center[1]:
            target = "top" if edge[0] < center[0] else "bottom"
        else:
            continue
        candidates.append((color, center, edge, target))

    if len(candidates) != 1:
        raise ValueError("expected exactly one aligned center/edge marker pair")
    return candidates[0]


def _components(grid: Grid, exclude_color: int) -> list[tuple[int, set[Cell]]]:
    h, w = len(grid), len(grid[0])
    seen: set[Cell] = set()
    comps: list[tuple[int, set[Cell]]] = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (BG, exclude_color) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells: set[Cell] = set()
            while q:
                rr, cc = q.popleft()
                cells.add((rr, cc))
                for dr, dc in NEI4:
                    nr, nc = rr + dr, cc + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and (nr, nc) not in seen
                        and grid[nr][nc] == color
                    ):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append((color, cells))
    return comps


def _border_cells(center: Cell, radius: int) -> set[Cell]:
    cr, cc = center
    cells: set[Cell] = set()
    for c in range(cc - radius, cc + radius + 1):
        cells.add((cr - radius, c))
        cells.add((cr + radius, c))
    for r in range(cr - radius, cr + radius + 1):
        cells.add((r, cc - radius))
        cells.add((r, cc + radius))
    return cells


def _gap_side(center: Cell, gap: Cell, radius: int) -> str:
    cr, cc = center
    r, c = gap
    if r == cr - radius and c == cc:
        return "top"
    if r == cr and c == cc + radius:
        return "right"
    if r == cr + radius and c == cc:
        return "bottom"
    if r == cr and c == cc - radius:
        return "left"
    raise ValueError("gap is not at the midpoint of a side")


def _parse_outlines(grid: Grid, marker_color: int, center: Cell) -> list[tuple[int, int, str]]:
    """Return outline tuples (radius, color, gap_side), sorted inner to outer."""
    outlines: list[tuple[int, int, str]] = []
    for color, cells in _components(grid, marker_color):
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)
        cr, cc = center
        if (min_r + max_r) != 2 * cr or (min_c + max_c) != 2 * cc:
            raise ValueError("outline is not centered on marker")
        radius = max_r - cr
        if radius <= 0 or radius != cr - min_r or radius != max_c - cc or radius != cc - min_c:
            raise ValueError("outline bounding box is not a centered square")

        border = _border_cells(center, radius)
        if not cells <= border:
            raise ValueError("outline contains cells away from its square border")
        missing = border - cells
        if len(missing) != 1:
            raise ValueError("each outline must have exactly one gap")
        side = _gap_side(center, next(iter(missing)), radius)
        outlines.append((radius, color, side))

    if not outlines:
        raise ValueError("expected at least one outline")
    outlines.sort(key=lambda x: x[0])
    if len({r for r, _, _ in outlines}) != len(outlines):
        raise ValueError("each outline must have a distinct radius")
    return outlines


def _count_rotations(gap_side: str, target_side: str) -> int:
    return (SIDE_TO_INDEX[target_side] - SIDE_TO_INDEX[gap_side]) % 4


def transform_t44(grid: Grid) -> Grid:
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    marker_color, center, _edge, target_side = _find_markers(grid)
    outlines = _parse_outlines(grid, marker_color, center)

    out: Grid = []
    for _radius, color, gap in outlines:
        n = _count_rotations(gap, target_side)
        out.append([color if c < n else BG for c in range(3)])
    return out


def _draw_outline(grid: Grid, center: Cell, radius: int, color: int, gap_side: str) -> None:
    cells = _border_cells(center, radius)
    cr, cc = center
    gap_by_side = {
        "top": (cr - radius, cc),
        "right": (cr, cc + radius),
        "bottom": (cr + radius, cc),
        "left": (cr, cc - radius),
    }
    gap = gap_by_side[gap_side]
    for r, c in cells:
        if (r, c) != gap:
            grid[r][c] = color


def _edge_for_direction(center: Cell, h: int, w: int, target_side: str) -> Cell:
    r, c = center
    if target_side == "top":
        return (0, c)
    if target_side == "bottom":
        return (h - 1, c)
    if target_side == "left":
        return (r, 0)
    if target_side == "right":
        return (r, w - 1)
    raise ValueError(target_side)


def generate(
    rng: random.Random | None = None,
    num_outlines: int | None = None,
    target_side: str | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()

    for _attempt in range(1000):
        n = num_outlines if num_outlines is not None else rng.randint(3, 6)
        target = target_side if target_side is not None else rng.choice(["top", "right", "bottom", "left"])
        if target not in SIDE_TO_INDEX:
            raise ValueError("target_side must be top/right/bottom/left")

        # Use step 1 or 2 between radii; step 2 gives visually separated rings.
        step = rng.choice([1, 2])
        start_radius = rng.randint(1, 2)
        radii = [start_radius + step * i for i in range(n)]
        max_r = radii[-1]

        margin_before = rng.randint(1, 3)
        margin_after = rng.randint(1, 3)
        if target in ("top", "bottom"):
            h = max_r + 1 + max_r + margin_before + margin_after + 1
            center_r = margin_before + max_r
            w = 2 * max_r + 1 + rng.randint(2, 5)
            center_c = rng.randint(max_r, w - max_r - 1)
        else:
            w = max_r + 1 + max_r + margin_before + margin_after + 1
            center_c = margin_before + max_r
            h = 2 * max_r + 1 + rng.randint(2, 5)
            center_r = rng.randint(max_r, h - max_r - 1)

        center = (center_r, center_c)
        edge = _edge_for_direction(center, h, w, target)
        marker_color = rng.choice(COLORS)
        outline_palette = [c for c in COLORS if c != marker_color]
        if len(outline_palette) < 2:
            continue

        grid = _empty(h, w)
        prev_color = None
        outline_specs: list[tuple[int, int, str]] = []
        for radius in radii:
            color_choices = [c for c in outline_palette if c != prev_color]
            color = rng.choice(color_choices)
            gap = rng.choice(["top", "right", "bottom", "left"])
            outline_specs.append((radius, color, gap))
            prev_color = color

        for radius, color, gap in outline_specs:
            _draw_outline(grid, center, radius, color, gap)

        grid[center_r][center_c] = marker_color
        grid[edge[0]][edge[1]] = marker_color

        try:
            out = transform_t44(grid)
        except Exception:
            continue

        # Prefer varied encodings, including at least one zero and one nonzero row.
        counts = [sum(1 for v in row if v != BG) for row in out]
        if len(set(counts)) < 2:
            continue
        if not any(c == 0 for c in counts):
            continue
        if not any(c == 3 for c in counts):
            continue
        return {"input": grid, "output": out}

    raise RuntimeError("failed to generate a valid t44 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t44 gap-rotation-count rule."""

from __future__ import annotations

from typing import List

from generator import transform_t44

Grid = List[List[int]]


def verify_t44(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t44(inp)

generator_py:
"""Generator for Test2/t45: toggle shadow and light from a yellow marker.

Rule:
- A yellow (4) marker is placed at a corner or the midpoint of one edge.
- The grid has a single non-black/non-yellow background color.
- Non-background, non-yellow cells cast black shadows away from the marker:
    * from an edge midpoint, shadows are horizontal/vertical;
    * from a corner, shadows are diagonal.
- Yellow cells do not cast black shadows.
- If a yellow cell lies in another object's shadow, it shines light in the same
  direction instead: consecutive background cells after it are restored to the
  background color until the ray hits another non-background object.

Generation constraints used to keep examples well-formed and unambiguous:
- exactly one yellow marker appears at an allowed boundary location;
- the background is a single dominant non-black/non-yellow color;
- there are at least two non-yellow colored objects;
- examples include visible shadows;
- many generated examples include shadowed yellow light-cells that clear part
  of an otherwise black shadow ray.
"""

from __future__ import annotations

import json
import random
from collections import Counter
from typing import List, Sequence, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]

BG_OUT = 0
YELLOW = 4
COLORS = list(range(1, 10))


def _empty(h: int, w: int, color: int) -> Grid:
    return [[color for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _allowed_marker_positions(h: int, w: int) -> list[Cell]:
    positions = [(0, 0), (0, w - 1), (h - 1, 0), (h - 1, w - 1)]
    if w % 2 == 1:
        positions.extend([(0, w // 2), (h - 1, w // 2)])
    if h % 2 == 1:
        positions.extend([(h // 2, 0), (h // 2, w - 1)])
    # Deduplicate for very small grids.
    return sorted(set(positions))


def _find_marker(grid: Grid) -> Cell:
    h, w = len(grid), len(grid[0])
    candidates = [p for p in _allowed_marker_positions(h, w) if grid[p[0]][p[1]] == YELLOW]
    if len(candidates) != 1:
        raise ValueError("expected exactly one yellow marker at a corner or edge midpoint")
    return candidates[0]


def _direction_from_marker(marker: Cell, h: int, w: int) -> tuple[int, int]:
    r, c = marker
    if r == 0 and c == 0:
        return (1, 1)
    if r == 0 and c == w - 1:
        return (1, -1)
    if r == h - 1 and c == 0:
        return (-1, 1)
    if r == h - 1 and c == w - 1:
        return (-1, -1)
    if r == 0:
        return (1, 0)
    if r == h - 1:
        return (-1, 0)
    if c == 0:
        return (0, 1)
    if c == w - 1:
        return (0, -1)
    raise ValueError("marker is not at an allowed location")


def _infer_background(grid: Grid) -> int:
    counts = Counter(v for row in grid for v in row if v not in (BG_OUT, YELLOW))
    if not counts:
        raise ValueError("expected a non-yellow background color")
    return counts.most_common(1)[0][0]


def _ray_cells(start: Cell, dr: int, dc: int, h: int, w: int) -> list[Cell]:
    r, c = start
    out: list[Cell] = []
    r += dr
    c += dc
    while 0 <= r < h and 0 <= c < w:
        out.append((r, c))
        r += dr
        c += dc
    return out


def transform_t45(grid: Grid) -> Grid:
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    h, w = len(grid), len(grid[0])
    marker = _find_marker(grid)
    dr, dc = _direction_from_marker(marker, h, w)
    bg = _infer_background(grid)

    shadowed: set[Cell] = set()
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != bg and val != YELLOW:
                shadowed.update(_ray_cells((r, c), dr, dc, h, w))

    out = [row[:] for row in grid]
    for r, c in shadowed:
        if grid[r][c] == bg:
            out[r][c] = BG_OUT

    # Shadowed yellow cells act as light sources: restore background along the
    # ray, but only through original background cells. Light does not pass
    # through colored objects.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == YELLOW and (r, c) in shadowed:
                for rr, cc in _ray_cells((r, c), dr, dc, h, w):
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = bg

    return out


def _place_cells(grid: Grid, cells: Sequence[Cell], color: int) -> None:
    h, w = len(grid), len(grid[0])
    for r, c in cells:
        if 0 <= r < h and 0 <= c < w:
            grid[r][c] = color


def _random_object(rng: random.Random, h: int, w: int, max_size: int = 9) -> list[Cell]:
    start = (rng.randrange(h), rng.randrange(w))
    target = rng.randint(1, max_size)
    cells = {start}
    while len(cells) < target:
        frontier = set()
        for r, c in cells:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in cells:
                    frontier.add((nr, nc))
        if not frontier:
            break
        cells.add(rng.choice(list(frontier)))
    return sorted(cells)


def _choose_marker(rng: random.Random, h: int, w: int) -> Cell:
    positions = _allowed_marker_positions(h, w)
    return rng.choice(positions)


def _place_light_cell_in_shadow(
    rng: random.Random,
    grid: Grid,
    shadow_source: Cell,
    dr: int,
    dc: int,
    bg: int,
) -> bool:
    h, w = len(grid), len(grid[0])
    ray = _ray_cells(shadow_source, dr, dc, h, w)
    candidates = [(r, c) for r, c in ray[:-1] if grid[r][c] == bg]
    rng.shuffle(candidates)
    for r, c in candidates:
        # Need at least one background cell after it before another object.
        rr, cc = r + dr, c + dc
        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
            grid[r][c] = YELLOW
            return True
    return False


def generate(
    rng: random.Random | None = None,
    h: int | None = None,
    w: int | None = None,
    background: int | None = None,
    marker: Cell | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()

    for _attempt in range(2000):
        hh = h if h is not None else rng.randint(8, 23)
        ww = w if w is not None else rng.randint(8, 23)
        if hh < 5 or ww < 5:
            continue

        bg_choices = [c for c in COLORS if c != YELLOW]
        bg = background if background is not None else rng.choice(bg_choices)
        if bg in (BG_OUT, YELLOW):
            continue

        grid = _empty(hh, ww, bg)
        mark = marker if marker is not None else _choose_marker(rng, hh, ww)
        if mark not in _allowed_marker_positions(hh, ww):
            continue
        grid[mark[0]][mark[1]] = YELLOW
        dr, dc = _direction_from_marker(mark, hh, ww)

        obj_colors = [c for c in COLORS if c not in (bg, YELLOW)]
        rng.shuffle(obj_colors)
        placed_sources: list[Cell] = []
        num_objects = rng.randint(3, 7)
        for i in range(num_objects):
            color = obj_colors[i % len(obj_colors)]
            cells = _random_object(rng, hh, ww, max_size=rng.randint(2, 10))
            cells = [p for p in cells if p != mark]
            if not cells:
                continue
            _place_cells(grid, cells, color)
            placed_sources.extend(cells)

        # Often include a yellow cell in an existing shadow, to demonstrate light.
        if placed_sources and rng.random() < 0.75:
            rng.shuffle(placed_sources)
            for src in placed_sources:
                if _place_light_cell_in_shadow(rng, grid, src, dr, dc, bg):
                    break

        # Ensure the boundary marker is still the only allowed-position yellow.
        for p in _allowed_marker_positions(hh, ww):
            if p != mark and grid[p[0]][p[1]] == YELLOW:
                grid[p[0]][p[1]] = bg

        try:
            out = transform_t45(grid)
        except Exception:
            continue

        changed = sum(
            1
            for r in range(hh)
            for c in range(ww)
            if out[r][c] != grid[r][c]
        )
        if changed < max(4, (hh * ww) // 25):
            continue
        non_bg_colors = {v for row in grid for v in row if v not in (bg, YELLOW)}
        if len(non_bg_colors) < 2:
            continue
        return {"input": grid, "output": out}

    raise RuntimeError("failed to generate a valid t45 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

