generator_py:
"""Generator for Test2/t46: 4-color sudoku over 2x2 quadrants.

Rule:
- The grid is always 5x5.
- The middle row and middle column are gray (5), splitting the grid into four
  2x2 quadrants.
- The four non-gray colors must fill the sixteen non-gray cells.
- No row, column, or 2x2 quadrant may contain the same color twice.
- Inputs reveal exactly four colored cells, one of each color; the output is
  the unique valid completion.

Generation constraints used to keep examples well-formed and unambiguous:
- the gray cross is fixed at row 2 and column 2;
- exactly four distinct non-gray/non-black colors are used;
- exactly four givens are shown, one per color;
- the partial puzzle has exactly one valid completion;
- generated givens are spread across at least three quadrants when possible.
"""

from __future__ import annotations

import itertools
import json
import random
from typing import Dict, List, Sequence, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]

BG = 0
GRAY = 5
NON_GRAY_CELLS: list[Cell] = [
    (r, c)
    for r in (0, 1, 3, 4)
    for c in (0, 1, 3, 4)
]
PALETTE_COLORS = [1, 2, 3, 4, 6, 7, 8, 9]


def _empty() -> Grid:
    grid = [[BG for _ in range(5)] for _ in range(5)]
    for i in range(5):
        grid[2][i] = GRAY
        grid[i][2] = GRAY
    return grid


def _quadrant_index(r: int, c: int) -> int:
    if r < 2 and c < 2:
        return 0
    if r < 2 and c > 2:
        return 1
    if r > 2 and c < 2:
        return 2
    if r > 2 and c > 2:
        return 3
    raise ValueError("gray-cross cell has no quadrant")


def _valid_grid_shape(grid: Grid) -> bool:
    return len(grid) == 5 and all(len(row) == 5 for row in grid)


def _check_gray_cross(grid: Grid) -> None:
    if not _valid_grid_shape(grid):
        raise ValueError("grid must be 5x5")
    for i in range(5):
        if grid[2][i] != GRAY or grid[i][2] != GRAY:
            raise ValueError("grid must contain a gray center row and column")


def _colors_from_grid(grid: Grid) -> list[int]:
    colors = sorted({grid[r][c] for r, c in NON_GRAY_CELLS if grid[r][c] not in (BG, GRAY)})
    if len(colors) != 4:
        raise ValueError("expected exactly four non-gray colors")
    return colors


def _is_consistent_assignment(assign: Dict[Cell, int]) -> bool:
    # Rows.
    for r in (0, 1, 3, 4):
        vals = [assign[(r, c)] for c in (0, 1, 3, 4) if (r, c) in assign]
        if len(vals) != len(set(vals)):
            return False

    # Columns.
    for c in (0, 1, 3, 4):
        vals = [assign[(r, c)] for r in (0, 1, 3, 4) if (r, c) in assign]
        if len(vals) != len(set(vals)):
            return False

    # Quadrants.
    for q in range(4):
        vals = [
            v
            for (r, c), v in assign.items()
            if _quadrant_index(r, c) == q
        ]
        if len(vals) != len(set(vals)):
            return False

    return True


def _solve(colors: Sequence[int], givens: Dict[Cell, int], max_solutions: int = 2) -> list[Dict[Cell, int]]:
    cells = NON_GRAY_CELLS[:]
    solutions: list[Dict[Cell, int]] = []

    if not _is_consistent_assignment(givens):
        return []

    rows = {r: set() for r in (0, 1, 3, 4)}
    cols = {c: set() for c in (0, 1, 3, 4)}
    quads = {q: set() for q in range(4)}
    assign: Dict[Cell, int] = {}

    for cell, val in givens.items():
        r, c = cell
        q = _quadrant_index(r, c)
        if val not in colors or val in rows[r] or val in cols[c] or val in quads[q]:
            return []
        rows[r].add(val)
        cols[c].add(val)
        quads[q].add(val)
        assign[cell] = val

    def candidates(cell: Cell) -> list[int]:
        r, c = cell
        q = _quadrant_index(r, c)
        return [v for v in colors if v not in rows[r] and v not in cols[c] and v not in quads[q]]

    def backtrack() -> None:
        if len(solutions) >= max_solutions:
            return
        unfilled = [cell for cell in cells if cell not in assign]
        if not unfilled:
            solutions.append(dict(assign))
            return

        cell = min(unfilled, key=lambda x: (len(candidates(x)), x))
        for val in candidates(cell):
            r, c = cell
            q = _quadrant_index(r, c)
            assign[cell] = val
            rows[r].add(val)
            cols[c].add(val)
            quads[q].add(val)
            backtrack()
            quads[q].remove(val)
            cols[c].remove(val)
            rows[r].remove(val)
            del assign[cell]
            if len(solutions) >= max_solutions:
                return

    backtrack()
    return solutions


def _assignment_to_grid(assign: Dict[Cell, int]) -> Grid:
    grid = _empty()
    for (r, c), val in assign.items():
        grid[r][c] = val
    return grid


def transform_t46(grid: Grid) -> Grid:
    _check_gray_cross(grid)
    colors = _colors_from_grid(grid)
    givens = {(r, c): grid[r][c] for r, c in NON_GRAY_CELLS if grid[r][c] != BG}
    sols = _solve(colors, givens, max_solutions=2)
    if len(sols) != 1:
        raise ValueError("input does not have a unique valid completion")
    return _assignment_to_grid(sols[0])


def _canonical_solution(symbols: Sequence[int]) -> Dict[Cell, int]:
    """Return a random-symbolized 4x4 sudoku solution.

    Base pattern is a valid 4x4 Latin sudoku with 2x2 boxes:
        0 1 | 2 3
        2 3 | 0 1
        ---------
        1 0 | 3 2
        3 2 | 1 0
    """
    pattern = [
        [0, 1, 2, 3],
        [2, 3, 0, 1],
        [1, 0, 3, 2],
        [3, 2, 1, 0],
    ]
    real_rows = [0, 1, 3, 4]
    real_cols = [0, 1, 3, 4]
    return {
        (real_rows[i], real_cols[j]): symbols[pattern[i][j]]
        for i in range(4)
        for j in range(4)
    }


def _permute_solution(rng: random.Random, assign: Dict[Cell, int]) -> Dict[Cell, int]:
    # Permutations that preserve rows/columns/quadrants:
    # swap rows within top/bottom bands, swap bands, same for columns.
    row_bands = [[0, 1], [3, 4]]
    col_bands = [[0, 1], [3, 4]]
    for band in row_bands:
        if rng.random() < 0.5:
            band.reverse()
    for band in col_bands:
        if rng.random() < 0.5:
            band.reverse()
    if rng.random() < 0.5:
        row_bands.reverse()
    if rng.random() < 0.5:
        col_bands.reverse()
    row_map = dict(zip([0, 1, 3, 4], row_bands[0] + row_bands[1]))
    col_map = dict(zip([0, 1, 3, 4], col_bands[0] + col_bands[1]))
    return {(row_map[r], col_map[c]): v for (r, c), v in assign.items()}


def _choose_unique_givens(
    rng: random.Random,
    solution: Dict[Cell, int],
    colors: Sequence[int],
) -> Dict[Cell, int] | None:
    cells_by_color: dict[int, list[Cell]] = {c: [] for c in colors}
    for cell, val in solution.items():
        cells_by_color[val].append(cell)

    # One given per color. Try random choices until the completion is unique.
    for _ in range(2000):
        chosen: Dict[Cell, int] = {}
        for color in colors:
            cell = rng.choice(cells_by_color[color])
            chosen[cell] = color
        if len(chosen) != 4:
            continue
        if len({_quadrant_index(*cell) for cell in chosen}) < 3:
            continue
        sols = _solve(colors, chosen, max_solutions=2)
        if len(sols) == 1 and sols[0] == solution:
            return chosen
    return None


def generate(
    rng: random.Random | None = None,
    colors: Sequence[int] | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()
    for _attempt in range(1000):
        cols = list(colors) if colors is not None else rng.sample(PALETTE_COLORS, 4)
        if len(cols) != 4 or len(set(cols)) != 4 or GRAY in cols or BG in cols:
            continue

        rng.shuffle(cols)
        solution = _canonical_solution(cols)
        solution = _permute_solution(rng, solution)

        givens = _choose_unique_givens(rng, solution, cols)
        if givens is None:
            continue

        inp = _empty()
        for cell, val in givens.items():
            r, c = cell
            inp[r][c] = val
        out = _assignment_to_grid(solution)
        if transform_t46(inp) == out:
            return {"input": inp, "output": out}

    raise RuntimeError("failed to generate a valid t46 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t46 4-color sudoku quadrants rule."""

from __future__ import annotations

from typing import List

from generator import transform_t46

Grid = List[List[int]]


def verify_t46(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    if len(inp) != 5 or any(len(row) != 5 for row in inp):
        raise ValueError("input grid must be 5x5")
    return transform_t46(inp)

generator_py:
"""Generator for Test2/t47: XOR two halves separated by a gray line.

Rule:
- The input consists of two equal-size halves separated by a full gray (5) line.
- The halves share one background color.
- Each half has exactly one non-background foreground color.
- For each corresponding location, output:
    - the left/top foreground color if only the first half has foreground there;
    - the right/bottom foreground color if only the second half has foreground there;
    - 0 if neither or both halves have foreground there.

Generation constraints used to keep examples well-formed and unambiguous:
- exactly one full gray separator row or column is present;
- the separator splits the grid into two equal-size halves;
- both halves use the same background color;
- each half has exactly one distinct foreground color;
- both foreground colors are different from the background and gray;
- generated examples include cells of both foreground colors and some cancellations.
"""

from __future__ import annotations

import json
import random
from typing import List

Grid = List[List[int]]

BG_OUT = 0
GRAY = 5
COLORS = list(range(1, 10))


def _empty(h: int, w: int, color: int = BG_OUT) -> Grid:
    return [[color for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _find_separator(grid: Grid) -> tuple[str, int]:
    """Return ('vertical', col) or ('horizontal', row) for the unique gray separator."""
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    h, w = len(grid), len(grid[0])

    vertical = [c for c in range(w) if all(grid[r][c] == GRAY for r in range(h))]
    horizontal = [r for r in range(h) if all(grid[r][c] == GRAY for c in range(w))]

    candidates: list[tuple[str, int]] = []
    for c in vertical:
        if c > 0 and w - c - 1 == c:
            candidates.append(("vertical", c))
    for r in horizontal:
        if r > 0 and h - r - 1 == r:
            candidates.append(("horizontal", r))

    if len(candidates) != 1:
        raise ValueError("expected exactly one centered full gray separator")
    return candidates[0]


def _split_halves(grid: Grid) -> tuple[Grid, Grid]:
    kind, idx = _find_separator(grid)
    if kind == "vertical":
        left = [row[:idx] for row in grid]
        right = [row[idx + 1 :] for row in grid]
        return left, right

    top = grid[:idx]
    bottom = grid[idx + 1 :]
    return [row[:] for row in top], [row[:] for row in bottom]


def _infer_colors(a: Grid, b: Grid) -> tuple[int, int, int]:
    colors_a = {v for row in a for v in row}
    colors_b = {v for row in b for v in row}
    shared = (colors_a & colors_b) - {GRAY}
    if len(shared) != 1:
        raise ValueError("expected exactly one shared background color")
    bg = next(iter(shared))

    fg_a = sorted(colors_a - {bg, GRAY})
    fg_b = sorted(colors_b - {bg, GRAY})
    if len(fg_a) != 1 or len(fg_b) != 1:
        raise ValueError("expected exactly one foreground color per half")
    if fg_a[0] == fg_b[0]:
        raise ValueError("foreground colors should be distinct")
    return bg, fg_a[0], fg_b[0]


def transform_t47(grid: Grid) -> Grid:
    a, b = _split_halves(grid)
    h, w = len(a), len(a[0])
    if len(b) != h or len(b[0]) != w:
        raise ValueError("halves must have matching dimensions")

    bg, fg_a, fg_b = _infer_colors(a, b)
    out = _empty(h, w, BG_OUT)

    for r in range(h):
        for c in range(w):
            av = a[r][c]
            bv = b[r][c]
            if av not in (bg, fg_a) or bv not in (bg, fg_b):
                raise ValueError("unexpected color in half")
            has_a = av == fg_a
            has_b = bv == fg_b
            if has_a and not has_b:
                out[r][c] = fg_a
            elif has_b and not has_a:
                out[r][c] = fg_b
            else:
                out[r][c] = BG_OUT
    return out


def _render_vertical(a: Grid, b: Grid) -> Grid:
    return [ra + [GRAY] + rb for ra, rb in zip(a, b)]


def _render_horizontal(a: Grid, b: Grid) -> Grid:
    width = len(a[0])
    return [row[:] for row in a] + [[GRAY for _ in range(width)]] + [row[:] for row in b]


def _choose_colors(rng: random.Random) -> tuple[int, int, int]:
    bg = rng.choice([c for c in COLORS if c != GRAY])
    remaining = [c for c in COLORS if c not in (bg, GRAY)]
    fg_a, fg_b = rng.sample(remaining, 2)
    return bg, fg_a, fg_b


def _random_pattern(
    rng: random.Random,
    h: int,
    w: int,
    bg: int,
    fg_a: int,
    fg_b: int,
) -> tuple[Grid, Grid]:
    a = _empty(h, w, bg)
    b = _empty(h, w, bg)

    forced = ["a", "b", "both", "none"]
    cells = [(r, c) for r in range(h) for c in range(w)]
    rng.shuffle(cells)

    for state, (r, c) in zip(forced, cells):
        if state in ("a", "both"):
            a[r][c] = fg_a
        if state in ("b", "both"):
            b[r][c] = fg_b

    for r, c in cells[len(forced) :]:
        state = rng.choices(
            ["none", "a", "b", "both"],
            weights=[4, 5, 5, 3],
            k=1,
        )[0]
        if state in ("a", "both"):
            a[r][c] = fg_a
        if state in ("b", "both"):
            b[r][c] = fg_b

    return a, b


def generate(
    rng: random.Random | None = None,
    h: int | None = None,
    w: int | None = None,
    orientation: str | None = None,
    background: int | None = None,
    fg_a: int | None = None,
    fg_b: int | None = None,
) -> dict[str, Grid]:
    """Generate one valid ARC-style example."""
    rng = rng or random.Random()

    for _attempt in range(1000):
        hh = h if h is not None else rng.randint(3, 12)
        ww = w if w is not None else rng.randint(3, 12)
        if hh < 1 or ww < 1:
            continue

        if background is None or fg_a is None or fg_b is None:
            bg, ca, cb = _choose_colors(rng)
            if background is not None:
                bg = background
            if fg_a is not None:
                ca = fg_a
            if fg_b is not None:
                cb = fg_b
        else:
            bg, ca, cb = background, fg_a, fg_b

        if len({bg, ca, cb, GRAY}) != 4:
            continue

        a, b = _random_pattern(rng, hh, ww, bg, ca, cb)
        orient = orientation if orientation is not None else rng.choice(["vertical", "horizontal"])
        if orient == "vertical":
            inp = _render_vertical(a, b)
        elif orient == "horizontal":
            inp = _render_horizontal(a, b)
        else:
            raise ValueError("orientation must be 'vertical' or 'horizontal'")

        out = transform_t47(inp)
        out_colors = {v for row in out for v in row}
        both_count = sum(1 for r in range(hh) for c in range(ww) if a[r][c] == ca and b[r][c] == cb)
        neither_count = sum(1 for r in range(hh) for c in range(ww) if a[r][c] == bg and b[r][c] == bg)
        if ca in out_colors and cb in out_colors and BG_OUT in out_colors and both_count > 0 and neither_count > 0:
            return {"input": inp, "output": out}

    raise RuntimeError("failed to generate a valid t47 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t47 XOR-halves rule."""

from __future__ import annotations

from typing import List

from generator import transform_t47

Grid = List[List[int]]


def verify_t47(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t47(inp)

generator_py:
"""Generator for Test2/t48: uniquely completable four-color map coloring.

Rule:
- The last row begins with four palette colors.
- In the map area above, one boundary color (not in the palette) forms the map
  walls, enclosing several regions.
- Some regions are already colored with palette colors; at least one region is
  left uncolored (0).
- Complete the empty regions so that adjacent regions never share a color.

Generation constraints used to keep examples well-formed and unambiguous:
- exactly four distinct palette colors are shown in the bottom-left legend;
- exactly one distinct non-palette color is used as the boundary color;
- every interior region is a 4-connected component separated by 1-cell-thick
  boundary walls;
- the map contains at least one hidden region and at least two revealed regions;
- the completed map uses all four palette colors at least once;
- the partial coloring has exactly one valid completion;
- generated maps prefer irregular outer silhouettes rather than always using a
  full rectangular enclosure.
"""

from __future__ import annotations

import itertools
import json
import random
from typing import List, Sequence, Set, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]
CoarseCell = Tuple[int, int]

BG = 0
ALL_COLORS = list(range(1, 10))
NEI4 = [(-1, 0), (1, 0), (0, -1), (0, 1)]


# ---------------------------------------------------------------------------
# Generic transform / solver
# ---------------------------------------------------------------------------


def _empty(h: int, w: int) -> Grid:
    return [[0 for _ in range(w)] for _ in range(h)]


def _find_palette(grid: Grid) -> list[int]:
    if not grid or not grid[0]:
        raise ValueError("grid must be non-empty")
    palette = grid[-1][:4]
    if len(palette) != 4 or any(v == 0 for v in palette) or len(set(palette)) != 4:
        raise ValueError("bottom-left legend must contain four distinct nonzero colors")
    return list(palette)


def _find_boundary_color(grid: Grid, palette: Sequence[int]) -> int:
    colors = {v for row in grid[:-1] for v in row if v != 0}
    candidates = sorted(colors - set(palette))
    if len(candidates) != 1:
        raise ValueError("expected exactly one non-palette boundary color")
    return candidates[0]


def _components_non_boundary(grid: Grid, boundary_color: int) -> tuple[list[list[int]], list[set[Cell]]]:
    """Return component-id map and component cell sets for cells != boundary_color.

    Components include both interior regions and outer background; callers can
    decide which ones to use.
    """
    h, w = len(grid), len(grid[0])
    comp_id = [[-1 for _ in range(w)] for _ in range(h)]
    comps: list[set[Cell]] = []
    cid = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == boundary_color or comp_id[r][c] != -1:
                continue
            stack = [(r, c)]
            cells: set[Cell] = set()
            comp_id[r][c] = cid
            while stack:
                rr, cc = stack.pop()
                cells.add((rr, cc))
                for dr, dc in NEI4:
                    nr, nc = rr + dr, cc + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and grid[nr][nc] != boundary_color
                        and comp_id[nr][nc] == -1
                    ):
                        comp_id[nr][nc] = cid
                        stack.append((nr, nc))
            comps.append(cells)
            cid += 1
    return comp_id, comps


class ParsedMap:
    def __init__(
        self,
        palette: Sequence[int],
        boundary_color: int,
        regions: list[set[Cell]],
        region_colors: list[int],
        adjacency: list[set[int]],
    ) -> None:
        self.palette = list(palette)
        self.boundary_color = boundary_color
        self.regions = regions
        self.region_colors = region_colors
        self.adjacency = adjacency


def _parse_map(grid: Grid) -> ParsedMap:
    palette = _find_palette(grid)
    boundary = _find_boundary_color(grid, palette)
    map_grid = [row[:] for row in grid[:-1]]
    h, w = len(map_grid), len(map_grid[0])

    comp_id, comps = _components_non_boundary(map_grid, boundary)

    # Interior regions are the non-boundary components that do not touch the outer frame.
    region_ids: list[int] = []
    for cid, cells in enumerate(comps):
        touches_border = any(r == 0 or c == 0 or r == h - 1 or c == w - 1 for r, c in cells)
        if not touches_border:
            region_ids.append(cid)

    if not region_ids:
        raise ValueError("no interior map regions found")

    id_map = {cid: i for i, cid in enumerate(region_ids)}
    regions = [comps[cid] for cid in region_ids]
    region_colors: list[int] = []
    for cells in regions:
        vals = {map_grid[r][c] for r, c in cells}
        if len(vals) != 1:
            raise ValueError("each region must be monochrome or uncolored")
        v = next(iter(vals))
        if v != 0 and v not in palette:
            raise ValueError("region color must be 0 or a legend color")
        region_colors.append(v)

    adjacency: list[set[int]] = [set() for _ in regions]
    for r in range(h):
        for c in range(w):
            if map_grid[r][c] != boundary:
                continue
            neigh_ids: set[int] = set()
            for dr, dc in NEI4:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    cid = comp_id[nr][nc]
                    if cid in id_map:
                        neigh_ids.add(id_map[cid])
            neigh = sorted(neigh_ids)
            for i in range(len(neigh)):
                for j in range(i + 1, len(neigh)):
                    a, b = neigh[i], neigh[j]
                    adjacency[a].add(b)
                    adjacency[b].add(a)

    return ParsedMap(palette, boundary, regions, region_colors, adjacency)


def _solve_region_coloring(
    palette: Sequence[int],
    adjacency: Sequence[Set[int]],
    preset: Sequence[int],
    max_solutions: int = 2,
) -> list[list[int]]:
    n = len(adjacency)
    domains = [set(palette) for _ in range(n)]
    for i, v in enumerate(preset):
        if v != 0:
            if v not in palette:
                return []
            domains[i] = {v}

    for i in range(n):
        if len(domains[i]) == 1:
            vi = next(iter(domains[i]))
            for j in adjacency[i]:
                if i < j and len(domains[j]) == 1 and next(iter(domains[j])) == vi:
                    return []

    solutions: list[list[int]] = []
    assign = [0] * n

    def backtrack() -> None:
        if len(solutions) >= max_solutions:
            return
        unassigned = [i for i in range(n) if assign[i] == 0]
        if not unassigned:
            solutions.append(assign[:])
            return
        var = min(unassigned, key=lambda i: (len(domains[i]), -len(adjacency[i]), i))
        forbidden = {assign[j] for j in adjacency[var] if assign[j] != 0}
        choices = sorted(v for v in domains[var] if v not in forbidden)
        for v in choices:
            assign[var] = v
            backtrack()
            assign[var] = 0
            if len(solutions) >= max_solutions:
                return

    for i in range(n):
        if len(domains[i]) == 1:
            assign[i] = next(iter(domains[i]))

    for i in range(n):
        if assign[i] == 0:
            continue
        for j in adjacency[i]:
            if i < j and assign[j] == assign[i] != 0:
                return []

    backtrack()
    return solutions


def transform_t48(grid: Grid) -> Grid:
    parsed = _parse_map(grid)
    solutions = _solve_region_coloring(parsed.palette, parsed.adjacency, parsed.region_colors, max_solutions=2)
    if len(solutions) != 1:
        raise ValueError("input does not have a unique valid completion")
    sol = solutions[0]
    out = [row[:] for row in grid]
    for ridx, cells in enumerate(parsed.regions):
        color = sol[ridx]
        for r, c in cells:
            out[r][c] = color
    return out


# ---------------------------------------------------------------------------
# Generation helpers
# ---------------------------------------------------------------------------


def _shape_connected(shape: set[CoarseCell]) -> bool:
    if not shape:
        return False
    start = next(iter(shape))
    stack = [start]
    seen = {start}
    while stack:
        r, c = stack.pop()
        for dr, dc in NEI4:
            nb = (r + dr, c + dc)
            if nb in shape and nb not in seen:
                seen.add(nb)
                stack.append(nb)
    return len(seen) == len(shape)


def _shape_hole_free(shape: set[CoarseCell], coarse_h: int, coarse_w: int) -> bool:
    inactive = {(r, c) for r in range(coarse_h) for c in range(coarse_w) if (r, c) not in shape}
    if not inactive:
        return True
    stack = [cell for cell in inactive if cell[0] in (0, coarse_h - 1) or cell[1] in (0, coarse_w - 1)]
    seen = set(stack)
    while stack:
        r, c = stack.pop()
        for dr, dc in NEI4:
            nb = (r + dr, c + dc)
            if 0 <= nb[0] < coarse_h and 0 <= nb[1] < coarse_w and nb in inactive and nb not in seen:
                seen.add(nb)
                stack.append(nb)
    return seen == inactive


def _generate_shape(rng: random.Random, coarse_h: int, coarse_w: int, target_cells: int) -> set[CoarseCell] | None:
    all_cells = {(r, c) for r in range(coarse_h) for c in range(coarse_w)}
    start = (rng.randrange(coarse_h), rng.randrange(coarse_w))
    shape = {start}
    frontier = set()
    for dr, dc in NEI4:
        nr, nc = start[0] + dr, start[1] + dc
        if 0 <= nr < coarse_h and 0 <= nc < coarse_w:
            frontier.add((nr, nc))

    while len(shape) < target_cells and frontier:
        candidates = list(frontier)
        weighted: list[tuple[int, CoarseCell]] = []
        for cell in candidates:
            r, c = cell
            deg = sum((r + dr, c + dc) in shape for dr, dc in NEI4)
            score = 1 + 2 * deg
            # slight bias away from filling the whole bounding rectangle too early
            min_r = min(x for x, _ in shape | {cell})
            max_r = max(x for x, _ in shape | {cell})
            min_c = min(y for _, y in shape | {cell})
            max_c = max(y for _, y in shape | {cell})
            bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
            if bbox_area > len(shape) + 1:
                score += 1
            weighted.append((score, cell))
        total = sum(score for score, _ in weighted)
        pick = rng.randrange(total)
        acc = 0
        chosen = weighted[-1][1]
        for score, cell in weighted:
            acc += score
            if pick < acc:
                chosen = cell
                break
        shape.add(chosen)
        frontier.discard(chosen)
        r, c = chosen
        for dr, dc in NEI4:
            nr, nc = r + dr, c + dc
            if 0 <= nr < coarse_h and 0 <= nc < coarse_w and (nr, nc) not in shape:
                frontier.add((nr, nc))

    if len(shape) != target_cells:
        return None
    if not _shape_connected(shape):
        return None
    if not _shape_hole_free(shape, coarse_h, coarse_w):
        return None
    # Prefer irregular silhouettes when possible.
    min_r = min(r for r, _ in shape)
    max_r = max(r for r, _ in shape)
    min_c = min(c for _, c in shape)
    max_c = max(c for _, c in shape)
    bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
    if target_cells >= 5 and bbox_area == len(shape):
        return None
    return shape


def _partition_shape(
    rng: random.Random,
    coarse_h: int,
    coarse_w: int,
    shape: set[CoarseCell],
    target_regions: int,
) -> tuple[list[int], list[int], set[CoarseCell], list[list[int]], list[set[int]]]:
    """Create a merged partition on an irregular connected coarse shape."""
    active_cells = sorted(shape)
    idx_of = {cell: i for i, cell in enumerate(active_cells)}
    parent = list(range(len(active_cells)))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        parent[rb] = ra
        return True

    edges: list[tuple[int, int]] = []
    for r, c in active_cells:
        a = idx_of[(r, c)]
        for dr, dc in ((1, 0), (0, 1)):
            nb = (r + dr, c + dc)
            if nb in idx_of:
                edges.append((a, idx_of[nb]))
    rng.shuffle(edges)

    region_count = len(active_cells)
    for a, b in edges:
        if region_count <= target_regions:
            break
        if union(a, b):
            region_count -= 1

    root_to_region: dict[int, int] = {}
    region_of_cell = [[-1 for _ in range(coarse_w)] for _ in range(coarse_h)]
    next_id = 0
    for r, c in active_cells:
        root = find(idx_of[(r, c)])
        if root not in root_to_region:
            root_to_region[root] = next_id
            next_id += 1
        region_of_cell[r][c] = root_to_region[root]

    nregions = next_id
    adjacency = [set() for _ in range(nregions)]
    for r, c in active_cells:
        a = region_of_cell[r][c]
        for dr, dc in ((1, 0), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < coarse_h and 0 <= nc < coarse_w and region_of_cell[nr][nc] != -1:
                b = region_of_cell[nr][nc]
                if a != b:
                    adjacency[a].add(b)
                    adjacency[b].add(a)

    row_sizes = [rng.randint(2, 4) for _ in range(coarse_h)]
    col_sizes = [rng.randint(2, 4) for _ in range(coarse_w)]
    return row_sizes, col_sizes, shape, region_of_cell, adjacency


def _enumerate_full_colorings(
    palette: Sequence[int], adjacency: Sequence[Set[int]], max_solutions: int = 10000
) -> list[list[int]]:
    return _solve_region_coloring(palette, adjacency, [0] * len(adjacency), max_solutions=max_solutions)


def _choose_target_and_revealed(
    rng: random.Random,
    palette: Sequence[int],
    adjacency: Sequence[Set[int]],
) -> tuple[list[int], set[int]] | None:
    """Pick a full coloring and a reveal set with a unique completion."""
    n = len(adjacency)
    all_colorings = _enumerate_full_colorings(palette, adjacency, max_solutions=10000)
    if not all_colorings:
        return None
    good_targets = [col for col in all_colorings if set(col) == set(palette)]
    if not good_targets:
        return None
    rng.shuffle(good_targets)

    region_indices = list(range(n))
    hidden_sizes = [2, 3, 1] if n >= 5 else [1, 2]

    for target in good_targets:
        for hidden_size in hidden_sizes:
            if hidden_size <= 0 or hidden_size >= n:
                continue
            candidates = list(itertools.combinations(region_indices, hidden_size))
            rng.shuffle(candidates)
            for hidden in candidates:
                hidden_set = set(hidden)
                revealed = [i for i in region_indices if i not in hidden_set]
                if len(revealed) < 2:
                    continue
                filtered = [col for col in all_colorings if all(col[i] == target[i] for i in revealed)]
                if len(filtered) == 1:
                    return list(target), set(revealed)
    return None


def _render_partition(
    row_sizes: Sequence[int],
    col_sizes: Sequence[int],
    shape: set[CoarseCell],
    region_of_cell: Sequence[Sequence[int]],
    full_colors: Sequence[int],
    revealed: Set[int],
    boundary_color: int,
    palette: Sequence[int],
    top_margin: int,
    left_margin: int,
    right_margin: int,
    gap_above_legend: int,
) -> tuple[Grid, Grid]:
    coarse_h = len(row_sizes)
    coarse_w = len(col_sizes)
    map_h = sum(row_sizes) + coarse_h + 1
    map_w = sum(col_sizes) + coarse_w + 1
    total_h = top_margin + map_h + gap_above_legend + 1
    total_w = max(left_margin + map_w + right_margin, 4)

    inp = _empty(total_h, total_w)
    out = _empty(total_h, total_w)

    for c, v in enumerate(palette):
        inp[-1][c] = v
        out[-1][c] = v

    r0 = top_margin
    c0 = left_margin
    row_starts = []
    cur = r0 + 1
    for hs in row_sizes:
        row_starts.append(cur)
        cur += hs + 1
    col_starts = []
    cur = c0 + 1
    for ws in col_sizes:
        col_starts.append(cur)
        cur += ws + 1

    # Draw each active coarse cell as a local rectangle with walls.
    for rr, cc in sorted(shape):
        rid = region_of_cell[rr][cc]
        fill_in = full_colors[rid] if rid in revealed else 0
        fill_out = full_colors[rid]
        rs = row_starts[rr]
        cs = col_starts[cc]
        hs = row_sizes[rr]
        ws = col_sizes[cc]

        # Outer local box first (walls + interior).
        for r in range(rs - 1, rs + hs + 1):
            for c in range(cs - 1, cs + ws + 1):
                inp[r][c] = boundary_color
                out[r][c] = boundary_color

        # Interior.
        for r in range(rs, rs + hs):
            for c in range(cs, cs + ws):
                inp[r][c] = fill_in
                out[r][c] = fill_out

    # Remove walls between same-region neighboring active cells.
    for rr, cc in sorted(shape):
        rid = region_of_cell[rr][cc]
        fill_in = full_colors[rid] if rid in revealed else 0
        fill_out = full_colors[rid]
        rs = row_starts[rr]
        cs = col_starts[cc]
        hs = row_sizes[rr]
        ws = col_sizes[cc]
        if (rr + 1, cc) in shape and region_of_cell[rr + 1][cc] == rid:
            wall_r = rs + hs
            for c in range(cs, cs + ws):
                inp[wall_r][c] = fill_in
                out[wall_r][c] = fill_out
        if (rr, cc + 1) in shape and region_of_cell[rr][cc + 1] == rid:
            wall_c = cs + ws
            for r in range(rs, rs + hs):
                inp[r][wall_c] = fill_in
                out[r][wall_c] = fill_out

    return inp, out


def generate(
    rng: random.Random | None = None,
    h: int | None = None,
    w: int | None = None,
) -> dict[str, Grid]:
    rng = rng or random.Random()
    for _attempt in range(6000):
        boundary_color = rng.choice(ALL_COLORS)
        palette = rng.sample([c for c in ALL_COLORS if c != boundary_color], 4)

        coarse_h = rng.randint(3, 5)
        coarse_w = rng.randint(3, 5)
        max_cells = coarse_h * coarse_w
        min_cells = min(max_cells, 5)
        target_cells = rng.randint(min_cells, max_cells - 1 if max_cells >= 6 else max_cells)
        shape = _generate_shape(rng, coarse_h, coarse_w, target_cells)
        if shape is None:
            continue

        target_regions = rng.randint(4, min(len(shape), 8))
        row_sizes, col_sizes, shape, region_of_cell, adjacency = _partition_shape(
            rng, coarse_h, coarse_w, shape, target_regions
        )
        nregions = len(adjacency)
        if nregions < 4:
            continue

        chosen = _choose_target_and_revealed(rng, palette, adjacency)
        if chosen is None:
            continue
        full_colors, revealed = chosen
        if len(revealed) >= nregions or len(revealed) < 2:
            continue

        top_margin = rng.randint(0, 3)
        left_margin = rng.randint(0, 3)
        right_margin = rng.randint(0, 3)
        gap_above_legend = rng.randint(1, 2)

        inp, out = _render_partition(
            row_sizes,
            col_sizes,
            shape,
            region_of_cell,
            full_colors,
            revealed,
            boundary_color,
            palette,
            top_margin,
            left_margin,
            right_margin,
            gap_above_legend,
        )

        if h is not None or w is not None:
            hh = len(inp)
            ww = len(inp[0])
            target_h = h if h is not None else hh
            target_w = w if w is not None else ww
            if hh > target_h or ww > target_w:
                continue
            pad_top = rng.randint(0, target_h - hh)
            pad_left = rng.randint(0, target_w - ww)
            new_inp = _empty(target_h, target_w)
            new_out = _empty(target_h, target_w)
            for r in range(hh):
                for c in range(ww):
                    new_inp[pad_top + r][pad_left + c] = inp[r][c]
                    new_out[pad_top + r][pad_left + c] = out[r][c]
            inp, out = new_inp, new_out
            for c, v in enumerate(palette):
                inp[-1][c] = v
                out[-1][c] = v

        try:
            check = transform_t48(inp)
        except Exception:
            continue
        if check != out:
            continue
        return {"input": inp, "output": out}

    raise RuntimeError("failed to generate a valid t48 sample")


if __name__ == "__main__":
    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t48 uniquely completable four-color map coloring."""

from __future__ import annotations

from typing import List

from generator import transform_t48

Grid = List[List[int]]


def verify_t48(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t48(inp)

generator_py:
"""Generator for Test2/t49: aligned 2x2 nodes connected by an MST.

Rule:
- The input contains several 2x2 nodes, all in one non-black/non-gray color.
- Two nodes can be connected only when their 2x2 blocks have the same top row
  or the same left column.
- The weight of a valid connection is the gap distance between the two blocks,
  measured in cells between their facing edges.
- Draw a minimal spanning tree of the alignment graph using gray (5) cells.
  Corridors are two cells wide, matching the width/height of the 2x2 nodes.

Generation constraints used to keep examples unambiguous:
- every colored component is exactly a 2x2 node;
- the alignment graph is connected;
- the MST is unique;
- selected MST corridors do not pass through another colored node;
- at least one horizontal and one vertical MST edge appear when possible;
- default generation prefers richer multi-row / multi-column topologies rather
  than simple single-row / single-column chains.
"""

from __future__ import annotations

import random
from collections import Counter
from dataclasses import dataclass
from typing import List, Sequence, Tuple

Grid = List[List[int]]
Cell = Tuple[int, int]
Node = Tuple[int, int]  # top-left row, top-left col

BG = 0
GRAY = 5
NODE_COLORS = [1, 2, 3, 4, 6, 7, 8, 9]
NEI4 = [(-1, 0), (1, 0), (0, -1), (0, 1)]


@dataclass(frozen=True)
class Edge:
    weight: int
    a: int
    b: int


class DSU:
    def __init__(self, n: int):
        self.p = list(range(n))
        self.r = [0] * n

    def find(self, x: int) -> int:
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1
        return True


def _empty(h: int, w: int) -> Grid:
    return [[BG for _ in range(w)] for _ in range(h)]


def _rectangular(grid: Grid) -> bool:
    return bool(grid) and bool(grid[0]) and all(len(row) == len(grid[0]) for row in grid)


def _node_cells(node: Node) -> set[Cell]:
    r, c = node
    return {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}


def _touch_or_overlap(a: Node, b: Node) -> bool:
    # True when the two 2x2 blocks overlap or touch by a 4-neighbor edge.
    ar, ac = a
    br, bc = b
    return not (ar + 1 < br - 1 or br + 1 < ar - 1 or ac + 1 < bc - 1 or bc + 1 < ac - 1)


def _find_nodes(grid: Grid) -> tuple[int, list[Node]]:
    """Return (foreground color, sorted 2x2 node top-lefts)."""
    if not _rectangular(grid):
        raise ValueError("input grid must be non-empty and rectangular")
    colors = sorted({v for row in grid for v in row if v not in (BG, GRAY)})
    if len(colors) != 1:
        raise ValueError("expected exactly one non-gray foreground color")
    color = colors[0]
    h, w = len(grid), len(grid[0])
    seen: set[Cell] = set()
    nodes: list[Node] = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            stack = [(r, c)]
            comp: set[Cell] = set()
            while stack:
                rr, cc = stack.pop()
                if (rr, cc) in comp or grid[rr][cc] != color:
                    continue
                comp.add((rr, cc))
                for dr, dc in NEI4:
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in comp:
                        stack.append((nr, nc))
            seen |= comp
            if len(comp) != 4:
                raise ValueError("each foreground component must be a 2x2 node")
            rs = [rr for rr, _ in comp]
            cs = [cc for _, cc in comp]
            r0, c0 = min(rs), min(cs)
            if comp != _node_cells((r0, c0)):
                raise ValueError("each foreground component must be a filled 2x2 node")
            nodes.append((r0, c0))
    if not nodes:
        raise ValueError("expected at least one node")
    return color, sorted(nodes)


def _edge_weight(a: Node, b: Node) -> int | None:
    if a[0] == b[0]:
        return abs(a[1] - b[1]) - 2
    if a[1] == b[1]:
        return abs(a[0] - b[0]) - 2
    return None


def _edges(nodes: Sequence[Node]) -> list[Edge]:
    out: list[Edge] = []
    for i in range(len(nodes)):
        for j in range(i + 1, len(nodes)):
            wt = _edge_weight(nodes[i], nodes[j])
            if wt is not None and wt > 0:
                out.append(Edge(wt, i, j))
    return sorted(out, key=lambda e: (e.weight, nodes[e.a], nodes[e.b]))


def _mst_edges(nodes: Sequence[Node]) -> list[Edge]:
    dsu = DSU(len(nodes))
    chosen: list[Edge] = []
    for e in _edges(nodes):
        if dsu.union(e.a, e.b):
            chosen.append(e)
            if len(chosen) == len(nodes) - 1:
                break
    if len(nodes) > 1 and len(chosen) != len(nodes) - 1:
        raise ValueError("alignment graph is disconnected")
    return chosen


def _has_unique_mst(nodes: Sequence[Node]) -> bool:
    """Kruskal uniqueness test: each equal-weight group must be acyclic after contraction."""
    edges = _edges(nodes)
    if len(nodes) <= 1:
        return True
    if len(_mst_edges(nodes)) != len(nodes) - 1:
        return False
    dsu = DSU(len(nodes))
    i = 0
    while i < len(edges):
        wt = edges[i].weight
        group: list[Edge] = []
        while i < len(edges) and edges[i].weight == wt:
            group.append(edges[i])
            i += 1
        temp = DSU(len(nodes))
        for e in group:
            a, b = dsu.find(e.a), dsu.find(e.b)
            if a == b:
                continue
            if not temp.union(a, b):
                return False
        for e in group:
            dsu.union(e.a, e.b)
    return True


def _corridor_cells(a: Node, b: Node) -> list[Cell]:
    ar, ac = a
    br, bc = b
    cells: list[Cell] = []
    if ar == br:
        lo, hi = sorted((ac, bc))
        for c in range(lo + 2, hi):
            cells.append((ar, c))
            cells.append((ar + 1, c))
    elif ac == bc:
        lo, hi = sorted((ar, br))
        for r in range(lo + 2, hi):
            cells.append((r, ac))
            cells.append((r, ac + 1))
    else:
        raise ValueError("nodes are not aligned")
    return cells


def _corridor_clear(nodes: Sequence[Node], e: Edge) -> bool:
    occupied: set[Cell] = set()
    for k, n in enumerate(nodes):
        if k not in (e.a, e.b):
            occupied |= _node_cells(n)
    return all(cell not in occupied for cell in _corridor_cells(nodes[e.a], nodes[e.b]))


def transform_t49(grid: Grid) -> Grid:
    """Draw the gray minimal-spanning tree between aligned 2x2 nodes."""
    _color, nodes = _find_nodes(grid)
    h, w = len(grid), len(grid[0])
    out = [list(row) for row in grid]
    for e in _mst_edges(nodes):
        for r, c in _corridor_cells(nodes[e.a], nodes[e.b]):
            if 0 <= r < h and 0 <= c < w and out[r][c] == BG:
                out[r][c] = GRAY
    return out


def _alignment_connected(nodes: Sequence[Node]) -> bool:
    if not nodes:
        return False
    dsu = DSU(len(nodes))
    for e in _edges(nodes):
        dsu.union(e.a, e.b)
    root = dsu.find(0)
    return all(dsu.find(i) == root for i in range(len(nodes)))


def _alignment_edge_count(nodes: Sequence[Node]) -> int:
    return len(_edges(nodes))


def _rich_structure(nodes: Sequence[Node]) -> bool:
    """Prefer nontrivial multi-row / multi-column graphs for default generation."""
    n = len(nodes)
    rows = Counter(r for r, _ in nodes)
    cols = Counter(c for _, c in nodes)
    dr = len(rows)
    dc = len(cols)
    repeated_rows = sum(v >= 2 for v in rows.values())
    repeated_cols = sum(v >= 2 for v in cols.values())
    ecount = _alignment_edge_count(nodes)

    if n >= 6:
        return dr >= 3 and dc >= 3 and repeated_rows >= 2 and repeated_cols >= 2 and ecount >= n
    if n == 5:
        return dr >= 3 and dc >= 3 and repeated_rows >= 2 and repeated_cols >= 2 and ecount >= n - 1
    if n == 4:
        return dr >= 2 and dc >= 2 and repeated_rows >= 1 and repeated_cols >= 1 and ecount >= n - 1
    return dr >= 2 and dc >= 2


def _valid_nodes(nodes: Sequence[Node], h: int, w: int, *, prefer_rich: bool = False) -> bool:
    if len(set(nodes)) != len(nodes):
        return False
    for r, c in nodes:
        if r < 0 or c < 0 or r + 1 >= h or c + 1 >= w:
            return False
    for i in range(len(nodes)):
        for j in range(i + 1, len(nodes)):
            if _touch_or_overlap(nodes[i], nodes[j]):
                return False
    if not _alignment_connected(nodes):
        return False
    try:
        mst = _mst_edges(nodes)
    except ValueError:
        return False
    if not _has_unique_mst(nodes):
        return False
    if not all(_corridor_clear(nodes, e) for e in mst):
        return False
    if len(nodes) >= 4:
        has_h = any(nodes[e.a][0] == nodes[e.b][0] for e in mst)
        has_v = any(nodes[e.a][1] == nodes[e.b][1] for e in mst)
        if not (has_h and has_v):
            return False
    if prefer_rich and not _rich_structure(nodes):
        return False
    return True


def _render(h: int, w: int, nodes: Sequence[Node], color: int) -> Grid:
    grid = _empty(h, w)
    for r, c in nodes:
        for rr, cc in _node_cells((r, c)):
            grid[rr][cc] = color
    return grid


def _sample_axis_positions(rng: random.Random, limit: int, count: int) -> list[int] | None:
    """Sample top-left coordinates with >=3 spacing so same-line nodes never touch."""
    vals = list(range(0, max(0, limit - 1)))
    rng.shuffle(vals)
    chosen: list[int] = []
    for v in vals:
        if all(abs(v - u) >= 3 for u in chosen):
            chosen.append(v)
            if len(chosen) == count:
                return sorted(chosen)
    return None


def _grow_nodes_on_lattice(
    rng: random.Random,
    rows: Sequence[int],
    cols: Sequence[int],
    n: int,
) -> list[Node] | None:
    """Grow a connected set of intersections, biased toward richer topology."""
    if not rows or not cols or n <= 0:
        return None

    nodes: set[Node] = set()
    used_rows: set[int] = set()
    used_cols: set[int] = set()

    # Seed with a 2x2 rectangle whenever possible to discourage simple chains.
    if n >= 4 and len(rows) >= 2 and len(cols) >= 2:
        rs = rng.sample(list(rows), 2)
        cs = rng.sample(list(cols), 2)
        for r in rs:
            for c in cs:
                nodes.add((r, c))
        used_rows.update(rs)
        used_cols.update(cs)
    else:
        start = (rng.choice(list(rows)), rng.choice(list(cols)))
        nodes.add(start)
        used_rows.add(start[0])
        used_cols.add(start[1])

    while len(nodes) < n:
        candidates: list[tuple[int, Node]] = []
        for r in rows:
            for c in cols:
                cand = (r, c)
                if cand in nodes:
                    continue
                if r not in used_rows and c not in used_cols:
                    continue  # would disconnect the alignment graph
                row_count = sum(rr == r for rr, _ in nodes)
                col_count = sum(cc == c for _, cc in nodes)
                introduces = int(r not in used_rows) + int(c not in used_cols)

                # Weighted preference:
                # - new row xor new col expands the graph,
                # - existing row and existing col densifies it and adds extra alignments,
                # - candidates on already-populated lines are favored for richer graphs.
                if introduces == 1:
                    score = 4 + row_count + col_count
                else:
                    score = 6 + 2 * row_count + 2 * col_count
                candidates.append((score, cand))
        if not candidates:
            return None
        total = sum(score for score, _ in candidates)
        pick = rng.randrange(total)
        acc = 0
        chosen = candidates[-1][1]
        for score, cand in candidates:
            acc += score
            if pick < acc:
                chosen = cand
                break
        nodes.add(chosen)
        used_rows.add(chosen[0])
        used_cols.add(chosen[1])

    return sorted(nodes)


def _sample_rich_nodes(rng: random.Random, h: int, w: int, n: int) -> list[Node] | None:
    max_rows = max(1, (h + 1) // 3)
    max_cols = max(1, (w + 1) // 3)
    if n >= 6:
        row_count = min(max_rows, rng.randint(3, min(4, n - 1, max_rows)))
        col_count = min(max_cols, rng.randint(3, min(4, n - 1, max_cols)))
    elif n == 5:
        row_count = min(max_rows, rng.randint(3, min(4, max_rows)))
        col_count = min(max_cols, rng.randint(3, min(4, max_cols)))
    elif n == 4:
        row_count = min(max_rows, rng.randint(2, min(3, max_rows)))
        col_count = min(max_cols, rng.randint(2, min(3, max_cols)))
    else:
        row_count = min(max_rows, rng.randint(2, min(3, max_rows)))
        col_count = min(max_cols, rng.randint(2, min(3, max_cols)))

    if row_count < 2 or col_count < 2:
        return None
    rows = _sample_axis_positions(rng, h, row_count)
    cols = _sample_axis_positions(rng, w, col_count)
    if rows is None or cols is None:
        return None
    if row_count * col_count < n:
        return None
    return _grow_nodes_on_lattice(rng, rows, cols, n)


def _sample_basic_nodes(rng: random.Random, h: int, w: int, n: int) -> list[Node] | None:
    start = (rng.randint(0, h - 2), rng.randint(0, w - 2))
    nodes = [start]
    for _ in range(n - 1):
        base = rng.choice(nodes)
        br, bc = base
        dirs = ["left", "right", "up", "down"]
        rng.shuffle(dirs)
        cand: Node | None = None
        for direction in dirs:
            if direction in ("left", "right"):
                max_gap = (bc - 2) if direction == "left" else (w - (bc + 2) - 2)
            else:
                max_gap = (br - 2) if direction == "up" else (h - (br + 2) - 2)
            if max_gap < 1:
                continue
            gaps = list(range(1, max_gap + 1))
            rng.shuffle(gaps)
            for gap in gaps:
                if direction == "left":
                    trial = (br, bc - gap - 2)
                elif direction == "right":
                    trial = (br, bc + gap + 2)
                elif direction == "up":
                    trial = (br - gap - 2, bc)
                else:
                    trial = (br + gap + 2, bc)
                if all(not _touch_or_overlap(trial, existing) for existing in nodes):
                    cand = trial
                    break
            if cand is not None:
                break
        if cand is None:
            return None
        nodes.append(cand)
    return sorted(nodes)


def generate(
    rng: random.Random | None = None,
    h: int | None = None,
    w: int | None = None,
    num_nodes: int | None = None,
    color: int | None = None,
) -> dict[str, Grid]:
    """Generate one valid ARC-style example."""
    rng = rng or random.Random()
    for attempt in range(6000):
        hh = h if h is not None else rng.randint(11, 30)
        ww = w if w is not None else rng.randint(11, 30)
        if hh < 5 or ww < 5:
            continue

        max_nodes = min(10, max(4, (hh * ww) // 28))
        min_nodes = 4 if min(hh, ww) < 13 else 5
        n = num_nodes if num_nodes is not None else rng.randint(min_nodes, max_nodes)
        col = color if color is not None else rng.choice(NODE_COLORS)

        # Prefer richer lattice-grown structures; occasionally fall back to a
        # simpler construction so the task family still covers a range of cases.
        use_rich = attempt < 5000 and (num_nodes is None or n >= 4)
        nodes = _sample_rich_nodes(rng, hh, ww, n) if use_rich else _sample_basic_nodes(rng, hh, ww, n)
        if nodes is None:
            continue
        if not _valid_nodes(nodes, hh, ww, prefer_rich=use_rich):
            continue

        inp = _render(hh, ww, nodes, col)
        out = transform_t49(inp)
        return {"input": inp, "output": out}
    raise RuntimeError("failed to generate a valid t49 sample")


if __name__ == "__main__":
    import json

    print(json.dumps(generate(rng=random.Random(0)), indent=2))

verifier_py:
"""Verifier for Test2/t49 aligned-node minimal-spanning-tree rule."""

from __future__ import annotations

from typing import List

from generator import transform_t49

Grid = List[List[int]]


def verify_t49(inp: Grid) -> Grid:
    if not inp or not inp[0]:
        raise ValueError("input grid must be non-empty")
    w = len(inp[0])
    if any(len(row) != w for row in inp):
        raise ValueError("ragged input grid")
    return transform_t49(inp)
